function validateProject(project) {
  if (!project || typeof project !== 'object') {
    throw new TypeError('paths() expects a project descriptor object');
  }
  const { root, name, version } = project;
  for (const field of ['root', 'name', 'version']) {
    if (typeof project[field] !== 'string' || project[field].trim() === '') {
      throw new TypeError(`project.${field} must be a non-empty string`);
    }
  }
  return { root: root.replace(/\/+$/, ''), name: name.trim(), version: version.trim() };
}

function paths(project) {
  const { root, name, version } = validateProject(project);

  const sourceDir = `${root}/source`;
  const buildDir = `${root}/build`;
  const assetsDir = `${root}/public`;
  const indexHtml = `${assetsDir}/index.html`;
  const styleSheet = `${assetsDir}/style.css`;
  const configJson = `${root}/${name}.config.json`;
  const readmeFile = `${root}/${name}-${version}.md`;
  const logFile = `${root}/logs/${name}.log`;

  return [
    sourceDir,
    buildDir,
    assetsDir,
    indexHtml,
    styleSheet,
    configJson,
    readmeFile,
    logFile,
  ];
}

function classify(path) {
  const leaf = path.slice(path.lastIndexOf('/') + 1);
  const dot = leaf.lastIndexOf('.');
  if (dot <= 0) {
    return 'directory';
  }
  return `${leaf.slice(dot + 1)} file`;
}

function describe(project) {
  const generated = paths(project);
  const header = `Layout for ${project.name} v${project.version}`;
  const lines = [header, '-'.repeat(header.length)];

  generated.forEach((path, index) => {
    const label = String(index + 1).padStart(2, '0');
    lines.push(`${label}. ${path}  [${classify(path)}]`);
  });

  lines.push(`total entries: ${generated.length}`);
  return lines.join('\n');
}

function main() {
  const projects = [
    { root: '/srv/apps/ledger/', name: 'ledger', version: '2.4.0' },
    { root: '/home/dev/kiosk', name: 'kiosk-ui', version: '0.9.1-beta' },
  ];

  for (const project of projects) {
    console.log(describe(project));
    console.log('');
  }

  try {
    paths({ root: '/tmp', name: '', version: '1.0.0' });
  } catch (error) {
    console.log(`rejected invalid descriptor: ${error.message}`);
  }
}

main();

module.exports = { paths, describe, classify };

