function validateConfig(config) {
  const required = ['baseImage', 'maintainer', 'appDir', 'envVar', 'port', 'startCommand', 'package'];
  const missing = required.filter((key) => !config[key]);
  if (missing.length > 0) {
    throw new Error(`Incomplete build config, missing: ${missing.join(', ')}`);
  }
  const port = Number(config.port);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error(`Exposed port must be between 1 and 65535, got ${config.port}`);
  }
  return { ...config, port };
}

function dockerfile(config) {
  const cfg = validateConfig(config);
  const from = `FROM ${cfg.baseImage}`;
  const maintainer = `LABEL maintainer="${cfg.maintainer}"`;
  const workdir = `WORKDIR ${cfg.appDir}`;
  const env = `ENV ${cfg.envVar}=production`;
  const run = `RUN apt-get update && apt-get install -y ${cfg.package}`;
  const copy = `COPY . ${cfg.appDir}`;
  const expose = `EXPOSE ${cfg.port}`;
  const cmd = `CMD ["${cfg.startCommand}"]`;
  return [from, maintainer, workdir, env, run, copy, expose, cmd];
}

function renderDockerfile(config) {
  return `${dockerfile(config).join('\n')}\n`;
}

function describeBuild(config) {
  const cfg = validateConfig(config);
  const image = `${cfg.baseImage.split(':')[0]}-app`;
  return [
    `Image name: ${image}`,
    `Base: ${cfg.baseImage}`,
    `Serving on port ${cfg.port}`,
    `Start command: ${cfg.startCommand}`,
    `Extra package: ${cfg.package}`,
  ];
}

function buildCommand(config, tag) {
  const cfg = validateConfig(config);
  const label = tag || `${cfg.maintainer.toLowerCase().replace(/\s+/g, '-')}/app:latest`;
  return `docker build -t ${label} .`;
}

function main() {
  const config = {
    baseImage: 'node:20-alpine',
    maintainer: 'Ada Lovelace',
    appDir: '/usr/src/app',
    envVar: 'NODE_ENV',
    port: 8080,
    startCommand: 'npm start',
    package: 'curl',
  };

  const lines = dockerfile(config);
  console.log(`Generated ${lines.length} instructions:`);
  console.log(renderDockerfile(config));

  for (const line of describeBuild(config)) {
    console.log(`  - ${line}`);
  }
  console.log(`Next step: ${buildCommand(config, 'registry.local/web:1.0')}`);
}

main();

module.exports = { dockerfile, renderDockerfile, describeBuild, buildCommand };

