function normalizeTheme(theme) {
  const required = [
    'primaryColor',
    'secondaryColor',
    'baseFontSize',
    'headingFontSize',
    'marginSize',
    'paddingSize',
    'borderRadius'
  ];
  const missing = required.filter((key) => theme[key] === undefined);
  if (missing.length > 0) {
    throw new Error(`Theme is missing properties: ${missing.join(', ')}`);
  }
  return required.reduce((acc, key) => {
    acc[key] = typeof theme[key] === 'number' ? `${theme[key]}px` : String(theme[key]);
    return acc;
  }, {});
}

function colorValue(raw) {
  const trimmed = raw.trim();
  return /^[0-9a-f]{3}([0-9a-f]{3})?$/i.test(trimmed) ? `#${trimmed}` : trimmed;
}

function stylesheet(theme) {
  const t = normalizeTheme(theme);
  const primary = colorValue(t.primaryColor);
  const secondary = colorValue(t.secondaryColor);

  const bodyBackground = `body { background-color: ${primary}; }`;
  const bodyColor = `body { color: ${secondary}; }`;
  const paragraphSize = `p { font-size: ${t.baseFontSize}; }`;
  const headingSize = `h1, h2, h3 { font-size: ${t.headingFontSize}; }`;
  const containerMargin = `.container { margin: ${t.marginSize}; }`;
  const containerPadding = `.container { padding: ${t.paddingSize}; }`;
  const buttonRadius = `button { border-radius: ${t.borderRadius}; }`;
  const buttonHover = `button:hover { background-color: ${primary}; }`;

  return [
    bodyBackground,
    bodyColor,
    paragraphSize,
    headingSize,
    containerMargin,
    containerPadding,
    buttonRadius,
    buttonHover
  ];
}

function renderStylesheet(theme, indent = 0) {
  const pad = ' '.repeat(indent);
  return stylesheet(theme)
    .map((rule) => `${pad}${rule}`)
    .join('\n');
}

function main() {
