  console.log(`/* generated ${rules.length} rules */`);
  console.log(renderStylesheet(theme, 2));

  try {
    stylesheet({ primaryColor: 'red' });
  } catch (err) {
    console.log(`Validation failed: ${err.message}`);
  }
}

main();

