function escapeText(text) {
  return String(text).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function validateNetwork(network) {
  if (!network || typeof network.name !== 'string' || network.name.length === 0) {
    throw new Error('a graph name is required');
  }
  const known = new Set();
  for (const node of network.nodes) {
    if (known.has(node.identifier)) {
      throw new Error(`duplicate node identifier: ${node.identifier}`);
    }
    known.add(node.identifier);
  }
  for (const edge of network.edges) {
    if (!known.has(edge.source)) {
      throw new Error(`edge starts at unknown node: ${edge.source}`);
    }
    if (!known.has(edge.destination)) {
      throw new Error(`edge ends at unknown node: ${edge.destination}`);
    }
  }
  return known;
}

function graph(network) {
  validateNetwork(network);
  const defaultShape = 'circle';
  const defaultColor = 'blue';
  const lines = [];
  lines.push(`digraph ${network.name} {`);
  lines.push(`  node [shape=${defaultShape}];`);
  lines.push(`  edge [color=${defaultColor}];`);
  for (const node of network.nodes) {
    const labelAttribute = `label="${escapeText(node.label)}"`;
    lines.push(`  ${node.identifier} [${labelAttribute}];`);
  }
  for (const edge of network.edges) {
    const connection = `  ${edge.source} -> ${edge.destination}`;
    const weightAttribute = `label="${escapeText(edge.weight)}"`;
    lines.push(`${connection} [${weightAttribute}];`);
  }
  lines.push('}');
  lines.push(`// ${network.nodes.length} nodes and ${network.edges.length} edges`);
  return lines;
}

function render(lines) {
  return lines.join('\n');
}

function main() {
  const network = {
    name: 'routes',
    nodes: [
      { identifier: 'a', label: 'Amsterdam' },
      { identifier: 'b', label: 'Berlin' },
      { identifier: 'c', label: 'Copenhagen' }
    ],
    edges: [
      { source: 'a', destination: 'b', weight: 577 },
      { source: 'b', destination: 'c', weight: 354 },
      { source: 'c', destination: 'a', weight: 755 }
    ]
  };
  console.log(render(graph(network)));
  const broken = { name: 'broken', nodes: network.nodes, edges: [{ source: 'a', destination: 'z', weight: 1 }] };
  try {
    graph(broken);
  } catch (error) {
    console.error(`could not build graph: ${error.message}`);
  }
}

main();

