function fullNameOf(student) {
  return `${student.firstName} ${student.lastName}`;
}

function evaluate(gpa) {
  if (gpa >= 3.5) return 'excellent standing';
  if (gpa >= 2.5) return 'good standing';
  if (gpa >= 2.0) return 'satisfactory standing';
  return 'academic probation';
}

function readGpa(student, index) {
  if (typeof student !== 'object' || student === null) {
    throw new TypeError(`Record at position ${index} is not a student object`);
  }
  const gpa = Number(student.gpa);
  if (Number.isNaN(gpa)) {
    throw new RangeError(`Record ${student.id} has an unreadable grade point average`);
  }
  return gpa;
}

const registry = {
  export(records) {
    const lines = [];
    lines.push(`Student Report — ${records.length} record(s) on file`);
    lines.push(`${'ID'.padEnd(8)}${'NAME'.padEnd(24)}${'LEVEL'.padEnd(12)}GPA`);
    lines.push('-'.repeat(52));

    records.forEach((student, index) => {
      const gpa = readGpa(student, index);
      const fullName = fullNameOf(student);
      const summaryRow = `${String(student.id).padEnd(8)}${fullName.padEnd(24)}`;
      lines.push(`${summaryRow}${String(student.gradeLevel).padEnd(12)}${gpa.toFixed(2)}`);
      lines.push(`  ${fullName} holds a GPA of ${gpa.toFixed(2)} and is in ${evaluate(gpa)}.`);
    });

    lines.push('-'.repeat(52));
    lines.push(`Total students processed: ${records.length}`);
    lines.push(`Report generated in ${new Date().getFullYear()}`);
    return lines;
  }
};

function averageGpa(records) {
  const total = records.reduce((sum, student) => sum + Number(student.gpa), 0);
  return records.length ? total / records.length : 0;
}

function main() {
  const roster = [
    { id: 'S1001', firstName: 'Ada', lastName: 'Lovelace', gradeLevel: 'Senior', gpa: 3.92 },
    { id: 'S1002', firstName: 'Alan', lastName: 'Turing', gradeLevel: 'Junior', gpa: 3.14 },
    { id: 'S1003', firstName: 'Grace', lastName: 'Hopper', gradeLevel: 'Sophomore', gpa: 2.35 },
    { id: 'S1004', firstName: 'Linus', lastName: 'Pauling', gradeLevel: 'Freshman', gpa: 1.87 }
  ];

  try {
    const report = registry.export(roster);
    report.forEach((line) => console.log(line));
    console.log(`Cohort average GPA: ${averageGpa(roster).toFixed(2)}`);
  } catch (err) {
    console.error(`Report aborted: ${err.message}`);
  }
}

main();

module.exports = { registry, fullNameOf, evaluate, averageGpa };

