const XML_ESCAPES = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&apos;',
};

function escapeXml(value) {
  return String(value).replace(/[&<>"']/g, (ch) => XML_ESCAPES[ch]);
}

function rfc822(date) {
  const parsed = date instanceof Date ? date : new Date(date);
  if (Number.isNaN(parsed.getTime())) {
    throw new TypeError(`Invalid post date: ${date}`);
  }
  return parsed.toUTCString();
}

function requireField(channel, field) {
  const value = channel[field];
  if (typeof value !== 'string' || value.trim() === '') {
    throw new TypeError(`Channel is missing a usable "${field}" value`);
  }
  return value.trim();
}

function feed(channel) {
  const title = requireField(channel, 'title');
  const link = requireField(channel, 'link');
  const description = requireField(channel, 'description');
  const author = requireField(channel, 'author');
  const posts = Array.isArray(channel.posts) ? channel.posts : [];

  const tags = ['<?xml version="1.0" encoding="UTF-8"?>'];
  tags.push('<rss version="2.0">');
  tags.push('<channel>');
  tags.push(`  <title>${escapeXml(title)}</title>`);
  tags.push(`  <link>${escapeXml(link)}</link>`);
  tags.push(`  <description>${escapeXml(description)}</description>`);

  posts.forEach((post, index) => {
    if (!post || typeof post.title !== 'string') {
      throw new TypeError(`Post at index ${index} has no title`);
    }
    tags.push('  <item>');
    tags.push(`    <title>${escapeXml(post.title)}</title>`);
    tags.push(`    <link>${escapeXml(post.link)}</link>`);
    tags.push(`    <pubDate>${rfc822(post.date)}</pubDate>`);
    tags.push('  </item>');
  });

  tags.push(`  <!-- feed maintained by ${escapeXml(author)} -->`);
  tags.push('</channel>');
  tags.push('</rss>');
  return tags;
}

function render(channel) {
  return feed(channel).join('\n');
}

const blog = {
  title: 'Wheels & Gears',
  link: 'https://example.com/blog',
  description: 'Notes on bicycles, tools, and long rides.',
  author: 'Dana Ruiz',
  posts: [
    { title: 'Truing a wobbly wheel', link: 'https://example.com/blog/truing', date: '2026-03-02T08:15:00Z' },
    { title: 'Why I ride <slowly>', link: 'https://example.com/blog/slowly', date: '2026-04-11T17:40:00Z' },
  ],
};

const document = render(blog);
console.log(document);
console.log(`Generated ${feed(blog).length} tags for "${blog.title}"`);

module.exports = { feed, render, escapeXml };

