function describeTarget({ module, fn }) {
  return `${module}.${fn}()`;
}

function formatValue(value) {
  if (typeof value === 'string') {
    return `"${value}"`;
  }
  if (value === null || value === undefined) {
    return String(value);
  }
  if (typeof value === 'object') {
    return JSON.stringify(value);
  }
  return `${value}`;
}

function describeDifference(expected, actual) {
  if (typeof expected === 'number' && typeof actual === 'number') {
    return `numeric drift of ${actual - expected}`;
  }
  if (typeof expected !== typeof actual) {
    return `type mismatch: ${typeof expected} vs ${typeof actual}`;
  }
  return `values differ: ${formatValue(expected)} != ${formatValue(actual)}`;
}

function assert(test) {
  const { module, fn, expected, actual, time, error } = test;
  if (!module || !fn) {
    throw new Error(`assert() requires both a module and a function name, got ${describeTarget(test)}`);
  }

  const messages = [];
  messages.push(`FAILURE: ${describeTarget(test)} did not pass`);
  messages.push(`Expected value: ${formatValue(expected)}`);
  messages.push(`Actual value: ${formatValue(actual)}`);
  messages.push(`Difference: ${describeDifference(expected, actual)}`);
  messages.push(`Warning: execution took ${time} ms`);
  messages.push(`Error type thrown: ${error}`);
  messages.push(`Stack trace for ${fn}:`);
  messages.push(`Please review the documentation for module "${module}".`);
  return messages;
}

function report(tests) {
  const lines = [];
  tests.forEach((test, index) => {
    lines.push(`--- Test #${index + 1} ---`);
    for (const message of assert(test)) {
      lines.push(`  ${message}`);
    }
  });
  lines.push(`${tests.length} failing test(s) reported.`);
  return lines.join('\n');
}

const failures = [
  { module: 'math', fn: 'divide', expected: 2.5, actual: 2, time: 412, error: 'RangeError' },
  { module: 'strings', fn: 'slugify', expected: 'hello-world', actual: 'Hello World', time: 18, error: 'TypeError' },
  { module: 'parser', fn: 'parse', expected: { ok: true }, actual: null, time: 1204, error: 'SyntaxError' }
];

console.log(report(failures));

module.exports = { assert, report, formatValue, describeDifference, describeTarget };

