const PAD = '  ';
const L1 = PAD;
const L2 = PAD.repeat(2);
const L3 = PAD.repeat(3);
const L4 = PAD.repeat(4);

function formatVersionHeader(version) {
  const versionLine = L1 + `"Version": "${version}",`;
  const statementOpen = L1 + '"Statement": [';
  return ['{', versionLine, statementOpen];
}

function validateRule(rule, index) {
  if (typeof rule.resource !== 'string' || rule.resource.length === 0) {
    throw new TypeError(`Rule ${index} is missing a resource string`);
  }
  if (!Array.isArray(rule.actions) || rule.actions.length === 0) {
    throw new TypeError(`Rule for ${rule.resource} must list at least one action`);
  }
  if (rule.effect !== 'Allow' && rule.effect !== 'Deny') {
    throw new TypeError(`Rule ${index} declares an effect that is neither Allow nor Deny`);
  }
}

function formatActionItems(actions) {
  return actions.map((action, i) => {
    const comma = i < actions.length - 1 ? ',' : '';
    const quoted = `"${action}"`;
    return L4 + quoted + comma;
  });
}

function formatStatement(rule, index, isLast) {
  validateRule(rule, index);
  const lines = [L2 + '{'];
  lines.push(L3 + `"Sid": "Stmt${index + 1}",`);
  lines.push(L3 + `"Effect": "${rule.effect}",`);
  lines.push(L3 + '"Action": [');
  for (const item of formatActionItems(rule.actions)) {
    lines.push(item);
  }
  lines.push(L3 + '],');
  lines.push(L3 + `"Resource": "${rule.resource}"`);
  lines.push(L2 + '}' + (isLast ? '' : ','));
  return lines;
}

function policy(rules) {
  if (!Array.isArray(rules)) {
    throw new TypeError(`policy() expects a list of rules, received ${typeof rules}`);
  }
  const lines = formatVersionHeader('2012-10-17');
  rules.forEach((rule, i) => {
    for (const line of formatStatement(rule, i, i === rules.length - 1)) {
      lines.push(line);
    }
  });
  lines.push(L1 + ']');
  lines.push('}');
  return lines.join('\n');
}

const demoRules = [
  {
    resource: 'arn:aws:s3:::object-bucket/*',
    actions: ['s3:GetObject', 's3:ListBucket'],
    effect: 'Allow'
  }
];

console.log(`Generated policy for ${demoRules.length} rule(s):`);
console.log(policy(demoRules));

