function buildHeader(projectName) {
  const shebang = '#!/usr/bin/env bash';
  const title = '# pre-commit hook for ' + projectName;
  const generated = '# generated by hook() -- do not edit by hand';
  const strictMode = 'set -euo pipefail';
  return [shebang, title, generated, '', strictMode].join('\n');
}

function buildBranchCheck(branchPrefix, projectName) {
  const branchVar = 'CURRENT_BRANCH="$(git rev-parse --abbrev-ref HEAD)"';
  const prefixVar = 'ALLOWED_PREFIX="' + branchPrefix + '"';
  const condition = 'if [[ "$CURRENT_BRANCH" != "$ALLOWED_PREFIX"/* ]]; then';
  const errorMessage = '  echo "[' + projectName + '] branch \'$CURRENT_BRANCH\' must start with \'$ALLOWED_PREFIX/\'" >&2';
  const hint = '  echo "[' + projectName + '] rename it: git branch -m $ALLOWED_PREFIX/$CURRENT_BRANCH" >&2';
  return [
    branchVar,
    prefixVar,
    '',
    condition,
    errorMessage,
    hint,
    '  exit 1',
    'fi',
  ].join('\n');
}

function buildLintBlock(linterCommand, warningMessage) {
  const lintVar = 'LINT_CMD="' + linterCommand + '"';
  const announce = 'echo "running: $LINT_CMD"';
  const execution = 'if ! $LINT_CMD; then';
  const lintError = '  echo "lint failed: $LINT_CMD" >&2';
  const warning = '  echo "' + warningMessage + '" >&2';
  return [
    lintVar,
    announce,
    '',
    execution,
    lintError,
    warning,
    '  exit 1',
    'fi',
  ].join('\n');
}

function hook(config) {
  const { projectName, linterCommand, branchPrefix, warningMessage } = config;
  const missing = ['projectName', 'linterCommand', 'branchPrefix', 'warningMessage']
    .filter((key) => !config[key]);
  if (missing.length > 0) {
    throw new Error('hook(): missing configuration keys: ' + missing.join(', '));
  }
  const header = buildHeader(projectName);
  const branchCheck = buildBranchCheck(branchPrefix, projectName);
  const lintBlock = buildLintBlock(linterCommand, warningMessage);
  const success = 'echo "[' + projectName + '] pre-commit checks passed"';
  return [header, '', branchCheck, '', lintBlock, '', success, ''].join('\n');
}

const script = hook({
  projectName: 'frontend',
  linterCommand: 'npm run format:check',
  branchPrefix: 'feature',
  warningMessage: 'Run npm run format before committing.',
});

