const INDENT = '  ';

function labelBlock(name, indent) {
  return `${indent}labels:\n${indent}${INDENT}app: ${name}`;
}

function metadataBlock(service) {
  const header = `apiVersion: apps/v1`;
  const kind = `kind: Deployment`;
  const nameLine = `${INDENT}name: ${service.name}`;
  const labels = labelBlock(service.name, INDENT);
  return [header, kind, 'metadata:', nameLine, labels].join('\n');
}

function selectorBlock(name, indent) {
  const matchLine = `${indent}${INDENT}app: ${name}`;
  return `${indent}selector:\n${indent}${INDENT}matchLabels:\n${INDENT}${matchLine}`;
}

function containerBlock(service, indent) {
  const nameLine = `${indent}- name: ${service.name}`;
  const imageLine = `${indent}${INDENT}image: ${service.image}`;
  const portsLine = `${indent}${INDENT}ports:`;
  const portLine = `${indent}${INDENT}${INDENT}- containerPort: ${service.port}`;
  return [nameLine, imageLine, portsLine, portLine].join('\n');
}

function podTemplate(service) {
  const specIndent = INDENT.repeat(2);
  const replicas = `${INDENT}replicas: ${service.replicas}`;
  const selector = selectorBlock(service.name, INDENT);
  const templateMeta = `${specIndent}metadata:`;
  const templateLabels = labelBlock(service.name, specIndent + INDENT);
  const containers = `${specIndent}spec:\n${specIndent}${INDENT}containers:`;
  const container = containerBlock(service, specIndent + INDENT + INDENT);
  return [
    'spec:',
    replicas,
    selector,
    `${INDENT}template:`,
    templateMeta,
    templateLabels,
    containers,
    container,
  ].join('\n');
}

function networkBlock(service) {
  const header = `apiVersion: v1`;
  const kind = `kind: Service`;
  const nameLine = `${INDENT}name: ${service.name}-svc`;
  const selectorLine = `${INDENT}${INDENT}app: ${service.name}`;
  const portLine = `${INDENT}${INDENT}- port: ${service.port}`;
  const targetLine = `${INDENT}${INDENT}${INDENT}targetPort: ${service.port}`;
  return [
    header,
    kind,
    'metadata:',
    nameLine,
    'spec:',
    `${INDENT}selector:`,
    selectorLine,
    `${INDENT}ports:`,
    portLine,
    targetLine,
  ].join('\n');
}

function manifest(service) {
  const deployment = `${metadataBlock(service)}\n${podTemplate(service)}`;
  const network = networkBlock(service);
  return `${deployment}\n---\n${network}`;
}

