const INDENT = '  ';

function indent(level) {
  return INDENT.repeat(level);
}

function routePath(indexName) {
  return `PUT /${indexName}`;
}

function settingsBlock(shards, level) {
  const open = `${indent(level)}"settings": {`;
  const shardLine = `${indent(level + 1)}"number_of_shards": ${shards}`;
  const close = `${indent(level)}},`;
  return [open, shardLine, close];
}

function propertyDefinition(field, level, isLast) {
  const nameKey = `${indent(level)}"${field.name}": {`;
  const typeLine = `${indent(level + 1)}"type": "${field.type}"`;
  const suffix = isLast ? '' : ',';
  const close = `${indent(level)}}${suffix}`;
  return [nameKey, typeLine, close];
}

function mappingsBlock(fields, level) {
  const open = `${indent(level)}"mappings": {`;
  const propsOpen = `${indent(level + 1)}"properties": {`;
  const lines = [open, propsOpen];
  fields.forEach((field, i) => {
    lines.push(...propertyDefinition(field, level + 2, i === fields.length - 1));
  });
  lines.push(`${indent(level + 1)}}`);
  lines.push(`${indent(level)}}`);
  return lines;
}

function validateSchema(schema) {
  if (!schema || typeof schema.index !== 'string' || !schema.index) {
    throw new Error('schema requires a non-empty index name');
  }
  if (!Number.isInteger(schema.shards) || schema.shards < 1) {
    throw new Error(`shards must be a positive integer, got ${schema.shards}`);
  }
  if (!Array.isArray(schema.fields) || schema.fields.length === 0) {
    throw new Error(`index ${schema.index} must declare at least one field`);
  }
  schema.fields.forEach((field, i) => {
    if (!field || !field.name || !field.type) {
      throw new Error(`field at position ${i} needs a name and a type`);
    }
  });
}

function mapping(schema) {
  validateSchema(schema);
  const lines = [routePath(schema.index), '{'];
  lines.push(...settingsBlock(schema.shards, 1));
  lines.push(...mappingsBlock(schema.fields, 1));
  lines.push('}');
  return lines.join('\n');
}

function describe(schema) {
  const names = schema.fields.map((f) => `${f.name}:${f.type}`).join(', ');
  return `${schema.index} (${schema.shards} shards) -> ${names}`;
}

function main() {
  const users = {
    index: 'users',
    shards: 3,
    fields: [
      { name: 'email', type: 'keyword' },
      { name: 'age', type: 'integer' }
    ]
  };
  console.log(describe(users));
  console.log(mapping(users));
}

main();

module.exports = { mapping, settingsBlock, mappingsBlock, propertyDefinition };

