const INDENT = '  ';

function validateModel(model) {
  if (!model.name) {
    throw new Error('Every model needs a name.');
  }
  if (!Array.isArray(model.properties) || model.properties.length === 0) {
    throw new Error(`Model ${model.name} must declare at least one property.`);
  }
  return model;
}

function schemaOpening(models) {
  const names = models.map((model) => model.name).join(', ');
  return `# Generated schema for: ${names}`;
}

function typeDocumentation(description) {
  return `"""\n${description}\n"""`;
}

function typeDeclaration(name) {
  return `type ${name} {`;
}

function requiredField(property) {
  return `${INDENT}${property.name}: ${property.type}!`;
}

function optionalField(property) {
  return `${INDENT}${property.name}: ${property.type}`;
}

function fieldLine(property) {
  return property.required ? requiredField(property) : optionalField(property);
}

function typeBlock(model) {
  const fields = model.properties.map(fieldLine).join('\n');
  const header = `${typeDocumentation(model.description)}\n${typeDeclaration(model.name)}`;
  return `${header}\n${fields}\n}`;
}

function queryResolver(model) {
  const key = model.properties.find((property) => property.required) || model.properties[0];
  const argument = `${key.name}: ${key.type}!`;
  const lowered = model.name[0].toLowerCase() + model.name.slice(1);
  return `${INDENT}${lowered}(${argument}): ${model.name}`;
}

function rootQueryType(models) {
  const resolvers = models.map(queryResolver).join('\n');
  return `type Query {\n${resolvers}\n}`;
}

function schemaClosing(models) {
  const fieldCount = models.reduce((total, model) => total + model.properties.length, 0);
  return `# ${models.length} type(s), ${fieldCount} field(s) emitted`;
}

function schema(models) {
  const checked = models.map(validateModel);
  const blocks = checked.map(typeBlock);
  blocks.push(rootQueryType(checked));
  const body = blocks.join('\n\n');
  return `${schemaOpening(checked)}\n\n${body}\n\n${schemaClosing(checked)}\n`;
}

const userModel = {
  name: 'User',
  description: 'A registered account holder.',
  properties: [
    { name: 'id', type: 'ID', required: true },
    { name: 'alias', type: 'String', required: false },
  ],
};

console.log(schema([userModel]));

module.exports = { schema, fieldLine, typeBlock, rootQueryType };

