const escapeSingleQuotes = (value) => String(value).split("'").join("'\\''");

const shellQuote = (value) => `'${escapeSingleQuotes(value)}'`;

const windowTarget = (name, index) => {
  const suffix = `:${index}`;
  return shellQuote(name + suffix);
};

const validateLayout = (layout) => {
  if (!layout || typeof layout.name !== 'string' || layout.name.trim() === '') {
    throw new Error('layout requires a non-empty session name');
  }
  if (!Array.isArray(layout.windows) || layout.windows.length === 0) {
    throw new Error(`session ${layout.name} must declare at least one window`);
  }
  layout.windows.forEach((win, index) => {
    if (typeof win.name !== 'string' || win.name.trim() === '') {
      throw new Error(`window #${index} is missing a name`);
    }
    if (typeof win.command !== 'string') {
      throw new Error(`window ${win.name} is missing a startup command`);
    }
  });
};

const shebang = () => '#!/usr/bin/env bash\nset -euo pipefail\n';

const sessionCheck = (name) => {
  const quoted = shellQuote(name);
  const guard = `if tmux has-session -t ${quoted} 2>/dev/null; then`;
  const notice = `  echo "session ${name} already running, attaching"`;
  const attach = `  exec tmux attach-session -t ${quoted}`;
  const body = [guard, notice, attach, 'fi'].join('\n');
  return `${body}\n`;
};

const changeDirectory = (root) => `cd ${shellQuote(root)}\n`;

const initSession = (plan) => {
  const name = shellQuote(plan.name);
  const first = shellQuote(plan.windows[0].name);
  const root = shellQuote(plan.root);
  return `tmux new-session -d -s ${name} -n ${first} -c ${root}\n`;
};

const newWindow = (plan, win, index) => {
  const target = windowTarget(plan.name, index);
  const root = shellQuote(plan.root);
  const label = shellQuote(win.name);
  const create = `tmux new-window -t ${target} -c ${root}`;
  const rename = `tmux rename-window -t ${target} ${label}`;
  return [create, rename, ''].join('\n');
};

const sendKeys = (plan, win, index) => {
  const target = windowTarget(plan.name, index);
  const command = shellQuote(win.command);
  return `tmux send-keys -t ${target} ${command} C-m\n`;
};

const selectFirstWindow = (name) => `tmux select-window -t ${windowTarget(name, 0)}\n`;

const attachSession = (name) => `exec tmux attach-session -t ${shellQuote(name)}\n`;

function session(layout) {
  validateLayout(layout);
  const plan = { name: layout.name, root: layout.root || '.', windows: layout.windows };
  let script = shebang();
  script += sessionCheck(plan.name);
  script += changeDirectory(plan.root);
  script += initSession(plan);
  plan.windows.forEach((win, index) => {
    if (index > 0) {
      script += newWindow(plan, win, index);
    }
    script += sendKeys(plan, win, index);
  });
  script += selectFirstWindow(plan.name);
  return script + attachSession(plan.name);
}

