function originDirective(domain) {
  return `$ORIGIN ${domain.name}.`;
}

function ttlDefinition(domain) {
  return `$TTL ${domain.ttl}`;
}

function emailToRname(email) {
  const [local, host] = email.split('@');
  const escaped = local.replace(/\./g, '\\.');
  return `${escaped}.${host}.`;
}

function authorityRecord(domain, serial) {
  const rname = emailToRname(domain.admin);
  const header = `@\tIN\tSOA\t${domain.primaryNs}.\t${rname} (`;
  const serialLine = `\t\t\t${serial}\t; serial`;
  const refreshLine = `\t\t\t${domain.refresh || 3600}\t; refresh`;
  const retryLine = `\t\t\t${domain.retry || 600}\t; retry`;
  const expireLine = `\t\t\t${domain.expire || 604800}\t; expire`;
  const minimumLine = `\t\t\t${domain.ttl}\t; minimum`;
  return [header, serialLine, refreshLine, retryLine, expireLine, minimumLine, '\t\t\t)'];
}

function nameServerRecords(domain) {
  const servers = domain.nameServers && domain.nameServers.length
    ? domain.nameServers
    : [domain.primaryNs];
  return servers.map((ns) => `@\tIN\tNS\t${ns}.`);
}

function addressRecords(domain) {
  return domain.records.map((record) => `${record.host}\tIN\tA\t${record.ip}`);
}

function makeSerial(date) {
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, '0');
  const d = String(date.getUTCDate()).padStart(2, '0');
  return `${y}${m}${d}01`;
}

function zone(domain) {
  if (!domain || !domain.name) {
    throw new Error('zone: a base domain name is required');
  }
  if (!domain.records || !domain.records.length) {
    throw new Error(`zone: ${domain.name} has no address records`);
  }
  const serial = makeSerial(domain.date || new Date());
  const lines = [originDirective(domain), ttlDefinition(domain), ''];
  lines.push(...authorityRecord(domain, serial), '');
  lines.push(...nameServerRecords(domain), '');
  lines.push(...addressRecords(domain));
  return `${lines.join('\n')}\n`;
}

const example = {
  name: 'example.com',
  ttl: 86400,
  admin: 'hostmaster@example.com',
  primaryNs: 'ns1.example.com',
  nameServers: ['ns1.example.com', 'ns2.example.com'],
  date: new Date(Date.UTC(2024, 4, 17)),
  records: [
    { host: 'www', ip: '198.51.100.10' },
    { host: 'mail', ip: '198.51.100.20' },
  ],
};

process.stdout.write(zone(example));
process.stdout.write(`; ${example.records.length} address records written\n`);

