function scriptHeader(job) {
  const shebang = `#!/usr/bin/env bash`;
  const strictMode = `set -euo pipefail`;
  const title = `# backup job: ${job.source} -> ${job.host}:${job.destination}`;
  return [shebang, strictMode, '', title].join('\n');
}

function loggingSetup(job) {
  const name = job.source.replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '');
  const logFile = `LOG_FILE="/var/log/backup-${name}.log"`;
  const redirect = `exec > >(tee -a "$LOG_FILE") 2>&1`;
  const startNotice = `echo "[$(date --iso-8601=seconds)] starting backup of ${job.source}"`;
  return [logFile, redirect, startNotice].join('\n');
}

function syncCommand(job) {
  const src = `SRC="${job.source.replace(/\/?$/, '/')}"`;
  const dst = `DST="${job.user}@${job.host}:${job.destination}"`;
  const sshArg = `--rsh="ssh -i ${job.keyFile} -o StrictHostKeyChecking=yes"`;
  const excludeFlag = `--exclude="${job.exclude}"`;
  const options = ['--archive', '--compress', '--delete', '--human-readable'].join(' ');
  const command = `rsync ${options} ${sshArg} ${excludeFlag} "$SRC" "$DST"`;
  return [src, dst, '', command].join('\n');
}

function completionNotice(job) {
  const success = `echo "[$(date --iso-8601=seconds)] backup of ${job.source} completed"`;
  const mail = `mail -s "Backup OK: ${job.host}" "${job.notify}" < "$LOG_FILE"`;
  return [success, mail].join('\n');
}

function validateJob(job) {
  const required = ['source', 'user', 'host', 'destination', 'keyFile', 'exclude', 'notify'];
  const missing = required.filter((field) => !job[field]);
  if (missing.length > 0) {
    throw new Error(`backup job is missing: ${missing.join(', ')}`);
  }
  if (!job.source.startsWith('/')) {
    throw new Error(`source must be an absolute path, got "${job.source}"`);
  }
  if (!job.destination.startsWith('/')) {
    throw new Error(`destination must be an absolute path, got "${job.destination}"`);
  }
}

function backup(job) {
  validateJob(job);
  const sections = [
    scriptHeader(job),
    loggingSetup(job),
    syncCommand(job),
    completionNotice(job)
  ];
  return `${sections.join('\n\n')}\n`;
}

function describeJob(job) {
  const target = `${job.user}@${job.host}:${job.destination}`;
  return `sync ${job.source} to ${target}, skipping ${job.exclude}`;
}

const homeJob = {
  source: '/home/alice',
  user: 'backup',
  host: 'files.example.net',
  destination: '/srv/backups/alice',
  keyFile: '/home/alice/.ssh/backup_ed25519',
  exclude: '*.cache',
  notify: 'alice@example.net'
};

console.log(describeJob(homeJob));
console.log(backup(homeJob));

