'use strict';

const INDENT = '  ';

function indentLine(depth, text) {
  return INDENT.repeat(depth) + text;
}

function formatLiteral(value) {
  if (typeof value === 'string') {
    return `"${value}"`;
  }
  return String(value);
}

function fieldPath(field) {
  return `"$${field}"`;
}

function validateQuery(query) {
  for (const key of ['collection', 'groupBy', 'sumAlias']) {
    if (!query[key]) {
      throw new TypeError(`Query is missing the required property "${key}".`);
    }
  }
  if (!query.match || !query.match.field) {
    throw new TypeError('Query needs a match stage describing the filtered field.');
  }
  const order = query.sort && query.sort.order;
  if (order !== 'asc' && order !== 'desc') {
    throw new TypeError(`Unsupported sort order "${order}", expected "asc" or "desc".`);
  }
}

function buildMatchStage(match) {
  const condition = `${match.field}: ` + formatLiteral(match.value);
  return [indentLine(1, '{ $match: {'), indentLine(2, condition), indentLine(1, '} }')];
}

function buildGroupStage(query) {
  const identifier = `_id: ${fieldPath(query.groupBy)},`;
  const sumExpression = query.sumField ? `{ $sum: ${fieldPath(query.sumField)} }` : '{ $sum: 1 }';
  const accumulator = `${query.sumAlias}: ` + sumExpression;
  return [
    indentLine(1, '{ $group: {'),
    indentLine(2, identifier),
    indentLine(2, accumulator),
    indentLine(1, '} }'),
  ];
}

function buildSortStage(sort) {
  const direction = sort.order === 'desc' ? -1 : 1;
  const sortLine = `${sort.field}: ` + direction;
  return [indentLine(1, '{ $sort: {'), indentLine(2, sortLine), indentLine(1, '} }')];
}

function aggregation(query) {
  validateQuery(query);
  const lines = [`db.${query.collection}.aggregate([`];
  const stages = [buildMatchStage(query.match), buildGroupStage(query), buildSortStage(query.sort)];
  stages.forEach((stage, index) => {
    const closing = stage[stage.length - 1];
    stage[stage.length - 1] = index < stages.length - 1 ? `${closing},` : closing;
    lines.push(...stage);
  });
  lines.push('])');
  return lines.join('\n');
}

function documentPipeline(title, query) {
  const heading = `// ${title}`;
  return [heading, aggregation(query)].join('\n');
}

