const PAPER_SIZES = ['letter', 'a4', 'a5', 'legal', 'executive'];

function normalizePaper(paper) {
  const name = String(paper || '').trim().toLowerCase();
  if (!PAPER_SIZES.includes(name)) {
    throw new RangeError(`Unsupported paper size: ${paper}`);
  }
  return `${name}paper`;
}

function escapeText(text) {
  return String(text)
    .replace(/\\/g, '\\textbackslash{}')
    .replace(/([&%$#_])/g, '\\$1')
    .replace(/~/g, '\\textasciitilde{}')
    .replace(/\^/g, '\\textasciicircum{}');
}

function command(name, argument) {
  return `\\${name}{${escapeText(argument)}}`;
}

function environment(name, body) {
  const opening = `\\begin{${name}}`;
  const closing = `\\end{${name}}`;
  return [opening, ...body, closing];
}

function renderSection(section) {
  const lines = [command('section', section.heading || 'Untitled')];
  for (const paragraph of section.paragraphs || []) {
    lines.push(escapeText(paragraph));
    lines.push('');
  }
  return lines;
}

function typeset(document) {
  if (!document || typeof document !== 'object') {
    throw new TypeError(`Expected a document object, received ${typeof document}`);
  }
  const lines = [`\\documentclass[${normalizePaper(document.paper)}]{article}`];
  lines.push(command('title', document.title || 'Untitled'));
  lines.push(command('author', document.author || 'Anonymous'));
  lines.push('\\begin{document}');
  lines.push('\\maketitle');
  if (document.abstract) {
    lines.push(...environment('abstract', [escapeText(document.abstract)]));
  }
  for (const section of document.sections || []) {
    lines.push(...renderSection(section));
  }
  lines.push('\\end{document}');
  return lines.join('\n');
}

function describe(document) {
  const sections = document.sections || [];
  const words = sections
    .flatMap((section) => section.paragraphs || [])
    .reduce((total, paragraph) => total + paragraph.split(/\s+/).filter(Boolean).length, 0);
  return `${document.title}: ${sections.length} section(s), ${words} word(s) of body text`;
}

const sample = {
  paper: 'letter',
  author: 'Jane',
  title: 'Hello',
  abstract: 'A short greeting rendered with 100% markup.',
  sections: [
    {
      heading: 'Introduction',
      paragraphs: ['Hello, world.', 'Typesetting is a craft of spacing & rhythm.']
    },
    {
      heading: 'Conclusion',
      paragraphs: ['Goodbye for now.']
    }
  ]
};

console.log(describe(sample));
console.log(typeset(sample));

module.exports = { typeset, describe, escapeText };

