function formatField(field, index) {
  const id = field.id ?? index + 1;
  return `  ${id}: ${field.type} ${field.name};`;
}

function formatStruct(struct) {
  const lines = [`struct ${struct.name} {`];
  struct.fields.forEach((field, index) => {
    lines.push(formatField(field, index));
  });
  lines.push('}');
  return lines.join('\n');
}

function formatParam(param, index) {
  const id = param.id ?? index + 1;
  return `${id}: ${param.type} ${param.name}`;
}

function formatFunction(fn) {
  const args = (fn.params || []).map(formatParam).join(', ');
  return `  ${fn.returns} ${fn.name}(${args}),`;
}

function formatService(service) {
  const lines = [`service ${service.name} {`];
  for (const fn of service.functions) {
    lines.push(formatFunction(fn));
  }
  lines.push('}');
  return lines.join('\n');
}

function validate(schema) {
  if (typeof schema.namespace !== 'string' || schema.namespace.length === 0) {
    throw new Error(`invalid namespace: ${JSON.stringify(schema.namespace)}`);
  }
  for (const struct of schema.structs || []) {
    if (!Array.isArray(struct.fields)) {
      throw new Error(`struct ${struct.name} must declare a fields array`);
    }
  }
  if (!schema.service || !Array.isArray(schema.service.functions)) {
    throw new Error(`service ${schema.service && schema.service.name} has no functions`);
  }
}

function interface_(schema) {
  validate(schema);
  const blocks = [`namespace ${schema.namespace}`];
  for (const file of schema.includes || []) {
    blocks.push(`include "${file}"`);
  }
  for (const struct of schema.structs || []) {
    blocks.push(formatStruct(struct));
  }
  blocks.push(formatService(schema.service));
  return `${blocks.join('\n\n')}\n`;
}

