const BLANK = ' '.repeat(10);
const ELEMENT = '*';

function segment(fields) {
  return `${fields.join(ELEMENT)}~`;
}

function padId(id, label) {
  const value = String(id == null ? '' : id).trim();
  if (value.length === 0 || value.length > 15) {
    throw new Error(`${label} identifier must hold 1 to 15 characters`);
  }
  return value.padEnd(15, ' ');
}

function controlNumber(raw) {
  const digits = String(raw).replace(/\D/g, '');
  if (digits.length === 0) {
    throw new Error(`Control number ${raw} must contain at least one digit`);
  }
  return digits.padStart(9, '0');
}

function ediDate(dateString) {
  const digits = String(dateString).replace(/\D/g, '');
  if (digits.length !== 8) {
    throw new Error(`Date ${dateString} must supply eight digits (CCYYMMDD)`);
  }
  return digits;
}

function money(amount) {
  const value = Number(amount);
  if (!Number.isFinite(value) || value < 0) {
    throw new Error(`Price ${amount} must be a non-negative number`);
  }
  return value.toFixed(2);
}

function quantity(amount) {
  const value = Number(amount);
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error(`Quantity ${amount} must be a positive number`);
  }
  return String(value);
}

function lineItemSegment(item, index) {
  const position = `${index + 1}`;
  if (!item.productCode) {
    throw new Error(`Line item ${position} is missing a product code`);
  }
  return segment([
    'PO1',
    position,
    quantity(item.quantity),
    'EA',
    money(item.price),
    '',
    'BP',
    item.productCode,
  ]);
}

function transaction(order) {
  const control = controlNumber(order.controlNumber);
  const sender = `ZZ${ELEMENT}${padId(order.senderId, 'Sender')}`;
  const receiver = `ZZ${ELEMENT}${padId(order.receiverId, 'Receiver')}`;
  const stamp = ediDate(order.date);
  const items = order.items || [];
  const setId = control.slice(-4);
  const parts = [
    segment(['ISA', '00', BLANK, '00', BLANK, sender, receiver, stamp.slice(2), '0000', 'U', '00401', control, '0', 'P', '>']),
    segment(['GS', 'PO', String(order.senderId).trim(), String(order.receiverId).trim(), stamp, '0000', Number(control), 'X', '004010']),
    segment(['ST', '850', setId]),
    ...items.map(lineItemSegment),
    segment(['SE', items.length, setId]),
    segment(['GE', '1', Number(control)]),
    segment(['IEA', '1', control]),
  ];
  return parts.join('');
}

module.exports = { transaction };

