const ALLOWED_TIERS = ['Hot', 'Cool', 'Archive'];

function requireString(value, field) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new TypeError(`blueprint field '${field}' must be a non-empty string`);
  }
  return value.trim();
}

function validateAccount(account, index) {
  const prefix = requireString(account && account.namePrefix, `storageAccounts[${index}].namePrefix`);
  const sku = requireString(account.redundancySku, 'redundancySku');
  const tier = requireString(account.accessTier, 'accessTier');
  if (!ALLOWED_SKUS.includes(sku)) {
    throw new RangeError(`unsupported redundancy sku '${sku}' for account ${prefix}`);
  }
  if (!ALLOWED_TIERS.includes(tier)) {
    throw new RangeError(`unsupported access tier '${tier}' for account ${prefix}`);
  }
  return { namePrefix: prefix, redundancySku: sku, accessTier: tier };
}

function symbolFor(namePrefix) {
  const cleaned = namePrefix.replace(/[^A-Za-z0-9]/g, '');
  const head = cleaned.charAt(0).toUpperCase();
  return `st${head + cleaned.slice(1)}`;
}

