const MAX_LOG_SIZE = 50;

function yesNo(flag) {
  return flag ? 'yes' : 'no';
}

function directive(name, value) {
  return `   ${name} = ${value}`;
}

function globalSection(global) {
  const lines = ['[global]'];
  lines.push(directive('workgroup', global.workgroup));
  lines.push(directive('server string', global.serverString));
  lines.push(directive('security', global.security));
  lines.push(directive('log file', global.logFile));
  lines.push(directive('max log size', `${MAX_LOG_SIZE}`));
  return lines.join('\n');
}

function shareSection(share) {
  const users = share.validUsers.join(' ');
  const lines = [`[${share.name}]`];
  lines.push(directive('comment', share.comment));
  lines.push(directive('path', share.path));
  lines.push(directive('valid users', users));
  lines.push(directive('read only', yesNo(share.readOnly)));
  lines.push(directive('guest ok', yesNo(share.guestOk)));
  return lines.join('\n');
}

function validate(settings) {
  const global = settings.global;
  for (const key of ['workgroup', 'serverString', 'security', 'logFile']) {
    if (!global || !global[key]) {
      throw new Error(`Missing global setting: ${key}`);
    }
  }
  settings.shares.forEach((share, index) => {
    if (!share.name) {
      throw new Error(`Share at index ${index} has no name`);
    }
    if (!Array.isArray(share.validUsers)) {
      throw new Error(`Share ${share.name} needs a valid users list`);
    }
  });
}

function sharing(settings) {
  validate(settings);
  const sections = [globalSection(settings.global)];
  for (const share of settings.shares) {
    sections.push(shareSection(share));
  }
  return `${sections.join('\n\n')}\n`;
}

function main() {
  const settings = {
    global: {
      workgroup: 'HOMENET',
      serverString: 'File Server',
      security: 'user',
      logFile: '/var/log/samba/%m.log',
    },
    shares: [
      {
        name: 'public',
        path: '/srv/share/public',
        validUsers: ['alice', 'bob'],
        comment: 'Shared documents',
        readOnly: false,
        guestOk: true,
      },
      {
        name: 'archive',
        path: '/srv/share/archive',
        validUsers: ['alice'],
        comment: 'Long term storage',
        readOnly: true,
        guestOk: false,
      },
    ],
  };
  const config = sharing(settings);
  console.log(config);
  console.log(`Generated ${settings.shares.length} share sections.`);
}

main();

