const FREQUENCIES = new Set(['daily', 'weekly', 'monthly', 'yearly']);

function validateLog(log, index) {
  const label = `logs[${index}]`;
  if (!log || typeof log.path !== 'string' || log.path.trim() === '') {
    throw new Error(`${label} must have a non-empty file path`);
  }
  if (!FREQUENCIES.has(log.frequency)) {
    throw new Error(`${label} has an unsupported frequency: ${log.frequency}`);
  }
  const retain = Number(log.retain);
  if (!Number.isInteger(retain) || retain < 0) {
    throw new Error(`${label} needs a non-negative integer retain count, got ${log.retain}`);
  }
  return { path: log.path.trim(), frequency: log.frequency, retain };
}

function scriptSection(name, command) {
  const body = String(command).trim();
  const lines = [`    ${name}`];
  lines.push(`        ${body}`);
  lines.push('    endscript');
  return lines.join('\n');
}

function rotation(logs) {
  const blocks = [];
  logs.forEach((log, index) => {
    const { path, frequency, retain } = validateLog(log, index);
    const lines = [`${path} {`];
    lines.push(`    ${frequency}`);
    lines.push(`    rotate ${retain}`);
    lines.push('    missingok');
    if (log.preRotate) {
      lines.push(scriptSection('prerotate', log.preRotate));
    }
    if (log.postRotate) {
      lines.push(scriptSection('postrotate', log.postRotate));
    }
    lines.push('}');
    blocks.push(lines.join('\n'));
  });
  return blocks.map((block) => `${block}\n`).join('\n');
}

function summarize(logs) {
  const counts = new Map();
  for (const log of logs) {
    counts.set(log.frequency, (counts.get(log.frequency) || 0) + 1);
  }
  const parts = [...counts.entries()].map(([frequency, count]) => `${count} ${frequency}`);
  return `Generated ${logs.length} block(s): ${parts.join(', ')}`;
}

const logs = [
  {
    path: '/var/log/nginx/access.log',
    frequency: 'daily',
    retain: 14,
    preRotate: 'test -x /usr/sbin/nginx || exit 0',
    postRotate: 'systemctl reload nginx',
  },
  {
    path: '/var/log/syslog',
    frequency: 'weekly',
    retain: 4,
    preRotate: '',
    postRotate: 'invoke-rc.d rsyslog rotate > /dev/null',
  },
  {
    path: '/var/log/app/audit.log',
    frequency: 'monthly',
    retain: 12,
    preRotate: '',
    postRotate: '',
  },
];

process.stdout.write(rotation(logs));
console.log(`# ${summarize(logs)}`);

module.exports = { rotation, summarize };

