function validateHost(host, index) {
  if (!host.alias) {
    throw new Error(`Host entry #${index + 1} is missing an alias`);
  }
  if (!host.hostName) {
    throw new Error(`Host "${host.alias}" is missing a real hostname`);
  }
  if (!host.user) {
    throw new Error(`Host "${host.alias}" is missing a username`);
  }
  if (!host.identityFile) {
    throw new Error(`Host "${host.alias}" is missing an identity file path`);
  }
  if (host.port !== undefined && host.port !== null) {
    const port = Number(host.port);
    if (!Number.isInteger(port) || port < 1 || port > 65535) {
      throw new Error(`Host "${host.alias}" has an invalid port: ${host.port}`);
    }
  }
}

function directive(keyword, value) {
  return `  ${keyword} ${value}`;
}

function hostBlock(host) {
  const lines = [`Host ${host.alias}`];
  lines.push(directive('HostName', host.hostName));
  lines.push(directive('User', host.user));
  if (host.port !== undefined && host.port !== null && host.port !== '') {
    lines.push(directive('Port', host.port));
  }
  lines.push(directive('IdentityFile', host.identityFile));
  lines.push(directive('ForwardAgent', host.forwardAgent ? 'yes' : 'no'));
  return lines.join('\n');
}

function access(hosts) {
  if (!Array.isArray(hosts)) {
    throw new TypeError(`access() expects an array of hosts, received ${typeof hosts}`);
  }
  hosts.forEach(validateHost);
  return hosts.map(hostBlock).join('\n\n');
}

function summarize(hosts) {
  const aliases = hosts.map((host) => host.alias).join(', ');
  const agents = hosts.filter((host) => host.forwardAgent).length;
  return `${hosts.length} host(s) configured (${aliases}); agent forwarding on ${agents}`;
}

const inventory = [
  {
    alias: 'web',
    hostName: 'web01.example.com',
    user: 'deploy',
    identityFile: '~/.ssh/id_deploy',
    port: 22,
    forwardAgent: true,
  },
  {
    alias: 'db',
    hostName: '10.0.4.19',
    user: 'postgres',
    identityFile: '~/.ssh/id_db',
    port: 2222,
    forwardAgent: false,
  },
  {
    alias: 'jump',
    hostName: 'bastion.example.com',
    user: 'admin',
    identityFile: '~/.ssh/id_bastion',
    forwardAgent: true,
  },
];

try {
  console.log(access(inventory));
  console.log(`\n# ${summarize(inventory)}`);
} catch (error) {
  console.error(`Configuration failed: ${error.message}`);
}

