function validateMenu(menu) {
  if (!menu || typeof menu !== 'object') {
    throw new TypeError('boot() requires a menu object');
  }
  for (const field of ['default', 'timeout', 'title', 'entries']) {
    if (!(field in menu)) {
      throw new TypeError(`menu is missing the required field "${field}"`);
    }
  }
  if (!Array.isArray(menu.entries) || menu.entries.length === 0) {
    throw new TypeError('menu.entries must be a non-empty array of boot entries');
  }
  const timeout = Number(menu.timeout);
  if (!Number.isFinite(timeout) || timeout < 0) {
    throw new RangeError(`menu.timeout must be a non-negative number, got ${menu.timeout}`);
  }
  return timeout;
}

function validateEntry(entry, index) {
  for (const field of ['label', 'kernel', 'initrd']) {
    if (typeof entry[field] !== 'string' || entry[field].length === 0) {
      throw new TypeError(`entry #${index} needs a non-empty "${field}" string`);
    }
  }
  if (!Array.isArray(entry.append)) {
    throw new TypeError(`entry "${entry.label}" needs an array of append parameters`);
  }
}

function appendDirective(entry) {
  const params = entry.append.map(String).join(' ');
  const initrd = `initrd=${entry.initrd}`;
  return params ? `${initrd} ${params}` : initrd;
}

function renderEntry(entry, index) {
  validateEntry(entry, index);
  const lines = [`label ${entry.label}`];
  lines.push(`  kernel ${entry.kernel}`);
  lines.push(`  append ${appendDirective(entry)}`);
  return lines.join('\n');
}

function boot(menu) {
  const timeout = validateMenu(menu);
  const header = [`default ${menu.default}`];
  header.push(`timeout ${timeout}`);
  header.push(`menu title ${menu.title}`);
  const blocks = [header.join('\n')];
  menu.entries.forEach((entry, index) => blocks.push(renderEntry(entry, index)));
  return blocks.join('\n\n');
}

function summarize(menu) {
  const labels = menu.entries.map((entry) => entry.label).join(', ');
  return `${menu.entries.length} entries (${labels}), booting "${menu.default}" after ${menu.timeout}`;
}

const pxeMenu = {
  default: 'rescue',
  timeout: 50,
  title: 'Network Boot Menu',
  entries: [
    {
      label: 'rescue',
      kernel: 'images/rescue/vmlinuz',
      initrd: 'images/rescue/initrd.img',
      append: ['ro', 'console=tty0', 'systemd.unit=rescue.target'],
    },
    {
      label: 'installer',
      kernel: 'images/debian/linux',
      initrd: 'images/debian/initrd.gz',
      append: ['auto=true', 'priority=critical', 'url=http://boot.local/preseed.cfg'],
    },
    {
      label: 'memtest',
      kernel: 'images/memtest/memtest86+',
      initrd: 'images/memtest/blank.img',
      append: [],
    },
  ],
};

console.log(`# generated menu: ${summarize(pxeMenu)}`);
console.log(boot(pxeMenu));

module.exports = { boot, summarize };

