function formatList(values) {
  return values.map((value) => `${value};`).join('');
}

function validateApp(app) {
  const problems = [];
  if (!app.name) {
    problems.push('name is required');
  }
  if (!app.exec) {
    problems.push('exec is required');
  }
  if (!Array.isArray(app.categories)) {
    problems.push(`categories must be an array, got ${typeof app.categories}`);
  }
  if (!Array.isArray(app.mimeTypes)) {
    problems.push(`mimeTypes must be an array, got ${typeof app.mimeTypes}`);
  }
  if (problems.length > 0) {
    throw new Error(`Invalid app entry: ${problems.join(', ')}`);
  }
}

function launcher(app) {
  validateApp(app);
  const lines = ['[Desktop Entry]'];
  lines.push('Type=Application');
  lines.push(`Name=${app.name}`);
  lines.push(`GenericName=${app.genericName}`);
  lines.push(`Comment=${app.comment}`);
  lines.push(`Exec=${app.exec}`);
  lines.push(`Icon=${app.icon}`);
  lines.push(`Terminal=${app.terminal ? 'true' : 'false'}`);
  lines.push(`Categories=${formatList(app.categories)}`);
  lines.push(`MimeType=${formatList(app.mimeTypes)}`);
  return `${lines.join('\n')}\n`;
}

function fileNameFor(app) {
  const slug = app.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  return `${slug}.desktop`;
}

function report(app) {
  const content = launcher(app);
  const header = `--- ${fileNameFor(app)} (${content.split('\n').length - 1} lines) ---`;
  return `${header}\n${content}`;
}

const apps = [
  {
    name: 'Fancy Text Editor',
    genericName: 'Text Editor',
    comment: 'Edit plain text files with style',
    exec: '/usr/bin/fancyedit %F',
    icon: '/usr/share/icons/fancyedit.png',
    terminal: false,
    categories: ['Utility', 'TextEditor', 'Development'],
    mimeTypes: ['text/plain', 'text/markdown', 'application/json'],
  },
  {
    name: 'Serial Console',
    genericName: 'Terminal Monitor',
    comment: 'Talk to devices over a serial port',
    exec: '/usr/local/bin/serialmon',
    icon: '/usr/share/icons/serialmon.svg',
    terminal: true,
    categories: ['System', 'TerminalEmulator'],
    mimeTypes: ['text/x-log'],
  },
];

for (const app of apps) {
  process.stdout.write(report(app));
}

module.exports = { launcher, fileNameFor, report };

