function formatColor(color) {
  const [r, g, b] = color;
  return r.toFixed(3) + ' ' + g.toFixed(3) + ' ' + b.toFixed(3) + ' setrgbcolor';
}

function rectangleLines(shape) {
  const { x, y, width, height } = shape;
  const lines = [formatColor(shape.color)];
  lines.push(x + ' ' + y + ' moveto');
  lines.push(width + ' 0 rlineto');
  lines.push('0 ' + height + ' rlineto');
  lines.push((-width) + ' 0 rlineto');
  lines.push('closepath');
  lines.push('fill');
  return lines;
}

function circleLines(shape) {
  const { x, y, radius } = shape;
  const lines = [formatColor(shape.color)];
  lines.push(x + ' ' + y + ' ' + radius + ' 0 360 arc');
  lines.push('fill');
  return lines;
}

function shapeLines(shape) {
  if (shape.type === 'rectangle') {
    return rectangleLines(shape);
  }
  if (shape.type === 'circle') {
    return circleLines(shape);
  }
  throw new Error('Unsupported shape type: ' + shape.type);
}

function postscript(shapes) {
  const { width, height } = shapes;
  const items = shapes.shapes || [];
  const out = ['%!PS-Adobe-3.0'];
  out.push('%%BoundingBox: 0 0 ' + width + ' ' + height);
  out.push((width / 2) + ' ' + (height / 2) + ' translate');
  for (const shape of items) {
    out.push(...shapeLines(shape));
  }
  out.push('showpage');
  out.push('%%EOF');
  return out.join('\n') + '\n';
}

function describe(shape) {
  if (shape.type === 'rectangle') {
    return 'rectangle ' + shape.width + 'x' + shape.height + ' at (' + shape.x + ', ' + shape.y + ')';
  }
  return 'circle r=' + shape.radius + ' at (' + shape.x + ', ' + shape.y + ')';
}

function main() {
  const page = {
    width: 400,
    height: 300,
    shapes: [
      { type: 'rectangle', x: -150, y: -100, width: 120, height: 80, color: [0.9, 0.2, 0.2] },
      { type: 'circle', x: 60, y: 20, radius: 70, color: [0.1, 0.4, 0.8] },
      { type: 'rectangle', x: -20, y: -120, width: 160, height: 40, color: [0, 0, 0] },
    ],
  };

  const document = postscript(page);
  for (const shape of page.shapes) {
    console.log('drawing ' + describe(shape));
  }
  console.log('page ' + page.width + 'x' + page.height + ' produced ' + (document.split('\n').length - 1) + ' lines');
  console.log(document);
}

main();

module.exports = { postscript, describe };

