function formatHeading(name, zone) {
  return `[${name}] [${zone}]`;
}

function formatConditions(lightLevel, weather) {
  return `The light level is ${lightLevel} and the weather is ${weather}.`;
}

function formatDanger(dangerLevel) {
  return `Warning: this area is classified as ${dangerLevel}.`;
}

function formatExits(exits) {
  const joined = exits.join(', ');
  return `Exits: [${joined}]`;
}

function formatPlayerCount(players) {
  const noun = players.length === 1 ? 'player' : 'players';
  return `There are ${players.length} active ${noun} in the area.`;
}

function formatPlayerList(players) {
  if (players.length === 0) {
    return 'No one is standing in the room right now.';
  }
  return `Standing in the room: ${players.join(', ')}.`;
}

function formatItems(items) {
  return items.map((item) => `A ${item} rests on the ground.`);
}

function describe(room) {
  const {
    name,
    zone,
    narrative,
    lightLevel,
    weather,
    exits = [],
    players = [],
    items = [],
    dangerLevel,
  } = room;

  if (!name || !zone) {
    throw new Error(`A room needs both a name and a zone, got "${name}" in "${zone}".`);
  }

  const lines = [formatHeading(name, zone), narrative];
  lines.push(formatConditions(lightLevel, weather));
  lines.push(formatDanger(dangerLevel));
  lines.push(formatExits(exits));
  lines.push(formatPlayerCount(players));
  lines.push(formatPlayerList(players));
  lines.push(...formatItems(items));
  lines.push(`What do you want to do in the ${name}?`);

  return lines.join('\n');
}

const darkCave = {
  name: 'Dark Cave',
  zone: 'Underworld',
  narrative: 'Water drips from unseen stalactites and the air tastes of iron.',
  lightLevel: 'pitch black',
  weather: 'damp and still',
  exits: ['north', 'east', 'down'],
  players: ['Ragnar', 'Lyra', 'Sethos'],
  items: ['rusted lantern', 'torn map', 'bone key'],
  dangerLevel: 'THREAT-4',
};

console.log(describe(darkCave));

module.exports = { describe, formatHeading, formatExits, formatItems };

