const XML_ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' };

function escapeXml(value) {
  return String(value).replace(/[&<>"]/g, (char) => XML_ESCAPES[char]);
}

function labelFor(command) {
  const base = command.trim().split(/\s+/)[0].split('/').pop();
  return `${base.charAt(0).toUpperCase()}${base.slice(1)}`;
}

function openMenu(id, label) {
  return `<menu id="${escapeXml(id)}" label="${escapeXml(label)}">`;
}

function executeItem(command, indent) {
  const pad = ' '.repeat(indent);
  const item = `${pad}<item label="${escapeXml(labelFor(command))}">`;
  const action = `${pad}  <action name="Execute">`;
  const exec = `${pad}    <command>${escapeXml(command)}</command>`;
  const closeAction = `${pad}  </action>`;
  const closeItem = `${pad}</item>`;
  return [item, action, exec, closeAction, closeItem];
}

function separatorTag(label, indent) {
  return `${' '.repeat(indent)}<separator label="${escapeXml(label)}"/>`;
}

function closeMenu(id) {
  return `</menu> <!-- ${escapeXml(id)} -->`;
}

function menu(config) {
  const required = ['id', 'label', 'terminal', 'browser', 'fileManager', 'editor', 'separator', 'exit'];
  const missing = required.filter((key) => !config || !config[key]);
  if (missing.length) {
    throw new Error(`menu(): missing configuration keys: ${missing.join(', ')}`);
  }
  const lines = [openMenu(config.id, config.label)];
  const commands = [config.terminal, config.browser, config.fileManager, config.editor];
  for (const command of commands) {
    lines.push(...executeItem(command, 2));
  }
  lines.push(separatorTag(config.separator, 2));
  lines.push(...executeItem(config.exit, 2));
  lines.push(closeMenu(config.id));
  return lines.join('\n');
}

function describe(config) {
  const count = [config.terminal, config.browser, config.fileManager, config.editor, config.exit].length;
  return `Menu "${config.label}" defines ${count} launchers under separator ${config.separator}.`;
}

function main() {
  const config = {
    id: 'desktop menu',
    label: 'Desktop Menu',
    terminal: 'xterm',
    browser: 'firefox',
    fileManager: 'pcmanfm',
    editor: 'gedit',
    separator: 'System',
    exit: 'openbox --exit'
  };
  const xml = `<?xml version="1.0" encoding="UTF-8"?>\n${menu(config)}`;
  console.log(xml);
  console.log(`<!-- ${describe(config)} -->`);
}

main();

module.exports = { menu, escapeXml, labelFor, describe };

