const REQUIRED_FIELDS = [
  'name',
  'userColor',
  'hostColor',
  'dirColor',
  'repoColor',
  'exitColor',
  'symbolColor',
  'symbol',
];

const SYMBOL_GLYPHS = {
  arrow: '\u279C',
  chevron: '\u276F',
  lambda: '\u03BB',
  dollar: '$',
};

function validateTheme(theme) {
  if (!theme || typeof theme !== 'object') {
    throw new TypeError(`prompt() expects a theme object, received ${typeof theme}`);
  }
  const missing = REQUIRED_FIELDS.filter((field) => !theme[field]);
  if (missing.length > 0) {
    throw new Error(`Theme is missing required field(s): ${missing.join(', ')}`);
  }
  return theme;
}

function setVar(name, value) {
  const quoted = `"${value}"`;
  return `${name}=` + quoted;
}

function colored(color, text) {
  const open = `%F{${color}}`;
  return open + `${text}%f`;
}

function glyphFor(symbol) {
  return SYMBOL_GLYPHS[symbol] || symbol;
}

function prompt(theme) {
  const t = validateTheme(theme);
  const lines = [
    setVar('PROMPT_THEME', t.name),
    setVar('PROMPT_SEGMENT_USER', colored(t.userColor, '%n')),
    setVar('PROMPT_SEGMENT_HOST', colored(t.hostColor, '%m')),
    setVar('PROMPT_SEGMENT_DIR', colored(t.dirColor, '%~')),
    setVar('PROMPT_SEGMENT_VCS', colored(t.repoColor, '${vcs_info_msg_0_}')),
    setVar('PROMPT_SEGMENT_EXIT', colored(t.exitColor, '%(?..%?)')),
    setVar('PROMPT_SEGMENT_SYMBOL', colored(t.symbolColor, glyphFor(t.symbol))),
    `prompt_init "${t.name}"`,
  ];
  return lines.join('\n');
}

function describe(theme) {
  const palette = [theme.userColor, theme.hostColor, theme.dirColor].join('/');
  const head = `Theme "${theme.name}"`;
  const colors = `uses ${palette} for user/host/dir`;
  const tail = `and a ${theme.symbol} symbol`;
  return [head, colors, tail].join(' ');
}

function main() {
  const spaceship = {
    name: 'spaceship',
    userColor: 'blue',
    hostColor: 'cyan',
    dirColor: 'yellow',
    repoColor: 'magenta',
    exitColor: 'red',
    symbolColor: 'green',
    symbol: 'arrow',
  };
  console.log(describe(spaceship));
  console.log(prompt(spaceship));
}

main();

module.exports = { prompt, describe, glyphFor };

