function validate(environment) {
  const required = [
    'version', 'box', 'hostname', 'ipAddress', 'hostPath', 'guestPath', 'provider', 'memory'
  ];
  for (const field of required) {
    if (environment[field] === undefined || environment[field] === '') {
      throw new Error(`Missing configuration field: ${field}`);
    }
  }
  const memory = Number(environment.memory);
  if (!Number.isInteger(memory) || memory <= 0) {
    throw new Error(`Memory must be a whole number of megabytes, got ${environment.memory}`);
  }
  if (!/^\d{1,3}(\.\d{1,3}){3}$/.test(environment.ipAddress)) {
    throw new Error(`Invalid private network address: ${environment.ipAddress}`);
  }
  return memory;
}

function indent(level, statement) {
  return '  '.repeat(level) + statement;
}

function syncedFolder(environment) {
  const host = `"${environment.hostPath}"`;
  const guest = `"${environment.guestPath}"`;
  return `config.vm.synced_folder ${host}, ${guest}`;
}

function shellProvisioner(hostname) {
  const greeting = `echo Hello from ${hostname}`;
  return `config.vm.provision "shell", inline: "${greeting}"`;
}

function provision(environment) {
  const memory = validate(environment);
  const lines = [];
  lines.push(`Vagrant.configure("${environment.version}") do |config|`);
  lines.push(indent(1, `config.vm.box = "${environment.box}"`));
  lines.push(indent(1, `config.vm.hostname = "${environment.hostname}"`));
  lines.push(indent(1, `config.vm.network "private_network", ip: "${environment.ipAddress}"`));
  lines.push(indent(1, syncedFolder(environment)));
  lines.push(indent(1, `config.vm.provider "${environment.provider}" do |vb|`));
  lines.push(indent(2, `vb.memory = "${memory}"`));
  lines.push(indent(1, 'end'));
  lines.push(indent(1, shellProvisioner(environment.hostname)));
  lines.push('end');
  return lines.join('\n');
}

function describe(environment) {
  const mapping = `${environment.hostPath} => ${environment.guestPath}`;
  const rows = [];
  rows.push(`box:      ${environment.box}`);
  rows.push(`hostname: ${environment.hostname}`);
  rows.push(`address:  ${environment.ipAddress}`);
  rows.push(`folders:  ${mapping}`);
  rows.push(`provider: ${environment.provider}`);
  rows.push(`memory:   ${environment.memory} MB`);
  return rows.join('\n');
}

const example = {
  version: '2',
  box: 'ubuntu',
  hostname: 'devbox',
  ipAddress: '10.0.0.5',
  hostPath: '.',
  guestPath: '/vagrant',
  provider: 'virtualbox',
  memory: 2000
};

console.log(describe(example));
console.log(`\n${provision(example)}`);

module.exports = { provision, describe };

