function validate(project) {
  const required = [
    'toolVersion',
    'name',
    'version',
    'standard',
    'executable',
    'source',
    'library',
    'installDir',
  ];
  const missing = required.filter((key) => !project[key]);
  if (missing.length > 0) {
    throw new Error(`Missing project fields: ${missing.join(', ')}`);
  }
  if (!/^[0-9]+(\.[0-9]+)?(\.[0-9]+)?$/.test(String(project.toolVersion))) {
    throw new Error(`Invalid tool version: ${project.toolVersion}`);
  }
  if (!String(project.source).includes('.')) {
    throw new Error(`Source file needs an extension: ${project.source}`);
  }
  return project;
}

function build(project) {
  const {
    toolVersion,
    name,
    version,
    standard,
    executable,
    source,
    library,
    installDir,
  } = validate(project);

  const lines = [];
  lines.push(`cmake_minimum_required(VERSION ${toolVersion})`);
  lines.push(`project(${name} VERSION ${version})`);
  lines.push(`set(CMAKE_CXX_STANDARD ${standard})`);
  lines.push('set(CMAKE_CXX_STANDARD_REQUIRED ON)');
  lines.push(`add_executable(${executable} ${source})`);
  lines.push(`target_link_libraries(${executable} PRIVATE ${library})`);
  lines.push(`target_include_directories(${executable} PRIVATE \${CMAKE_SOURCE_DIR}/include)`);
  lines.push(`install(TARGETS ${executable} DESTINATION ${installDir})`);
  lines.push(`message(STATUS "Configured ${name} version ${version}")`);

  return lines.join('\n');
}

function describe(project) {
  const script = build(project);
  const count = script.split('\n').length;
  const header = `# ${project.name} build script (${count} directives)`;
  return `${header}\n${script}`;
}

function main() {
  const calculator = {
    toolVersion: '3.10',
    name: 'Calculator',
    version: '1.0.0',
    standard: 17,
    executable: 'calc',
    source: 'main.cpp',
    library: 'm',
    installDir: '/usr/local/bin',
  };

  console.log(describe(calculator));
}

main();

