const AS_RANGE = { min: 1, max: 4294967295 };

function requireFields(peer, fields) {
  const missing = fields.filter((name) => peer[name] === undefined || peer[name] === '');
  if (missing.length > 0) {
    throw new Error(`Missing BGP parameter(s): ${missing.join(', ')}`);
  }
}

function checkAsn(label, value) {
  const asn = Number(value);
  if (!Number.isInteger(asn) || asn < AS_RANGE.min || asn > AS_RANGE.max) {
    throw new Error(`${label} must be an integer between 1 and 4294967295, got "${value}"`);
  }
  return asn;
}

function checkAddress(label, value) {
  const octets = String(value).split('.');
  const valid = octets.length === 4 && octets.every((part) => /^\d{1,3}$/.test(part) && Number(part) < 256);
  if (!valid) {
    throw new Error(`${label} must be a dotted-quad IPv4 address, got "${value}"`);
  }
  return String(value);
}

function checkPrefix(value) {
  const [network, length] = String(value).split('/');
  checkAddress('network prefix', network);
  if (!/^\d{1,2}$/.test(length || '') || Number(length) > 32) {
    throw new Error(`network prefix "${value}" needs a mask length between 0 and 32`);
  }
  return `${network}/${Number(length)}`;
}

function routing(peer) {
  requireFields(peer, ['localAs', 'routerId', 'neighbor', 'remoteAs', 'description', 'addressFamily', 'prefix', 'routeMap']);
  const localAs = checkAsn('local AS', peer.localAs);
  const remoteAs = checkAsn('remote AS', peer.remoteAs);
  const routerId = checkAddress('router id', peer.routerId);
  const neighbor = checkAddress('neighbor', peer.neighbor);
  const prefix = checkPrefix(peer.prefix);
  const lines = [`router bgp ${localAs}`];
  lines.push(` bgp router-id ${routerId}`);
  lines.push(` neighbor ${neighbor} remote-as ${remoteAs}`);
  lines.push(` neighbor ${neighbor} description ${peer.description}`);
  lines.push(` address-family ${peer.addressFamily}`);
  lines.push(`  network ${prefix}`);
  lines.push(`  neighbor ${neighbor} route-map ${peer.routeMap} in`);
  lines.push(`  neighbor ${neighbor} activate`);
  return lines.join('\n');
}

function main() {
  const peer = {
    localAs: 65001,
    routerId: '1.1.1.1',
    neighbor: '192.0.2.1',
    remoteAs: 65002,
    description: 'TRANSIT-UPSTREAM',
    addressFamily: 'ipv4 unicast',
    prefix: '10.0.0.0/24',
    routeMap: 'RM-TRANSIT-IN',
  };
  console.log(routing(peer));
  try {
    routing({ ...peer, prefix: '10.0.0.0/40' });
  } catch (err) {
    console.error(`configuration rejected: ${err.message}`);
  }
}

main();

module.exports = { routing };

