const fs = require('fs');

const REQUIRED_FIELDS = ['name', 'version', 'release', 'description', 'arch', 'url', 'license', 'source'];

function validate(software) {
  const missing = REQUIRED_FIELDS.filter((field) => !software[field]);
  if (missing.length) {
    throw new Error(`package(): missing field(s): ${missing.join(', ')}`);
  }
  if (!/^\d+(\.\d+)*$/.test(String(software.version))) {
    throw new Error(`package(): "${software.version}" is not a usable version string`);
  }
  if (!/^\d+$/.test(String(software.release))) {
    throw new Error(`package(): release must be a whole number, got ${software.release}`);
  }
  return software;
}

function bare(variable, value) {
  return `${variable}=${value}`;
}

function doubleQuoted(variable, value) {
  return `${variable}="${value}"`;
}

function quotedArray(variable, value) {
  const entries = (Array.isArray(value) ? value : [value]).map((item) => `'${item}'`);
  return `${variable}=(${entries.join(' ')})`;
}

function sourceLine(software) {
  const segments = software.source.split('/');
  const archive = segments
    .pop()
    .split(software.version)
    .join('$pkgver')
    .split(software.name)
    .join('$pkgname');
  const base = segments.join('/').split(software.version).join('$pkgver');
  return doubleQuoted('source', `${base}/${archive}`);
}

function package(software) {
  const spec = validate(software);
  const directives = [
    bare('pkgname', spec.name),
    bare('pkgver', spec.version),
    bare('pkgrel', spec.release),
    doubleQuoted('pkgdesc', spec.description),
    quotedArray('arch', spec.arch),
    doubleQuoted('url', spec.url),
    quotedArray('license', spec.license),
    sourceLine(spec),
  ];
  return directives.join('\n');
}

const catalogue = [
  {
    name: 'htop',
    version: '3.2.2',
    release: '1',
    description: 'Interactive process viewer',
    arch: ['x86_64'],
    url: 'https://htop.dev',
    license: ['GPL2'],
    source: 'https://github.com/htop-dev/htop/releases/download/3.2.2/htop-3.2.2.tar.xz',
  },
  {
    name: 'jq',
    version: '1.7.1',
    release: '2',
    description: 'Command-line JSON processor',
    arch: ['x86_64', 'aarch64'],
    url: 'https://jqlang.github.io/jq/',
    license: ['MIT'],
    source: 'https://github.com/jqlang/jq/releases/download/jq-1.7.1/jq-1.7.1.tar.gz',
  },
];

for (const software of catalogue) {
  const target = `PKGBUILD.${software.name}`;
  fs.writeFileSync(target, `${package(software)}\n`);
  console.log(`wrote ${target} for ${software.name}-${software.version}-${software.release}`);
}

module.exports = { package };

