function validate(application) {
  const required = ['type', 'name', 'comment', 'exec', 'icon'];
  for (const field of required) {
    if (!application[field]) {
      throw new Error(`Missing required desktop entry field: ${field}`);
    }
  }
  if (typeof application.startupNotify !== 'boolean') {
    throw new Error(`StartupNotify must be a boolean, got ${typeof application.startupNotify}`);
  }
  return application;
}

function execLine(exec, args) {
  const startup = (args || '').trim();
  return startup ? `${exec} ${startup}` : exec;
}

function categoriesLine(category) {
  const tag = category.trim();
  return tag.endsWith(';') ? tag : `${tag};`;
}

function keywordsLine(name, category) {
  const tag = category.replace(/;+$/, '');
  return `${name} ${tag}`;
}

function launcher(application) {
  const app = validate(application);
  const lines = ['[Desktop Entry]'];
  lines.push(`Type=${app.type}`);
  lines.push(`Name=${app.name}`);
  lines.push(`Comment=${app.comment}`);
  lines.push(`Exec=${execLine(app.exec, app.args)}`);
  lines.push(`Icon=${app.icon}`);
  lines.push(`StartupNotify=${app.startupNotify}`);
