const REQUIRED = [
  'facility',
  'severity',
  'templateName',
  'format',
  'target',
  'port',
  'fallbackFile',
  'queueDir',
];

function validateRouting(routing) {
  for (const key of REQUIRED) {
    const value = routing[key];
    if (value === undefined || value === null || `${value}`.trim() === '') {
      throw new Error(`syslog: missing or empty routing field "${key}"`);
    }
  }
  const port = Number(routing.port);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error(`syslog: "${routing.port}" is not a usable destination port`);
  }
  return { ...routing, port };
}

function workDirectory(queueDir) {
  return `$WorkDirectory ${queueDir}`;
}

function formatTemplate(templateName, format) {
  const nameAttr = `name="${templateName}"`;
  return `template(${nameAttr} type="string" string="${format}")`;
}

function conditionOpen(facility, severity) {
  const facilityTest = `$syslogfacility-text == "${facility}"`;
  const severityTest = `$syslogseverity-text == "${severity}"`;
  return `if (${facilityTest} and ${severityTest}) then {`;
}

function forwardAction(target, port, templateName) {
  const address = `target="${target}" port="${port}"`;
  return `    action(type="omfwd" ${address} protocol="tcp" template="${templateName}"`;
}

function queueOptions(queueDir) {
  const spool = `queue.spoolDirectory="${queueDir}"`;
  return `           queue.type="linkedlist" queue.filename="fwd-queue" ${spool} queue.maxdiskspace="1g" queue.saveonshutdown="on" action.resumeRetryCount="-1")`;
}

function fileAction(fallbackFile) {
  return `    action(type="omfile" file="${fallbackFile}")`;
}

function syslog(routing) {
  const rule = validateRouting(routing);
  const lines = [
    workDirectory(rule.queueDir),
    'module(load="omfwd")',
    formatTemplate(rule.templateName, rule.format),
    conditionOpen(rule.facility, rule.severity),
    forwardAction(rule.target, rule.port, rule.templateName),
    queueOptions(rule.queueDir),
    fileAction(rule.fallbackFile),
    '    stop',
    '}',
    `# end of ${rule.facility} forwarding rule`,
  ];
  return lines.join('\n');
}

const routing = {
  facility: 'authpriv',
  severity: 'error',
  templateName: 'AuthPrivForward',
  format: '%TIMESTAMP:::date-rfc3339% %HOSTNAME% %syslogtag%%msg%\\n',
  target: 'logs.internal.example.com',
  port: 514,
  fallbackFile: '/var/log/authpriv-fallback.log',
  queueDir: '/var/spool/rsyslog',
};

const block = syslog(routing);
console.log(block);
console.log(`# ${block.split('\n').length} directives generated for ${routing.facility}.${routing.severity}`);

