function titleSection(recipe) {
  const heading = `Recipe: ${recipe.name}`;
  const credit = `by ${recipe.author}`;
  return [heading, credit];
}

function timingSection(recipe) {
  const prep = `Prep time: ${recipe.prepMinutes} minutes.`;
  const cook = `Cook time: ${recipe.cookMinutes} minutes.`;
  const total = recipe.prepMinutes + recipe.cookMinutes;
  const totalLine = `Total time: ${total} minutes.`;
  return [prep, cook, totalLine];
}

function formatIngredient(item) {
  if (!item.unit) {
    return `${item.quantity} ${item.name}`;
  }
  return `${item.quantity} ${item.unit} of ${item.name}`;
}

function ingredientsSection(recipe) {
  const lines = ['Ingredients:'];
  for (const item of recipe.ingredients) {
    lines.push(`- ${formatIngredient(item)}`);
  }
  return lines;
}

function instructionsSection(recipe) {
  const lines = ['Instructions:'];
  recipe.steps.forEach((action, index) => {
    lines.push(`Step ${index + 1}: ${action}`);
  });
  return lines;
}

function print(recipe) {
  const sections = [
    titleSection(recipe),
    timingSection(recipe),
    ingredientsSection(recipe),
    instructionsSection(recipe),
  ];
  return sections.map((lines) => lines.join('\n')).join('\n\n');
}

const pancakes = {
  name: 'Buttermilk Pancakes',
  author: 'Marie Leclerc',
  prepMinutes: 10,
  cookMinutes: 15,
  ingredients: [
    { quantity: 2, unit: 'cups', name: 'flour' },
    { quantity: 1, unit: 'tablespoon', name: 'sugar' },
    { quantity: 2, unit: '', name: 'eggs' },
    { quantity: 500, unit: 'millilitres', name: 'buttermilk' },
  ],
  steps: [
    'Whisk the dry ingredients together in a large bowl.',
    'Beat the eggs into the buttermilk, then fold into the dry mix.',
    'Ladle the batter onto a hot greased griddle and cook until golden.',
  ],
};

console.log(print(pancakes));
console.log(`\n(${pancakes.ingredients.length} ingredients, ${pancakes.steps.length} steps)`);

module.exports = {
  print,
  titleSection,
  timingSection,
  formatIngredient,
  ingredientsSection,
  instructionsSection,
};

