function teamsSection(match) {
  const home = `Home side ${match.homeTeam} takes the field.`;
  const away = `Visiting side ${match.awayTeam} answers the call.`;
  const league = `The fixture belongs to the ${match.league}.`;
  return [home, away, league];
}

function scoreSection(match) {
  const homeLine = `${match.homeTeam} have put up ${match.homeScore} goals.`;
  const awayLine = `${match.awayTeam} have replied with ${match.awayScore}.`;
  const periodLine = `Play is currently in the ${match.period}.`;
  return [homeLine, awayLine, periodLine];
}

function scorerSentence(event) {
  return `${event.player} struck in minute ${event.minute} for ${event.team}.`;
}

function scorersSection(match) {
  const events = match.scorers || [];
  if (events.length === 0) {
    return ['No goals have been recorded so far.'];
  }
  return events.map(scorerSentence);
}

function stadiumSection(match) {
  const venue = match.stadium || {};
  const nameLine = `The match is hosted at ${venue.name}.`;
  const crowdLine = `Attendance stands at ${formatCrowd(venue.attendance)} spectators.`;
  const cityLine = `Supporters have gathered in ${venue.city}.`;
  return [nameLine, crowdLine, cityLine];
}

function formatCrowd(attendance) {
  const digits = String(Math.round(attendance));
  return digits.replace(/\B(?=(\d{3})+$)/g, ',');
}

