  taxRate: 0.1,
  tipRate: 0.15,
  items: [
    { quantity: 2, name: 'Tagliatelle al ragu', price: 14.5 },
    { quantity: 1, name: 'Insalata mista', price: 6.0 },
    { quantity: 3, name: 'Espresso', price: 2.0 },
  ],
};

console.log(receipt(dinner));

