const pad = (n) => String(n).padStart(2, '0');

function timeMarker(totalSeconds) {
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const clock = `${pad(minutes)}:${pad(seconds)}`;
  return hours > 0 ? `${hours}:${clock}` : clock;
}

function metadataLines(episode) {
  const lines = [];
  lines.push(`Title: ${episode.title}`);
  lines.push(`Episode: ${episode.number}`);
  lines.push(`Duration: ${episode.durationMinutes} minutes`);
  return lines;
}

function guestLines(guest) {
  if (!guest) {
    return ['Guest: none this week'];
  }
  const lines = [];
  lines.push(`Guest: ${guest.name}`);
  lines.push(`Occupation: ${guest.occupation}`);
  lines.push(`Website: ${guest.website}`);
  return lines;
}

function timestampLines(topics) {
  return topics.map((topic) => {
    const marker = timeMarker(topic.atSeconds);
    return `[${marker}] ${topic.title} — with ${topic.speaker}`;
  });
}

function linkLines(links) {
  return links.map((link) => `${link.name} (${link.url}) — ${link.description}.`);
}

function notes(episode) {
  const sections = [];
  sections.push(metadataLines(episode).join('\n'));
  sections.push(guestLines(episode.guest).join('\n'));

  const topics = episode.topics || [];
  if (topics.length > 0) {
    const body = timestampLines(topics).join('\n');
    sections.push(`Timestamps:\n${body}`);
  }

  const links = episode.links || [];
  if (links.length > 0) {
    const body = linkLines(links).join('\n');
    sections.push(`Links:\n${body}`);
  }

  return sections.join('\n\n');
}

