const buildScheme = ({ protocol, appId, region }) => [
  `protocol: ${protocol}`,
  `app id: ${appId}`,
  `region: ${region}`,
].join('\n');

const buildResourcePath = ({ resourceType, resourceId }) => {
  const typeLine = `resource type: ${resourceType}`;
  const idLine = `resource id: ${resourceId}`;
  return `${typeLine}\n${idLine}`;
};

const buildQuery = ({ campaign, source, medium }) => [
  `campaign: ${campaign}`,
  `source: ${source}`,
  `medium: ${medium}`,
].join('\n');

const buildFallback = ({ webUrl, storeId, language }) => [
  `web url: ${webUrl}`,
  `store id: ${storeId}`,
  `language: ${language}`,
].join('\n');

const buildUri = (route) => {
  const query = [
    `utm_campaign=${route.campaign}`,
    `utm_source=${route.source}`,
    `utm_medium=${route.medium}`,
  ].join('&');
  const path = `${route.resourceType}/${route.resourceId}`;
  return `${route.protocol}://${route.appId}/${path}?${query}`;
};

function deeplink(route) {
  const missing = ['protocol', 'appId', 'region', 'resourceType', 'resourceId']
    .filter((key) => !route[key]);
  if (missing.length) {
    throw new Error(`deeplink: missing route fields: ${missing.join(', ')}`);
  }
  return [
    buildScheme(route),
    buildResourcePath(route),
    buildQuery(route),
    buildFallback(route),
    `uri: ${buildUri(route)}`,
  ].join('\n');
}

