const REQUIRED_FIELDS = [
  'vintage', 'varietal', 'region',
  'clarity', 'colorIntensity', 'hue',
  'condition', 'aromaIntensity', 'aromas',
  'sweetness', 'acidity', 'tannin'
];

function validateEvaluation(wine) {
  for (const field of REQUIRED_FIELDS) {
    if (wine[field] === undefined) {
      throw new Error(`The tasting evaluation is missing the ${field} entry.`);
    }
  }
}

function formatList(items) {
  const list = Array.isArray(items) ? items : [items];
  if (list.length === 1) {
    return String(list[0]);
  }
  const lead = list.slice(0, -1).join(', ');
  const closer = ` and ${list[list.length - 1]}`;
  return lead + closer;
}

function describeIdentity(wine) {
  const vintageLine = `This bottle comes from the ${wine.vintage} harvest.`;
  const varietalLine = `It was vinified from ${wine.varietal} grapes.`;
  const regionLine = `The fruit was grown in the ${wine.region} region.`;
  return [vintageLine, varietalLine, regionLine];
}

function describeAppearance(wine) {
  const clarityLine = `In the glass the liquid appears ${wine.clarity}.`;
  const intensityLine = `Its colour intensity reads as ${wine.colorIntensity}.`;
  const hueLine = `The hue settles into a distinct ${wine.hue} tone.`;
  return [clarityLine, intensityLine, hueLine];
}

function describeNose(wine) {
  const conditionLine = `On the nose the wine is ${wine.condition}.`;
  const intensityLine = `The aromatic intensity is ${wine.aromaIntensity}.`;
  const aromaLine = `Aromas of ${formatList(wine.aromas)} lead the bouquet.`;
  return [conditionLine, intensityLine, aromaLine];
}

function describePalate(wine) {
  const sweetnessLine = `On the palate it tastes ${wine.sweetness}.`;
  const acidityLine = `The acidity comes across as ${wine.acidity}.`;
  const tanninLine = `Tannins are ${wine.tannin} and frame the finish.`;
  return [sweetnessLine, acidityLine, tanninLine];
}

function tasting(wine) {
  validateEvaluation(wine);
  const sentences = [
    ...describeIdentity(wine),
    ...describeAppearance(wine),
    ...describeNose(wine),
    ...describePalate(wine)
  ];
  return sentences.join('\n');
}

const bordeaux = {
  vintage: 2010,
  varietal: 'Cabernet Sauvignon',
  region: 'Bordeaux',
  clarity: 'clear and bright',
  colorIntensity: 'deep',
  hue: 'ruby with garnet edges',
  condition: 'clean',
  aromaIntensity: 'pronounced',
  aromas: ['blackcurrant', 'cedar', 'graphite', 'violet'],
  sweetness: 'dry',
  acidity: 'medium plus',
  tannin: 'firm yet ripe'
};

console.log(`Tasting note for the ${bordeaux.vintage} ${bordeaux.varietal}:`);
console.log(tasting(bordeaux));

