function formatDate(dateString) {
  const parsed = new Date(dateString);
  if (Number.isNaN(parsed.getTime())) {
    return `${dateString}`;
  }
  const month = parsed.toLocaleString('en-US', { month: 'long' });
  return `${month} ${parsed.getUTCDate()}, ${parsed.getUTCFullYear()}`;
}

function describeSpread(spreadType) {
  const label = spreadType.trim().toLowerCase();
  if (label.includes('three') || label.includes('past')) {
    return `the ${spreadType} spread, which traces one thread from memory into possibility`;
  }
  return `the ${spreadType} spread, chosen to frame your question with three turning points`;
}

function creditSources(readerName, deckName) {
  return `${readerName} shuffled and cut the ${deckName} for you`;
}

function greet(seekerName) {
  return `Welcome, ${seekerName}, and thank you for sitting down at this table.`;
}

function blessing(seekerName) {
  const initial = seekerName.trim().charAt(0).toUpperCase();
  return `May the letter ${initial} that opens your name also open every door you walk toward, ${seekerName}.`;
}

function requireField(reading, field) {
  const value = reading ? reading[field] : undefined;
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`Reading is missing a usable "${field}" value.`);
  }
  return value.trim();
}

function interpret(reading) {
  const seekerName = requireField(reading, 'seekerName');
  const pastCard = requireField(reading, 'pastCard');
  const presentCard = requireField(reading, 'presentCard');
  const futureCard = requireField(reading, 'futureCard');
  const deckName = requireField(reading, 'deckName');
  const readerName = requireField(reading, 'readerName');
  const spreadType = requireField(reading, 'spreadType');
  const sessionDate = requireField(reading, 'sessionDate');

