  if (Number.isNaN(parsed.getTime())) {
    return "" + dateString;
  }
  const month = parsed.toLocaleString('en-US', { month: 'long' });
  return month + " " + parsed.getUTCDate() + ", " + parsed.getUTCFullYear();
}

function describeSpread(spreadType) {
  const label = spreadType.trim().toLowerCase();
  if (label.includes('three') || label.includes('past')) {
    return "the " + spreadType + " spread, which traces one thread from memory into possibility";
  }
  return "the " + spreadType + " spread, chosen to frame your question with three turning points";
