function formatDate(dateInput) {
  const date = dateInput instanceof Date ? dateInput : new Date(dateInput);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`Encounter date "${dateInput}" is not a valid date`);
  }
  const month = `${date.getMonth() + 1}`.padStart(2, '0');
  const day = `${date.getDate()}`.padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
}

function formatMonster(monster) {
  const initiative = Number(monster.initiative);
  const rolled = Number.isFinite(initiative) ? initiative : 0;
  return `  ${monster.name} rolled initiative ${rolled}`;
}

function summarize(encounter) {
  const {
    campaignName,
    environmentType,
    partyLevel,
    difficultyRating,
    totalExperience,
    averageHitPoints,
    monsters = [],
    encounterDate,
  } = encounter;

  const lines = [];
  lines.push(`Campaign "${campaignName}" — encounter of ${formatDate(encounterDate)}`);
  lines.push(`The party finds itself in ${environmentType} terrain.`);
  lines.push(`Party level: ${partyLevel}`);
  lines.push(`Warning: this encounter is rated ${difficultyRating.toUpperCase()}.`);
  lines.push(`Total experience on offer: ${totalExperience.toLocaleString('en-US')} XP`);
  lines.push(`Average hit points per creature: ${averageHitPoints.toFixed(1)}`);

  for (const monster of monsters) {
    lines.push(formatMonster(monster));
  }

  lines.push(`Monsters in this encounter: ${monsters.length}`);
  return lines;
}

function orderByInitiative(monsters) {
  return [...monsters].sort((a, b) => b.initiative - a.initiative);
}

