  campaignName: 'Hollow Crowns',
  environmentType: 'swamp',
  partyLevel: 7,
  difficultyRating: 'deadly',
  totalExperience: 5400,
  averageHitPoints: 63.5,
  monsters: [
    { name: 'Bog Hag', initiative: 18 },
    { name: 'Giant Crocodile', initiative: 9 },
    { name: 'Will-o-Wisp', initiative: 21 },
  ],
  encounterDate: '2026-03-14',
};

