function formatLatitude(latitude) {
  const hemisphere = latitude >= 0 ? 'N' : 'S';
  const degrees = Math.floor(Math.abs(latitude));
  const minutes = (Math.abs(latitude) - degrees) * 60;
  return `${hemisphere} ${degrees}° ${minutes.toFixed(3)}'`;
}

function formatLongitude(longitude) {
  const hemisphere = longitude >= 0 ? 'E' : 'W';
  const degrees = Math.floor(Math.abs(longitude));
  const minutes = (Math.abs(longitude) - degrees) * 60;
  return `${hemisphere} ${degrees}° ${minutes.toFixed(3)}'`;
}

function ratingLabel(value) {
  const stars = '★'.repeat(Math.floor(value)) + (value % 1 ? '½' : '');
  return `${value.toFixed(1)} ${stars}`;
}

function validate(cache) {
  const required = ['name', 'owner', 'size', 'latitude', 'longitude', 'difficulty', 'terrain', 'hint'];
  const missing = required.filter((field) => cache[field] === undefined || cache[field] === null);
  if (missing.length) {
    throw new Error(`Cache listing is missing: ${missing.join(', ')}`);
  }
  if (Math.abs(cache.latitude) > 90) {
    throw new Error(`Latitude out of range: ${cache.latitude}`);
  }
  if (Math.abs(cache.longitude) > 180) {
    throw new Error(`Longitude out of range: ${cache.longitude}`);
  }
}

function build(cache) {
  validate(cache);
  const lines = [];
  lines.push(`You have found the geocache "${cache.name}"!`);
  lines.push(`This cache was placed and is maintained by ${cache.owner}.`);
  lines.push(`Container size: ${cache.size}.`);
  lines.push(`Latitude: ${formatLatitude(cache.latitude)}`);
  lines.push(`Longitude: ${formatLongitude(cache.longitude)}`);
  lines.push(`Difficulty ${ratingLabel(cache.difficulty)} / Terrain ${ratingLabel(cache.terrain)}`);
  lines.push(`Spoiler warning, the hint reads: ${cache.hint}`);
  lines.push(`Checksum: ${(cache.difficulty + cache.terrain).toFixed(1)}`);
  return lines;
}

function render(cache) {
  const listing = build(cache).map((line, index) => `${index + 1}. ${line}`);
  return listing.join('\n');
}

function main() {
  const caches = [
    {
      name: 'Mossy Bridge',
      owner: 'TrailFinder42',
      size: 'small',
      latitude: 47.6205,
      longitude: -122.3493,
      difficulty: 2.5,
      terrain: 1.5,
      hint: 'Look under the third plank from the north end.',
    },
    {
      name: 'Summit Signal',
      owner: 'AlpineAnna',
      size: 'micro',
      latitude: 46.8523,
      longitude: 200.5,
      difficulty: 4,
      terrain: 5,
      hint: 'Magnetic, behind the survey marker.',
    },
  ];
  for (const cache of caches) {
    try {
      console.log(render(cache));
    } catch (error) {
      console.error(`Could not build listing for ${cache.name}: ${error.message}`);
    }
  }
}

main();

module.exports = { build, render, formatLatitude, formatLongitude };

