function validate(pattern) {
  const required = ['name', 'juggler', 'propCount', 'propType', 'startingHand', 'maxHeight', 'avgHeight', 'durationSeconds'];
  const missing = required.filter((key) => pattern[key] === undefined);
  if (missing.length > 0) {
    throw new Error(`Pattern description is missing: ${missing.join(', ')}`);
  }
  if (pattern.propCount <= 0) {
    throw new Error(`A pattern needs at least one prop, got ${pattern.propCount}`);
  }
  if (pattern.durationSeconds < 0) {
    throw new Error(`Duration cannot be negative, got ${pattern.durationSeconds}`);
  }
}

function formatHeight(meters) {
  return `${meters.toFixed(2)} m`;
}

function pluralize(count, noun) {
  const word = count === 1 ? noun : `${noun}s`;
  return `${count} ${word}`;
}

function describe(pattern) {
  validate(pattern);
  const totalThrows = pattern.durationSeconds * pattern.propCount;
  return [
    `${pattern.name} is juggled by ${pattern.juggler}.`,
    `It uses ${pluralize(pattern.propCount, 'prop')}.`,
    `The props are ${pattern.propType}.`,
    `The first throw comes from the ${pattern.startingHand} hand.`,
    `The highest throw reaches ${formatHeight(pattern.maxHeight)}.`,
    `The average throw reaches ${formatHeight(pattern.avgHeight)}.`,
    `The run lasts ${pattern.durationSeconds} seconds.`,
    `That works out to ${totalThrows} throws in total.`,
  ];
}

function report(pattern) {
  const body = describe(pattern)
    .map((line, index) => `  ${index + 1}. ${line}`)
    .join('\n');
  return `=== ${pattern.name} ===\n${body}`;
}

function main() {
  const patterns = [
    {
      name: 'Cascade',
      juggler: 'Ada Lovelace',
      propCount: 3,
      propType: 'leather beanbags',
      startingHand: 'right',
      maxHeight: 1.8,
      avgHeight: 1.55,
      durationSeconds: 45,
    },
    {
      name: 'Mills Mess',
      juggler: 'Grace Hopper',
      propCount: 5,
      propType: 'silicone stage balls',
      startingHand: 'left',
      maxHeight: 2.4,
      avgHeight: 2.05,
      durationSeconds: 30,
    },
  ];

  for (const pattern of patterns) {
    console.log(report(pattern));
  }
}

main();

