class GopherMenuBuilder {
    constructor(menu) {
        this.menu = menu;
        this.lines = [];
        this.defaultSelector = 'fake';
    }

    addInfo(text) {
        const itemType = 'i';
        const display = `${itemType}${text}`;
        const routing = `\t${this.defaultSelector}\t`;
        const host = `${routing}${this.menu.serverHost}`;
        const port = `\t${this.menu.serverPort}`;
        this.lines.push(display + host + port);
    }

    addEmail(email) {
        const mailType = 'm';
        const display = `${mailType}Contact Admin`;
        const mailto = `\tmailto:${email}\t`;
        const host = `${mailto}${this.menu.serverHost}`;
        const port = `\t${this.menu.serverPort}`;
        this.lines.push(display + host + port);
    }

    addText(content) {
        this.addInfo(content);
    }

    build() {
        const titleText = `Menu: ${this.menu.menuTitle}`;
        this.addInfo(titleText);

        const hostInfo = `Host: ${this.menu.serverHost}`;
        const portInfo = ` Port: ${this.menu.serverPort}`;
        this.addInfo(hostInfo + portInfo);

        const emailString = `${this.menu.adminEmail}`;
        this.addEmail(emailString);

        const welcome = `Welcome: ${this.menu.welcomeText}`;
        this.addText(welcome);

        const itemsCount = `Total Items: ${this.menu.totalItems}`;
        this.addInfo(itemsCount);

        const footer = `Footer: ${this.menu.footerText}`;
