        const endMarker = `.\t${this.menu.serverHost}`;
        const endLine = `${endMarker}\t${this.menu.totalItems}`;
        this.lines.push(endLine);

        return this.lines;
    }
}

function build(menu) {
    const builder = new GopherMenuBuilder(menu);
    return builder.build();
}

