function formatRightAscension(ra) {
  if (typeof ra === 'string') return ra;
  const hours = Math.floor(ra);
  const totalMinutes = (ra - hours) * 60;
  const minutes = Math.floor(totalMinutes);
  const seconds = ((totalMinutes - minutes) * 60).toFixed(1);
  const hm = `${hours}h ${String(minutes).padStart(2, '0')}m`;
  return `${hm} ${String(seconds).padStart(4, '0')}s`;
}

function formatDeclination(dec) {
  if (typeof dec === 'string') return dec;
  const sign = dec < 0 ? '-' : '+';
  const abs = Math.abs(dec);
  const degrees = Math.floor(abs);
  const totalArcmin = (abs - degrees) * 60;
  const arcmin = Math.floor(totalArcmin);
  const arcsec = Math.round((totalArcmin - arcmin) * 60);
  const dm = `${sign}${degrees}° ${String(arcmin).padStart(2, '0')}'`;
  return `${dm} ${String(arcsec).padStart(2, '0')}"`;
}

function validate(target) {
  const required = ['name', 'constellation', 'catalog', 'rightAscension',
    'declination', 'magnitude', 'surfaceBrightness', 'advice'];
  const missing = required.filter((key) => target[key] === undefined);
  if (missing.length > 0) {
    throw new Error(`Incomplete target data, missing: ${missing.join(', ')}`);
  }
}

function guide(target) {
  validate(target);
  const ra = formatRightAscension(target.rightAscension);
  const dec = formatDeclination(target.declination);
  const magnitude = Number(target.magnitude).toFixed(1);
  const brightness = Number(target.surfaceBrightness).toFixed(1);

  const instructions = [];
  instructions.push(`Tonight we observe ${target.name} in ${target.constellation}.`);
  instructions.push(`Its catalog designation is ${target.catalog}.`);
  instructions.push(`Point the telescope to right ascension ${ra}.`);
  instructions.push(`Then swing to declination ${dec}.`);
  instructions.push(`Expect an apparent magnitude of ${magnitude}.`);
  instructions.push(`Its surface brightness is ${brightness} mag/arcsec².`);
  instructions.push(`Observing advice: ${target.advice}`);
  instructions.push(`Confirm ${target.name} sits at right ascension ${ra}.`);
  return instructions;
}

function printSession(target) {
  const header = `=== Observing plan for ${target.catalog} ===`;
  console.log(header);
  guide(target).forEach((line, index) => {
    console.log(`${String(index + 1).padStart(2, ' ')}. ${line}`);
  });
}

const targets = [
  {
    name: 'The Whirlpool Galaxy',
    constellation: 'Canes Venatici',
    catalog: 'M51',
    rightAscension: 13.4979,
    declination: 47.1952,
    magnitude: 8.4,
    surfaceBrightness: 12.6,
    advice: 'use low power and averted vision to trace the spiral arms',
  },
  {
    name: 'The Ring Nebula',
    constellation: 'Lyra',
    catalog: 'M57',
    rightAscension: 18.8931,
    declination: 33.0292,
    magnitude: 8.8,
    surfaceBrightness: 9.3,
    advice: 'an O-III filter sharpens the annulus at high magnification',
  },
];

targets.forEach(printSession);

