function gravity(value) {
  return Number(value).toFixed(3);
}

function percent(value) {
  return `${Number(value).toFixed(1)}%`;
}

function volume(litres) {
  const gallons = (Number(litres) / 3.78541).toFixed(1);
  return `${Number(litres).toFixed(1)} L (${gallons} gal)`;
}

function attenuation(originalGravity, finalGravity) {
  const drop = originalGravity - finalGravity;
  const ratio = (drop / (originalGravity - 1)) * 100;
  return `${ratio.toFixed(0)}% apparent attenuation`;
}

function label(style, alcoholPercentage) {
  const strength = alcoholPercentage >= 7.5 ? "Strong" : "Session";
  return `${strength} ${style} — ${percent(alcoholPercentage)} ABV`;
}

function format(recipe) {
  const {
    beerStyle,
    batchVolume,
    originalGravity,
    finalGravity,
    alcoholPercentage,
    bitternessIbu,
    boilTime,
    primaryYeast,
  } = recipe;

  const lines = [];
  lines.push(`${beerStyle} — batch of ${volume(batchVolume)}`);
  lines.push(`Target original gravity: ${gravity(originalGravity)}`);
  lines.push(`Target final gravity: ${gravity(finalGravity)}`);
  lines.push(`Estimated alcohol: ${percent(alcoholPercentage)} by volume`);
  lines.push(`Bitterness: ${bitternessIbu} IBU`);
  lines.push(`Boil for ${boilTime} minutes`);
  lines.push(`Pitch ${primaryYeast} as the primary yeast`);
  lines.push(`Label: ${label(beerStyle, alcoholPercentage)}`);
  return lines;
}

function report(recipe) {
  const header = `=== ${recipe.beerStyle} brew sheet ===`;
  const body = format(recipe)
    .map((line, index) => `${index + 1}. ${line}`)
    .join("\n");
  const footer = attenuation(recipe.originalGravity, recipe.finalGravity);
  return `${header}\n${body}\nYeast performance: ${footer}`;
}

const recipes = [
  {
    beerStyle: "American IPA",
    batchVolume: 20,
    originalGravity: 1.064,
    finalGravity: 1.012,
    alcoholPercentage: 6.8,
    bitternessIbu: 65,
    boilTime: 60,
    primaryYeast: "Safale US-05",
  },
  {
    beerStyle: "Belgian Tripel",
    batchVolume: 23,
    originalGravity: 1.078,
    finalGravity: 1.01,
    alcoholPercentage: 9,
    bitternessIbu: 30,
    boilTime: 90,
    primaryYeast: "Wyeast 3787",
  },
];

for (const recipe of recipes) {
  console.log(report(recipe));
  console.log("");
}

