const REQUIRED_FIELDS = [
  'bedName',
  'zone',
  'frostDate',
  'sunExposure',
  'soilType',
  'waterFrequency',
  'primaryCrop',
  'companionPlant',
];

function validate(garden) {
  const missing = REQUIRED_FIELDS.filter((field) => !garden || !garden[field]);
  if (missing.length > 0) {
    throw new Error(`Garden bed is missing required details: ${missing.join(', ')}`);
  }
}

function formatDate(frostDate) {
  const parsed = new Date(frostDate);
  if (Number.isNaN(parsed.getTime())) {
    return String(frostDate);
  }
  const month = parsed.toLocaleString('en-US', { month: 'long' });
  return `${month} ${parsed.getUTCDate()}`;
}

function harvestWindow(frostDate) {
  const parsed = new Date(frostDate);
  if (Number.isNaN(parsed.getTime())) {
    return `roughly 10 weeks after ${frostDate}`;
  }
  const harvest = new Date(parsed.getTime());
  harvest.setUTCDate(harvest.getUTCDate() + 70);
  return `around ${formatDate(harvest.toISOString())}`;
}

function guide(garden) {
  validate(garden);
  const frost = formatDate(garden.frostDate);

  return [
    `Welcome to the ${garden.bedName} bed, planted in hardiness zone ${garden.zone}.`,
    `Watch the calendar: the last expected frost falls on ${frost}, so hold tender seedlings until it passes.`,
    `This bed receives ${garden.sunExposure}, and the layout should keep taller plants from shading it.`,
    `Build the soil to a ${garden.soilType} texture before anything goes in the ground.`,
    `Water ${garden.waterFrequency}, adjusting only for heavy rain or a long dry spell.`,
    `The star of the bed is ${garden.primaryCrop}, so give it the center rows and the best drainage.`,
    `Tuck ${garden.companionPlant} along the edges as a companion to deter pests and draw pollinators.`,
    `Expect the first ${garden.primaryCrop} harvest ${harvestWindow(garden.frostDate)}, counting forward from the ${frost} frost date.`,
  ];
}

function printGuide(garden) {
  const lines = guide(garden);
  console.log(`--- ${garden.bedName} ---`);
  lines.forEach((line, index) => {
    console.log(`${index + 1}. ${line}`);
  });
}

const beds = [
  {
    bedName: 'South Terrace',
    zone: '6b',
    frostDate: '2026-05-10',
    sunExposure: 'full sun, about eight hours a day',
    soilType: 'loose, sandy loam',
    waterFrequency: 'deeply twice a week',
    primaryCrop: 'San Marzano tomatoes',
    companionPlant: 'sweet basil',
  },
  {
    bedName: 'Shade Corner',
    zone: '8a',
    frostDate: '2026-03-28',
    sunExposure: 'dappled morning light',
    soilType: 'rich, moisture-holding compost blend',
    waterFrequency: 'lightly every other day',
    primaryCrop: 'buttercrunch lettuce',
    companionPlant: 'chives',
  },
];

beds.forEach(printGuide);

