function formatTankHeader(tank) {
  return `Tank #${tank.tankNumber} — Species: ${tank.species}`;
}

function formatWaterLine(tank) {
  const temperature = `Temperature: ${tank.temperature.toFixed(1)}°C`;
  return `${temperature} | pH: ${tank.phLevel.toFixed(1)}`;
}

function formatEquipmentLine(tank) {
  const filter = `Filter: ${tank.filterStatus}`;
  return `${filter} | Lighting: ${tank.lightingMode}`;
}

function buildAlerts(tank) {
  const alerts = [];
  if (tank.temperature < 20 || tank.temperature > 28) {
    alerts.push(`WARNING: critical temperature in tank ${tank.tankNumber}!`);
  }
  if (tank.phLevel < 7) {
    alerts.push(`NOTE: water in tank ${tank.tankNumber} is acidic.`);
  }
  return alerts;
}

function countActiveFilters(tanks) {
  return tanks.filter((tank) => String(tank.filterStatus).toLowerCase() === 'active').length;
}

function summarize(tanks) {
  if (!Array.isArray(tanks) || tanks.length === 0) {
    throw new Error('summarize() requires a non-empty list of tanks');
  }

  const lines = [`AQUARIUM FACILITY REPORT — ${tanks.length} tank(s)`];
  lines.push(`Daily report generated on ${new Date().toISOString().slice(0, 10)}`);
  lines.push('');

  for (const tank of tanks) {
    lines.push(formatTankHeader(tank));
    lines.push(`  ${formatWaterLine(tank)}`);
    lines.push(`  ${formatEquipmentLine(tank)}`);
    for (const alert of buildAlerts(tank)) {
      lines.push(`  ${alert}`);
    }
    lines.push('');
  }

  const active = countActiveFilters(tanks);
  lines.push(`Active filters: ${active} of ${tanks.length}`);
  lines.push(`Next scheduled facility feeding: ${tanks[0].feedingTime}`);

  return lines.join('\n');
}

const facility = [
  {
    tankNumber: 1,
    species: 'Clownfish',
    temperature: 25,
    phLevel: 8,
    filterStatus: 'active',
    lightingMode: 'day',
    feedingTime: '12:00 noon',
  },
  {
    tankNumber: 2,
    species: 'Neon Tetra',
    temperature: 18.5,
    phLevel: 6.4,
    filterStatus: 'offline',
    lightingMode: 'night',
    feedingTime: '18:00',
  },
];

console.log(summarize(facility));

module.exports = { summarize, countActiveFilters, buildAlerts };

