  const total = rides.reduce((sum, ride) => sum + Number(ride.waitTime), 0);
  return total / rides.length;
}

function validateRide(ride, index) {
  if (typeof ride.name !== 'string' || ride.name.trim() === '') {
    throw new Error('Ride at index ' + index + ' is missing a name');
  }
  if (!Number.isFinite(Number(ride.waitTime))) {
    throw new Error('Ride ' + ride.name + ' has a non-numeric wait time');
  }
  if (!Number.isFinite(Number(ride.maxCapacity))) {
    throw new Error('Ride ' + ride.name + ' has a non-numeric maximum capacity');
  }
}

function report(rides) {
  if (!Array.isArray(rides)) {
    throw new TypeError('Expected an array of rides, received ' + typeof rides);
  }
  rides.forEach(validateRide);

  const lines = ['Theme Park Ride Report - ' + rides.length + ' ride(s) reported'];
  lines.push(parkStatus(rides));

  for (const ride of rides) {
    lines.push(formatRideHeading(ride));
    lines.push(formatCapacityLine(ride));
    lines.push(formatInspectorLine(ride));
    if (ride.fastTrack) {
      lines.push('  FAST TRACK OPEN for ' + ride.name);
    }
    if (Number(ride.waitTime) > 60) {
      lines.push('  WARNING: ' + ride.name + ' is experiencing a severe delay');
    }
  }

  const average = averageWait(rides).toFixed(1);
  lines.push('Average wait time across all rides: ' + average + ' minutes');
  lines.push('Report complete for ' + rides.length + ' ride(s).');

  return lines.join('\n');
}

const parkRides = [
  { name: 'rollercoaster', waitTime: 45, status: 'running', maxCapacity: 100, fastTrack: true, inspector: 'John' },
  { name: 'haunted mansion', waitTime: 75, status: 'running', maxCapacity: 40, fastTrack: false, inspector: 'Maria' },
  { name: 'log flume', waitTime: 20, status: 'closed', maxCapacity: 60, fastTrack: true, inspector: 'Ahmed' },
];

console.log(report(parkRides));

module.exports = { report, parkStatus, averageWait };

