function formatDuration(minutes) {
  const unit = minutes === 1 ? 'minute' : 'minutes';
  return `${minutes} ${unit}`;
}

function totalDuration(exhibits) {
  return exhibits.reduce((sum, exhibit) => sum + Number(exhibit.durationMinutes || 0), 0);
}

function welcomeHeader(count) {
  const noun = count === 1 ? 'exhibit' : 'exhibits';
  return `Welcome to our museum tour featuring ${count} ${noun}.`;
}

function durationHeader(exhibits) {
  return `The complete tour lasts ${formatDuration(totalDuration(exhibits))}.`;
}

function validateExhibit(exhibit, index) {
  if (!exhibit || typeof exhibit !== 'object') {
    throw new TypeError(`Exhibit at position ${index} is not an object.`);
  }
  if (exhibit.exhibitNumber === undefined) {
    throw new TypeError(`Exhibit at position ${index} is missing an exhibit number.`);
  }
  if (!Number.isFinite(Number(exhibit.durationMinutes))) {
    throw new TypeError(`Exhibit ${exhibit.exhibitNumber} has a non-numeric duration.`);
  }
}

function exhibitLines(exhibit) {
  const lines = [];
  lines.push(`Welcome to exhibit number ${exhibit.exhibitNumber}.`);
  lines.push(`Here you see the ${exhibit.artifactName}, dating from the ${exhibit.historicalEra}.`);
  lines.push(`This artifact was discovered by ${exhibit.discovererName}.`);
  lines.push(`Please listen for the next ${formatDuration(exhibit.durationMinutes)}.`);
  if (exhibit.interactiveDisplay) {
    lines.push(`Touch the screen at exhibit number ${exhibit.exhibitNumber} to explore further.`);
  }
  return lines;
}

function closingLines(count) {
  const noun = count === 1 ? 'exhibit' : 'exhibits';
  return [
    'Thank you for completing the tour.',
    `After visiting all ${count} ${noun}, please continue to the gift shop.`
  ];
}

function script(exhibits) {
  if (!Array.isArray(exhibits)) {
    throw new TypeError(`Expected a list of exhibits, received ${typeof exhibits}.`);
  }
  exhibits.forEach(validateExhibit);
  const lines = [welcomeHeader(exhibits.length), durationHeader(exhibits)];
  for (const exhibit of exhibits) {
    lines.push(...exhibitLines(exhibit));
  }
  lines.push(...closingLines(exhibits.length));
  return lines.join('\n');
}

const tour = [
  {
    exhibitNumber: 1,
    artifactName: 'vase',
    historicalEra: 'bronze age',
    discovererName: 'Smith',
    durationMinutes: 5,
    interactiveDisplay: true
  }
];

console.log(script(tour));

module.exports = { script, formatDuration, totalDuration };

