function formatAngles(rotationAngle, phaseShift) {
  const theta = Number(rotationAngle).toFixed(4);
  const phi = Number(phaseShift).toFixed(4);
  return `params theta=${theta} phi=${phi}`;
}

function formatErrorRate(rate) {
  return `error rate expected ${Number(rate).toFixed(5)}`;
}

function describeOperation(op, index) {
  const name = String(op.type).toLowerCase();
  const lines = [`op ${index}: ${name} applied to qubit q${op.target}`];

  if (op.control !== null && op.control !== undefined) {
    lines.push(`control q${op.control} modifies target q${op.target}`);
  }

  lines.push(formatAngles(op.rotationAngle, op.phaseShift));
  lines.push(formatErrorRate(op.errorRate));

  if (Number(op.errorRate) > 0.01) {
    lines.push(`warning: high noise on qubit q${op.target}`);
  }

  return lines;
}

function validateOperation(op, index) {
  if (!op || typeof op.type !== 'string' || op.type.trim() === '') {
    throw new Error(`operation ${index} is missing an operation type`);
  }
  if (!Number.isInteger(op.target) || op.target < 0) {
    throw new Error(`operation ${index} has an invalid target qubit: ${op.target}`);
  }
  if (op.control === op.target) {
    throw new Error(`operation ${index} cannot use q${op.target} as its own control`);
  }
}

function build(operations) {
  const ops = Array.isArray(operations) ? operations : [];
  const total = ops.length;
  const lines = ['QASM version 2'];
  lines.push(`sequence contains ${total} operations`);

  ops.forEach((op, i) => {
    validateOperation(op, i);
    describeOperation(op, i).forEach((line) => lines.push(line));
  });

  lines.push('end of circuit execution');
  lines.push(`read out the quantum states for all ${total} operations`);
  return lines.join('\n');
}

const circuit = build([
  { type: 'hadamard', target: 0, control: null, rotationAngle: 0, phaseShift: 0, errorRate: 0.005 },
  { type: 'cnot', target: 1, control: 0, rotationAngle: 0, phaseShift: 0, errorRate: 0.02 },
  { type: 'rz', target: 1, control: null, rotationAngle: Math.PI / 2, phaseShift: 0.25, errorRate: 0.001 },
]);

console.log(circuit);

module.exports = { build, describeOperation, formatAngles, formatErrorRate };

