const HIGH_COMPLEXITY = new Set(['high', 'very high', 'expert']);

function isHighComplexity(rating) {
  return HIGH_COMPLEXITY.has(String(rating).trim().toLowerCase());
}

function describeAction(step) {
  return `Step ${step.stepNumber}: perform a ${step.foldAction}.`;
}

function describeLandmark(step) {
  return `  Align the paper with the ${step.paperLandmark}.`;
}

function describeDirection(step) {
  return `  Turn the paper ${step.foldingDirection}.`;
}

function describeCrease(step) {
  return `  Press firmly to create a ${step.creaseType} crease.`;
}

function describeWarning(step) {
  return `  ! Take extra care on step ${step.stepNumber} — this fold is rated ${step.complexityRating}.`;
}

function renderStep(step) {
  const lines = [
    describeAction(step),
    describeLandmark(step),
    describeDirection(step),
    describeCrease(step),
  ];
  if (isHighComplexity(step.complexityRating)) {
    lines.push(describeWarning(step));
  }
  return lines;
}

function document(steps) {
  if (!Array.isArray(steps)) {
    throw new TypeError(`document() expects an array of steps, received ${typeof steps}.`);
  }
  const total = steps.length;
  const lines = ['Origami Model Instructions'];
  lines.push(`This model requires ${total} step${total === 1 ? '' : 's'} in total.`);

  steps.forEach((step, index) => {
    if (step === null || typeof step !== 'object') {
      throw new TypeError(`Step at position ${index} is not a valid step object.`);
    }
    lines.push(...renderStep(step));
  });

  lines.push(`Your model is complete after all ${total} steps.`);
  lines.push('Display your creation with pride — you have earned it!');
  return lines.join('\n');
}

const sampleSteps = [
  {
    stepNumber: 1,
    foldAction: 'valley fold',
    paperLandmark: 'center line',
    foldingDirection: 'inward',
    creaseType: 'sharp',
    complexityRating: 'low',
  },
  {
    stepNumber: 2,
    foldAction: 'reverse fold',
    paperLandmark: 'top right corner',
    foldingDirection: 'outward',
    creaseType: 'soft',
    complexityRating: 'high',
  },
];

console.log(document(sampleSteps));

module.exports = { document, renderStep, isHighComplexity };

