const HEADER = 'CITY TRAFFIC CONTROL SYSTEM — SIGNAL TIMING REPORT';

function cycleLength(intersection) {
  const { northSouthDuration, eastWestDuration, pedestrianCrossingTime } = intersection;
  return northSouthDuration + eastWestDuration + pedestrianCrossingTime;
}

function normalize(intersection, index) {
  const name = String(intersection.intersectionName ?? 'Unnamed intersection #' + (index + 1)).trim();
  const toSeconds = (value, label) => {
    const seconds = Number(value);
    if (!Number.isFinite(seconds) || seconds < 0) {
      throw new RangeError('Invalid ' + label + ' for ' + name + ': ' + value);
    }
    return Math.round(seconds);
  };
  return {
    intersectionName: name,
    northSouthDuration: toSeconds(intersection.northSouthDuration, 'north/south duration'),
    eastWestDuration: toSeconds(intersection.eastWestDuration, 'east/west duration'),
    pedestrianCrossingTime: toSeconds(intersection.pedestrianCrossingTime, 'pedestrian crossing time'),
    peakHourModifier: Number(intersection.peakHourModifier) || 0,
    cameraActive: Boolean(intersection.cameraActive),
  };
}

function describeIntersection(intersection) {
  const lines = ['Intersection: ' + intersection.intersectionName];
  lines.push('  North/South: ' + intersection.northSouthDuration + 's | East/West: ' + intersection.eastWestDuration + 's');
  lines.push('  Pedestrian crossing: ' + intersection.pedestrianCrossingTime + 's');
  lines.push('  Peak hour modifier: ' + intersection.peakHourModifier + '%');
  lines.push('  Full cycle length: ' + cycleLength(intersection) + 's');
  if (intersection.cameraActive) {
    lines.push('  Traffic enforcement cameras are recording at ' + intersection.intersectionName + '.');
  }
  return lines;
}

function format(intersections) {
  const list = (Array.isArray(intersections) ? intersections : []).map(normalize);
  const report = [HEADER, 'Monitored intersections: ' + list.length, ''];

  for (const intersection of list) {
    report.push(...describeIntersection(intersection));
    report.push('');
  }

  const totalPedestrianTime = list.reduce((sum, item) => sum + item.pedestrianCrossingTime, 0);
  report.push('Total pedestrian crossing time: ' + totalPedestrianTime + 's');
  report.push('All ' + list.length + ' intersections are synchronized.');

  return report.join('\n');
}

function main() {
  const intersections = [
    {
      intersectionName: 'Main Street',
      northSouthDuration: 40,
      eastWestDuration: 30,
      pedestrianCrossingTime: 15,
      peakHourModifier: 10,
      cameraActive: true,
    },
    {
      intersectionName: 'Elm Avenue',
      northSouthDuration: 35,
      eastWestDuration: 25,
      pedestrianCrossingTime: 12,
      peakHourModifier: -5,
      cameraActive: false,
    },
  ];

  try {
    console.log(format(intersections));
  } catch (error) {
    console.error('Report generation failed: ' + error.message);
  }
}

main();

module.exports = { format, describeIntersection, cycleLength };

