const SHELTER_ADDRESS = '412 Maple Street, Riverton';

function formatAgeInMonths(ageInMonths) {
  const unit = ageInMonths === 1 ? 'month' : 'months';
  return `${ageInMonths} ${unit} old`;
}

function formatWeight(weightInPounds) {
  const rounded = Math.round(weightInPounds * 10) / 10;
  return `${rounded} lbs`;
}

function normalizeAnimal(animal, index) {
  const name = String(animal.name || '').trim();
  if (!name) {
    throw new Error(`Animal at position ${index + 1} is missing a name.`);
  }
  const age = Number(animal.ageInMonths);
  if (!Number.isFinite(age) || age < 0) {
    throw new Error(`${name} has an invalid age in months.`);
  }
  const weight = Number(animal.weightInPounds);
  if (!Number.isFinite(weight) || weight <= 0) {
    throw new Error(`${name} has an invalid weight in pounds.`);
  }
  return {
    name: name.charAt(0).toUpperCase() + name.slice(1),
    species: String(animal.species || 'animal').trim(),
    breed: String(animal.breed || 'mixed breed').trim(),
    ageInMonths: age,
    weightInPounds: weight,
    temperament: String(animal.temperament || 'friendly').trim()
  };
}

function profileLines(animal) {
  const lines = [];
  lines.push(`Meet ${animal.name}, a ${animal.species} of the ${animal.breed} breed.`);
  lines.push(`${animal.name} is ${formatAgeInMonths(animal.ageInMonths)} and weighs ${formatWeight(animal.weightInPounds)}.`);
  lines.push(`Personality: ${animal.temperament}.`);
  lines.push(`Come meet ${animal.name} in person!`);
  if (animal.ageInMonths < 6) {
    lines.push(`Note: ${animal.name} is a young baby and requires extra training.`);
  }
  return lines;
}

function profile(animals) {
  if (!Array.isArray(animals)) {
    throw new TypeError('profile() expects a list of animals.');
  }
  const roster = animals.map(normalizeAnimal);
  const count = roster.length;
  const noun = count === 1 ? 'animal' : 'animals';
  const lines = ['Welcome to the Weekly Pet Adoption Drive!'];
  lines.push(`We have ${count} ${noun} looking for homes today.`);
  roster.forEach((animal) => {
    lines.push('');
    profileLines(animal).forEach((line) => lines.push(line));
  });
  lines.push('');
  lines.push(`Visit us at ${SHELTER_ADDRESS}.`);
  lines.push(`Adopting any of these ${count} ${noun} saves lives.`);
  return lines.join('\n');
}

module.exports = { profile, formatAgeInMonths, formatWeight };

