const HEADER_RULE = '='.repeat(58);
const LOW_FUEL_THRESHOLD = 20;

function formatHeader() {
  const lines = [HEADER_RULE];
  lines.push(`${'MISSION CONTROL'.padStart(36)} — FLIGHT DYNAMICS`);
  lines.push(`  PHASE: ORBITAL ADJUSTMENT`);
  lines.push(HEADER_RULE);
  return lines;
}

function formatBurnCount(total) {
  const plural = total === 1 ? 'burn' : 'burns';
  return `Total planned ${plural}: ${total}`;
}

function formatManeuver(maneuver, index) {
  const {
    maneuverName,
    engineUsed,
    burnDuration,
    velocityChange,
    newAltitude,
    fuelRemainingPercentage,
  } = maneuver;
  const lines = [];
  lines.push('');
  lines.push(`[${index + 1}] ${maneuverName} — engine: ${engineUsed}`);
  lines.push(`    Burn duration: ${burnDuration.toFixed(1)} seconds`);
  lines.push(`    Velocity change: ${velocityChange.toFixed(2)} m/s`);
  lines.push(`    Predicted new altitude confirmed at ${newAltitude.toFixed(1)} km`);
  lines.push(`    Fuel remaining after burn: ${fuelRemainingPercentage.toFixed(1)}%`);
  if (fuelRemainingPercentage < LOW_FUEL_THRESHOLD) {
    lines.push(`    WARNING: low propellant reserves following ${maneuverName}`);
  }
  return lines;
}

function validateManeuver(maneuver, index) {
  const required = [
    'maneuverName',
    'engineUsed',
    'burnDuration',
    'velocityChange',
    'newAltitude',
    'fuelRemainingPercentage',
  ];
  for (const field of required) {
    if (maneuver[field] === undefined || maneuver[field] === null) {
      throw new Error(`Maneuver at index ${index} is missing field "${field}"`);
    }
  }
}

function log(maneuvers) {
  if (!Array.isArray(maneuvers)) {
    throw new TypeError(`Expected a list of maneuvers, received ${typeof maneuvers}`);
  }
  const report = formatHeader();
  report.push(formatBurnCount(maneuvers.length));
  maneuvers.forEach((maneuver, index) => {
    validateManeuver(maneuver, index);
    report.push(...formatManeuver(maneuver, index));
  });
  report.push('');
  report.push(`Spacecraft is in a stable orbit after ${maneuvers.length} total burns.`);
  report.push('END OF TRANSMISSION');
  return report.join('\n');
}

const plan = [
  {
    maneuverName: 'orbit raise',
    engineUsed: 'main thruster',
    burnDuration: 60,
    velocityChange: 50,
    newAltitude: 400,
    fuelRemainingPercentage: 80,
  },
];

console.log(log(plan));

module.exports = { log, formatManeuver, formatBurnCount };

