function formatClueHeader(clue) {
  const room = `Room: ${clue.roomLocation}`;
  return `Clue #${clue.clueNumber} — ` + room;
}

function formatPuzzle(clue) {
  return `  Puzzle type: present a ${clue.puzzleType} to the players.`;
}

function formatCombination(clue) {
  const combo = `Lock combination ${clue.lockCombination}`;
  const target = `the ${clue.hiddenObject}`;
  return '  ' + combo + ' opens ' + target + '.';
}

function formatPenalty(clue) {
  return `  Time penalty for this hint: ${clue.timePenalty} minute(s).`;
}

function formatWarning(clue) {
  return `  WARNING: clue #${clue.clueNumber} is a costly hint!`;
}

function totalPenalty(clues) {
  return clues.reduce((sum, clue) => sum + clue.timePenalty, 0);
}

function sequence(clues) {
  if (!Array.isArray(clues)) {
    throw new TypeError(`sequence expects a list of clues, received ${typeof clues}`);
  }

  const lines = ['=== ESCAPE ROOM GAME MASTER GUIDE ==='];
  lines.push(`Total clues available: ${clues.length}`);

  for (const clue of clues) {
    lines.push(formatClueHeader(clue));
    lines.push(formatPuzzle(clue));
    lines.push(formatCombination(clue));
    lines.push(formatPenalty(clue));
    if (clue.timePenalty > 5) {
      lines.push(formatWarning(clue));
    }
  }

  const total = totalPenalty(clues);
  lines.push(`Total time penalty of all clues: ${total} minute(s).`);
  lines.push(`Game over once the ${total} minute penalty sum is reached.`);

  return lines.join('\n');
}

function main() {
  const clues = [
    {
      clueNumber: 1,
      roomLocation: 'library',
      puzzleType: 'riddle',
      lockCombination: '1234',
      hiddenObject: 'safe',
      timePenalty: 2,
    },
    {
      clueNumber: 2,
      roomLocation: 'cellar',
      puzzleType: 'jigsaw',
      lockCombination: '8891',
      hiddenObject: 'wine rack',
      timePenalty: 7,
    },
  ];

  console.log(sequence(clues));
}

main();

module.exports = { sequence, totalPenalty };

