const currency = (amount) =>
  '$' + amount.toLocaleString('en-US', { maximumFractionDigits: 2 });

const PREMIUM_THRESHOLD = 1000;

const REQUIRED_FIELDS = ['lotNumber', 'title', 'donor', 'startingBid', 'minIncrement', 'category'];

function pluralize(count, noun) {
  const label = count === 1 ? noun : noun + 's';
  return count + ' ' + label;
}

function validateItem(item, index) {
  const position = 'item at position ' + (index + 1);
  if (item === null || typeof item !== 'object') {
    throw new TypeError('Invalid ' + position + ': expected an object.');
  }
  const missing = REQUIRED_FIELDS.filter((field) => item[field] === undefined || item[field] === null || item[field] === '');
  if (missing.length > 0) {
    throw new TypeError(position + ' is missing: ' + missing.join(', ') + '.');
  }
  const bid = Number(item.startingBid);
  const increment = Number(item.minIncrement);
  if (!Number.isFinite(bid) || bid <= 0) {
    throw new RangeError('Starting bid for lot ' + item.lotNumber + ' must be a positive number.');
  }
  if (!Number.isFinite(increment) || increment <= 0) {
    throw new RangeError('Minimum increment for lot ' + item.lotNumber + ' must be a positive number.');
  }
  return { ...item, startingBid: bid, minIncrement: increment };
