const CABLE_RATINGS = ['good', 'fair', 'poor'];

function normalizeRating(rating) {
  const cleaned = String(rating).trim().toLowerCase();
  if (!CABLE_RATINGS.includes(cleaned)) {
    throw new Error(`Unknown cable condition rating: ${rating}`);
  }
  return cleaned;
}

function formatDate(date) {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
}

function nextMaintenanceDate(from) {
  const next = new Date(from.getTime());
  next.setMonth(next.getMonth() + 1);
  return formatDate(next);
}

function unitReport(unit, index) {
  const rating = normalizeRating(unit.cableCondition);
  const lines = [];
  lines.push(`Unit ${index + 1}: elevator ${unit.id}`);
  lines.push(`  Serves ${unit.floorsServed} floors.`);
  lines.push(`  Cable condition rated: ${rating}.`);
  lines.push(`  Door operation is ${unit.doorStatus}.`);
  const service = `${unit.lastService} by technician ${unit.technician}`;
  lines.push(`  Last serviced ${service}.`);
  if (rating === 'poor') {
    lines.push(`  ACTION REQUIRED: lock down elevator ${unit.id} out of service immediately.`);
  }
  return lines;
}

function document(elevators) {
  const units = Array.isArray(elevators) ? elevators : [];
  const total = units.length;
  const today = new Date();
  const lines = [];
  lines.push('MONTHLY ELEVATOR SAFETY INSPECTION');
  lines.push('==================================');
  lines.push(`Total units inspected: ${total}`);
  lines.push('');
  units.forEach((unit, index) => {
    unitReport(unit, index).forEach((line) => lines.push(line));
    lines.push('');
  });
  lines.push(`Inspection signed off for ${total} unit(s) on ${formatDate(today)}.`);
  lines.push(`Next scheduled maintenance: ${nextMaintenanceDate(today)}.`);
  return lines.join('\n');
}

