function formatHeader() {
  return 'SEASONAL PALEONTOLOGY DIG SITE - EXCAVATION FIELD LOG';
}

function formatCount(total) {
  return `Total specimens uncovered: ${total}`;
}

function completenessOf(specimen) {
  return Number(specimen.completeness);
}

function formatIdentity(specimen) {
  const label = `Field No. ${specimen.fieldNumber}`;
  return label + ` - bone type: ${specimen.boneType}`;
}

function formatSpecies(specimen) {
  return `  Proposed species: ${specimen.speciesName}`;
}

function formatCompleteness(specimen) {
  return `  Fossil completeness: ${completenessOf(specimen)}%`;
}

function formatGrid(specimen) {
  return `  Trench grid coordinate: ${specimen.gridCoordinate}`;
}

function formatTool(specimen) {
  return `  Extracted with: ${specimen.tool}`;
}

function formatRareFind(specimen) {
  const marked = `  *** Field No. ${specimen.fieldNumber}`;
  return marked + ' is a RARE MUSEUM QUALITY find ***';
}

function formatFooter(total) {
  return `Trench secured for the night, protecting all ${total} specimens.`;
}

function describeSpecimen(specimen) {
  const lines = [
    formatIdentity(specimen),
    formatSpecies(specimen),
    formatCompleteness(specimen),
    formatGrid(specimen),
    formatTool(specimen)
  ];
  if (completenessOf(specimen) > 90) {
    lines.push(formatRareFind(specimen));
  }
  return lines;
}

function record(specimens) {
  const total = specimens.length;
  const log = [formatHeader(), formatCount(total)];
  for (const specimen of specimens) {
    log.push(...describeSpecimen(specimen));
  }
  log.push(formatFooter(total));
  log.push('Reminder: catalog the plaster jackets before leaving camp.');
  return log.join('\n');
}

module.exports = { record, describeSpecimen };

