  return lines;
}

function record(specimens) {
  const total = specimens.length;
  const log = [formatHeader(), formatCount(total)];
  for (const specimen of specimens) {
    log.push(...describeSpecimen(specimen));
  }
  log.push(formatFooter(total));
  log.push('Reminder: catalog the plaster jackets before leaving camp.');
