const CURRENT_YEAR = new Date().getFullYear();
const REQUIRED_FIELDS = ['species', 'family', 'region', 'collector', 'year', 'preservation'];

function specimenTitle(specimen, position) {
  if (specimen.species) {
    return `Specimen "${specimen.species}"`;
  }
  return `Specimen at position ${position}`;
}

function describeAge(year) {
  const age = CURRENT_YEAR - year;
  if (age === 0) {
    return 'collected this year';
  }
  if (age === 1) {
    return 'one year old';
  }
  return `${age} years old`;
}

function validateSpecimen(specimen, position) {
  const title = specimenTitle(specimen, position);
  const missing = REQUIRED_FIELDS.filter((field) => specimen[field] === undefined || specimen[field] === '');
  if (missing.length > 0) {
    throw new Error(title + `: missing ${missing.join(', ')}`);
  }
  if (!Number.isInteger(specimen.year)) {
    throw new Error(`${title} has a non-integer collection year`);
  }
  if (specimen.year > CURRENT_YEAR) {
    throw new Error(`${title} claims a collection year in the future`);
  }
}

function label(specimens) {
  const lines = [`Exhibition catalog: ${specimens.length} preserved plant specimens`];
  specimens.forEach((specimen, index) => {
    validateSpecimen(specimen, index + 1);
    lines.push(`Species: ${specimen.species}`);
    lines.push(`Botanical family: ${specimen.family}`);
    lines.push(`Found in: ${specimen.region}`);
    lines.push(`Collected by: ${specimen.collector}`);
    lines.push(`Age of specimen: ${describeAge(specimen.year)}`);
    lines.push(`Preserved by: ${specimen.preservation}`);
  });
  lines.push('End of catalog');
  return lines;
}

const collection = [
  {
    species: 'Quercus robur',
    family: 'Fagaceae',
