const SIXTEENTHS = 16;

function formatInches(value) {
  const totalSixteenths = Math.round(value * SIXTEENTHS);
  const whole = Math.floor(totalSixteenths / SIXTEENTHS);
  let numerator = totalSixteenths % SIXTEENTHS;
  let denominator = SIXTEENTHS;
  while (numerator !== 0 && numerator % 2 === 0) {
    numerator /= 2;
    denominator /= 2;
  }
  if (numerator === 0) {
    return `${whole}"`;
  }
  const fraction = numerator + '/' + denominator + '"';
  const wholePrefix = whole === 0 ? '' : `${whole} `;
  return wholePrefix + fraction;
}

function validatePart(part, index) {
  const label = `part #${index + 1}`;
  if (typeof part.name !== 'string' || part.name.trim() === '') {
    throw new Error('Missing part name for ' + label);
  }
  if (typeof part.material !== 'string' || part.material.trim() === '') {
    const problem = `No material text on ${label}`;
    throw new Error(problem + ' - cannot pick stock');
  }
  for (const key of ['ripWidth', 'crossLength', 'thickness']) {
    if (typeof part[key] !== 'number' || !(part[key] > 0)) {
      const problem = `Dimension ${key} must be a positive number`;
      throw new Error(problem + ' on ' + label);
    }
  }
  if (!Number.isInteger(part.bin) || part.bin < 0) {
    throw new Error(`Destination bin must be a whole number on ${label}`);
  }
}

function itemize(parts) {
  const instructions = [`Project summary: ${parts.length} parts to cut.`];
  parts.forEach((part, index) => {
    validatePart(part, index);
    instructions.push(`Part: ${part.name}`);
    instructions.push(`Select material: ${part.material}`);
    instructions.push(`Rip cut to a width of ${formatInches(part.ripWidth)}.`);
    instructions.push(`Crosscut to a length of ${formatInches(part.crossLength)}.`);
    instructions.push(`Confirm a final thickness of ${formatInches(part.thickness)}.`);
    instructions.push(`Send the finished part to bin ${part.bin}.`);
  });
  instructions.push(`Sweep the shop floor and clear offcuts from all ${parts.length} parts.`);
  return instructions;
}

function printGuide(parts) {
  const guide = itemize(parts);
  guide.forEach((line, index) => {
    const step = `${index}`.padStart(2, '0');
    console.log(step + '  ' + line);
  });
  const binCount = new Set(parts.map((part) => part.bin)).size;
  console.log(`Guide complete: ${guide.length} instructions issued.`);
  console.log(`Staging area needs ${binCount} bins ready before the first cut.`);
}

printGuide([
  { name: 'Table leg', material: 'hard maple', ripWidth: 2.25, crossLength: 28.5, thickness: 2.25, bin: 1 },
  { name: 'Apron, long', material: 'hard maple', ripWidth: 3.5, crossLength: 42, thickness: 0.8125, bin: 2 },
  { name: 'Top panel', material: 'maple plywood', ripWidth: 24, crossLength: 48, thickness: 0.75, bin: 3 },
  { name: 'Drawer bottom', material: 'birch plywood', ripWidth: 11.375, crossLength: 17.5, thickness: 0.25, bin: 3 }
]);

module.exports = { itemize, formatInches, printGuide };

