function formatWeight(kilograms) {
  const rounded = Math.round(kilograms * 10) / 10;
  return `${rounded.toFixed(1)} kg`;
}

function mitePressure(mites) {
  if (mites >= 50) {
    return `${mites} mites per 100 bees — above the treatment threshold`;
  }
  if (mites >= 20) {
    return `${mites} mites per 100 bees — approaching the threshold`;
  }
  return `${mites} mites per 100 bees — within safe limits`;
}

function validateHive(hive, index) {
  const position = index + 1;
  if (typeof hive !== 'object' || hive === null) {
    throw new TypeError(`Hive record at position ${position} is not a record`);
  }
  for (const field of ['number', 'queen', 'brood', 'honey', 'mites', 'treatment']) {
    if (!(field in hive)) {
      throw new TypeError(`Hive record at position ${position} is missing "${field}"`);
    }
  }
  return hive;
}

function inspect(hives) {
  if (!Array.isArray(hives)) {
    throw new TypeError('inspect expects a list of hive records');
  }
  const report = [`Total hives inspected: ${hives.length}`];
  hives.forEach((record, index) => {
    const hive = validateHive(record, index);
    report.push(`Hive ${hive.number}`);
    report.push(`Queen status: ${hive.queen}`);
    report.push(`Brood frames: ${hive.brood}`);
    report.push(`Estimated honey: ${formatWeight(hive.honey)}`);
    report.push(`Mite count: ${mitePressure(hive.mites)}`);
    report.push(`Required treatment: ${hive.treatment}`);
  });
  report.push('Apiary secured.');
  return report;
}

const checks = [
  { number: 1, queen: 'laying well, marked blue', brood: 7, honey: 18.42, mites: 12, treatment: 'none, recheck in two weeks' },
  { number: 2, queen: 'not seen, eggs present', brood: 5, honey: 11.8, mites: 27, treatment: 'formic acid strip, single dose' },
  { number: 3, queen: 'drone layer, needs replacing', brood: 2, honey: 6.05, mites: 63, treatment: 'oxalic acid dribble plus requeen' }
];

const observations = inspect(checks);
for (const line of observations) {
