function validateTrain(train, index) {
  const position = index + 1;
  if (!Number.isInteger(train.number)) {
    throw new TypeError(`Train at position ${position} needs an integer train number`);
  }
  if (!train.locoClass) {
    throw new TypeError(`Train ${train.number} is missing a locomotive class`);
  }
  if (!train.from || !train.to) {
    throw new TypeError(`Train ${train.number} needs both a departure and an arrival station`);
  }
  if (!Number.isInteger(train.cars) || train.cars < 0) {
    throw new RangeError(`Train ${train.number} has an invalid car count: ${train.cars}`);
  }
  if (!(train.speedLimit > 0)) {
    throw new RangeError(`Train ${train.number} has an invalid speed limit: ${train.speedLimit}`);
  }
  return train;
}

function trainOrders(train) {
  const consist = train.cars === 1 ? '1 car' : `${train.cars} cars`;
  return [
    `Train ${train.number}, this is the dispatcher, acknowledge.`,
    `Your power is a class ${train.locoClass} locomotive.`,
    `You are authorized to depart ${train.from}.`,
    `Route is cleared through to ${train.to}.`,
    `Your consist is ${consist}.`,
    `Do not exceed ${train.speedLimit} km/h at any point.`,
  ];
}

function trackBulletin(count) {
  const noun = count === 1 ? 'movement' : 'movements';
  return `Track bulletin: clearance granted for ${count} ${noun} on the main line.`;
}

function dispatch(trains) {
  if (!Array.isArray(trains)) {
    throw new TypeError(`dispatch expects an array of train records, got ${typeof trains}`);
  }
  const instructions = [trackBulletin(trains.length)];
  trains.forEach((train, index) => {
    validateTrain(train, index);
    instructions.push(...trainOrders(train));
  });
  instructions.push('Dispatcher desk out, all sheets signed.');
  return instructions;
}

function printSheet(trains) {
  const lines = dispatch(trains);
  lines.forEach((line, index) => {
    const label = String(index + 1).padStart(2, '0');
    console.log(`${label}  ${line}`);
  });
  console.log(`--- ${lines.length} lines issued at ${new Date().toISOString().slice(11, 16)} ---`);
}

const schedule = [
  { number: 412, locoClass: 'BR 218', from: 'Ostbahnhof', to: 'Seeheim', cars: 7, speedLimit: 100 },
  { number: 9, locoClass: 'V 60', from: 'Seeheim', to: 'Kiesgrube', cars: 1, speedLimit: 40 },
  { number: 1533, locoClass: 'BR 103', from: 'Kiesgrube', to: 'Ostbahnhof', cars: 12, speedLimit: 160 },
];

printSheet(schedule);

module.exports = { dispatch, trainOrders, trackBulletin, printSheet };

