function formatAmplitude(amplitude) {
  if (amplitude >= 270) {
    return `Amplitude measured at ${amplitude} degrees, within healthy range.`;
  }
  if (amplitude >= 220) {
    return `Amplitude measured at ${amplitude} degrees, acceptable after service.`;
  }
  return `Amplitude measured at ${amplitude} degrees, below specification.`;
}

function formatBeatError(beatError) {
  const reading = beatError.toFixed(1);
  if (beatError <= 0.5) {
    return `Beat error reading of ${reading} ms, movement is in beat.`;
  }
  return `Beat error reading of ${reading} ms, hairspring stud adjusted.`;
}

function service(watches) {
  const notes = [`Total watches serviced: ${watches.length}.`];
  watches.forEach((watch) => {
    notes.push(`Customer: ${watch.customer}.`);
    notes.push(`Movement caliber number ${watch.caliber} inspected on the bench.`);
    notes.push(formatAmplitude(watch.amplitude));
    notes.push(formatBeatError(watch.beatError));
    notes.push(`Replaced part: ${watch.replacedPart}, sourced from factory stock.`);
    notes.push(`Work guaranteed for ${watch.warranty} from the date of collection.`);
  });
  notes.push('All movements have passed timing tests.');
  return notes;
}

function report(watches) {
  return service(watches)
    .map((note, index) => `${String(index + 1).padStart(3, ' ')}. ${note}`)
    .join('\n');
}

