function describeBoard(board, index) {
  const label = `Board ${index + 1}`;
  return [
    `${label}: prepare the ${board.caseMaterial} case and check for burrs.`,
    `${label}: confirm the ${board.layout} layout on the PCB.`,
    `${label}: lubricate the ${board.switchName} switches with a thin coat.`,
    `${label}: swap the springs to ${board.springWeight}g.`,
    `${label}: mount the ${board.keycapProfile} keycaps row by row.`,
    `${label}: plug in the ${board.cableType} cable and verify power.`,
  ];
}

function validateBoard(board, index) {
  const required = [
    'caseMaterial',
    'layout',
    'switchName',
    'springWeight',
    'keycapProfile',
    'cableType',
  ];
  for (const field of required) {
    if (board[field] === undefined || board[field] === null || board[field] === '') {
      throw new Error(`Board ${index + 1} is missing its ${field}.`);
    }
  }
  if (typeof board.springWeight !== 'number' || Number.isNaN(board.springWeight)) {
    throw new Error(`Board ${index + 1} has a non-numeric spring weight: ${board.springWeight}`);
  }
}

function build(boards) {
  const steps = [`Assembling ${boards.length} custom mechanical keyboards.`];
  boards.forEach((board, index) => {
    validateBoard(board, index);
    steps.push(...describeBoard(board, index));
  });
  steps.push('All typing tests passed.');
  return steps;
}

function formatWorkOrder(boards) {
  const lines = build(boards).map((step, i) => `${String(i).padStart(3, ' ')}  ${step}`);
  return lines.join('\n');
}

