    noteRange: 'G5 through C6',
    mallet: 'brass-headed',
    piece: 'Carillon Nocturne',
    pageTurn: 'no turns; the part fits on one spread',
  },
];

printGuide(tonightsRingers);

module.exports = { assign, tablePlan, printGuide };

