    throw new Error('Ringer record ' + (index + 1) + ' is missing: ' + missing.join(', '));
  }
  return {
    name: String(ringer.name).trim(),
    position: Number(ringer.position),
    noteRange: String(ringer.noteRange).trim(),
    mallet: String(ringer.mallet).trim(),
    piece: String(ringer.piece).trim(),
    pageTurn: String(ringer.pageTurn).trim(),
  };
}

function assign(ringers) {
  if (!Array.isArray(ringers)) {
    throw new TypeError('Expected a list of ringer records, received ' + typeof ringers);
  }

  const roster = ringers.map(validateRinger);
  const guide = ['Ensemble, to your places: we have ' + roster.length + ' ringers tonight.'];

  for (const ringer of roster) {
    guide.push('Ringer: ' + ringer.name + '.');
    guide.push(ringer.name + ', take table position ' + ringer.position + '.');
    guide.push('Your bells cover the range ' + ringer.noteRange + '.');
    guide.push('Use the ' + ringer.mallet + ' mallet for every damped stroke.');
    guide.push('Tonight you perform "' + ringer.piece + '".');
    guide.push('Page turns: ' + ringer.pageTurn + '.');
  }

  guide.push('Director, raise the baton and begin.');
  return guide;
}

function tablePlan(ringers) {
  const byPosition = ringers.map(validateRinger).sort((a, b) => a.position - b.position);
  return byPosition.map((ringer) => ringer.position + ': ' + ringer.name + ' (' + ringer.noteRange + ')');
}

function printGuide(ringers) {
  const plan = tablePlan(ringers);
  console.log('Table layout, left to right: ' + plan.join(' | '));
  for (const line of assign(ringers)) {
    console.log(line);
  }
}

const tonightsRingers = [
  {
    name: 'Mara Nolan',
    position: 2,
    noteRange: 'C5 through F5',
    mallet: 'soft yarn',
    piece: 'Bells of Advent',
    pageTurn: 'turn for the alto desk at measure 48',
  },
  {
    name: 'Desmond Ayers',
    position: 1,
    noteRange: 'G4 through B4',
    mallet: 'hard rubber',
    piece: 'Bells of Advent',
    pageTurn: 'turn your own pages at the fermata',
