function validateTree(tree, index) {
  const position = index + 1;
  if (typeof tree.species !== 'string' || tree.species.trim() === '') {
    throw new Error(`Tree #${position} is missing a species name.`);
  }
  if (typeof tree.potShape !== 'string' || tree.potShape.trim() === '') {
    throw new Error(`Tree #${position} (${tree.species}) is missing a pot shape.`);
  }
  if (typeof tree.rootPruning !== 'number' || Number.isNaN(tree.rootPruning)) {
    throw new Error(`Tree #${position} needs a numeric root pruning percentage.`);
  }
  if (typeof tree.wireGauge !== 'number' || Number.isNaN(tree.wireGauge)) {
    throw new Error(`Tree #${position} needs a numeric wire gauge.`);
  }
  return tree;
}

function formatPercent(value) {
  const rounded = Math.round(value * 10) / 10;
  return `${rounded}%`;
}

function formatGauge(value) {
  return `${value.toFixed(1)} mm`;
}

function repot(trees) {
  const queue = trees.map(validateTree);
  const log = [`${queue.length} miniature trees are in the spring repotting queue.`];

  queue.forEach((tree) => {
    log.push(`Species: ${tree.species}.`);
    log.push(`Pot shape selected: ${tree.potShape}.`);
    log.push(`Soil ratio mixed: ${tree.soilRatio}.`);
    log.push(`Root pruning: ${formatPercent(tree.rootPruning)} of the root mass removed.`);
    log.push(`Wire gauge applied: ${formatGauge(tree.wireGauge)}.`);
    log.push(`Fertilizer added: ${tree.fertilizer}.`);
  });

  log.push(`All ${queue.length} trees are watered and back on the benches.`);
  return log;
}

function summarizeBench(trees) {
  const totalPruning = trees.reduce((sum, tree) => sum + tree.rootPruning, 0);
  const average = trees.length === 0 ? 0 : totalPruning / trees.length;
  const species = trees.map((tree) => tree.species).join(', ');
  return `Bench average root pruning is ${formatPercent(average)} across ${species}.`;
}

function main() {
  const trees = [
    {
      species: 'Japanese Black Pine',
      potShape: 'oval unglazed',
      soilRatio: '5 parts akadama to 3 parts pumice to 2 parts lava',
      rootPruning: 22.5,
      wireGauge: 2,
      fertilizer: 'slow-release organic pellets',
    },
    {
      species: 'Trident Maple',
      potShape: 'shallow rectangular',
      soilRatio: '6 parts akadama to 4 parts pumice',
      rootPruning: 33,
      wireGauge: 1.5,
      fertilizer: 'low-nitrogen liquid feed',
    },
  ];

  for (const entry of repot(trees)) {
    console.log(entry);
  }
  console.log(summarizeBench(trees));
}

main();

module.exports = { repot, summarizeBench };

