function formatThickness(inches) {
  const safety = inches >= 4 ? "safe" : "thin ice";
  return `${inches} inches (${safety})`;
}

function formatFuel(fuel) {
  const level = fuel.trim().length === 0 ? "unrecorded" : fuel.trim();
  return `heater fuel: ${level}`;
}

function normalizeShack(record, index) {
  const owner = String(record.owner || "").trim();
  if (owner.length === 0) {
    throw new Error(`Shack #${index + 1} is missing an owner name`);
  }
  const coordinate = String(record.coordinate || "").trim();
  if (coordinate.length === 0) {
    throw new Error(`Shack of ${owner} is missing a gps coordinate`);
  }
  const thickness = Number(record.thickness);
  if (!Number.isFinite(thickness)) {
    throw new Error(`Ice thickness for ${owner} is not a number`);
  }
  const fish = Number(record.fish);
  if (!Number.isFinite(fish)) {
    throw new Error(`Fish count for ${owner} is not a number`);
  }
  return {
    owner,
    coordinate,
    thickness,
    fuel: String(record.fuel || ""),
    fish,
    license: String(record.license || "").trim() || "not checked"
  };
}

function describeShack(shack) {
  const catchLine = shack.fish === 1 ? "1 fish caught" : `${shack.fish} fish caught`;
  return [
    `Owner: ${shack.owner}`,
    `GPS coordinate: ${shack.coordinate}`,
    `Ice thickness: ${formatThickness(shack.thickness)}`,
    `Recorded ${formatFuel(shack.fuel)}`,
    `Tally: ${catchLine}`,
    `License check: ${shack.license}`
  ];
}

function locate(shacks) {
  const records = Array.isArray(shacks) ? shacks : [];
  const report = [`Starting lake patrol of ${records.length} shacks`];
  records.forEach((record, index) => {
    const shack = normalizeShack(record, index);
    describeShack(shack).forEach(line => report.push(line));
  });
  report.push("Lake patrol complete");
  return report;
}

function main() {
  const shacks = [
    { owner: "Bjorn Haugen", coordinate: "46.7821 N, 92.1005 W", thickness: 11, fuel: "propane, half tank", fish: 4, license: "valid" },
    { owner: "Marta Kell", coordinate: "46.7903 N, 92.0888 W", thickness: 3.5, fuel: "  ", fish: 1, license: "expired" },
    { owner: "Dell Novak", coordinate: "46.8012 N, 92.1140 W", thickness: 7.25, fuel: "kerosene, full", fish: 0, license: "" }
  ];
  locate(shacks).forEach(line => console.log(line));
  try {
    locate([{ owner: "", coordinate: "46.79 N, 92.10 W", thickness: 6, fish: 2 }]);
  } catch (err) {
    console.log(`Patrol aborted: ${err.message}`);
  }
}

main();

