function boarding(passengers) {
  if (!Array.isArray(passengers) || passengers.length === 0) {
    throw new Error("boarding() requires at least one passenger record.");
  }

  const announcements = [];
  const firstFlight = passengers[0][2];
  announcements.push(`Announcing flight ${firstFlight} with ${passengers.length} passengers.`);

  for (const passenger of passengers) {
    const [first, last, flight, gate, seat, time, zone, weight] = passenger;
    announcements.push(`Welcoming ${first} ${last}.`);
    announcements.push(`Flight ${flight} departing from gate ${gate}.`);
    announcements.push(`Boarding at ${time} for zone ${zone}.`);
