function validateAction(action, index) {
  if (!Array.isArray(action) || action.length !== 5) {
    throw new TypeError(`Action ${index} must be a list of five fields.`);
  }
  const [attacker, defender, weapon, damage, element] = action;
  if (!attacker || !defender || !weapon) {
    throw new TypeError(`Action ${index} is missing a combatant or weapon.`);
  }
  if (typeof damage !== "number" || Number.isNaN(damage)) {
    throw new TypeError(`Action ${index} has a non-numeric damage amount.`);
  }
  if (typeof element !== "string") {
    throw new TypeError(`Action ${index} has an invalid element type.`);
  }
  return { attacker, defender, weapon, damage, element: element.toLowerCase() };
}

function elementalSentence({ defender, weapon, damage, element }) {
  if (element === "fire") {
    return `The ${weapon} burns ${defender}.`;
  }
  if (element === "ice") {
    return `The ${weapon} freezes ${defender}.`;
  }
  if (element === "poison") {
    return `${damage} poison damage sickens ${defender}.`;
  }
  return null;
}

function combat(actions) {
  const total = actions.length;
  const sentences = [`Battle begun with ${total} actions.`];
  actions.forEach((raw, index) => {
    const move = validateAction(raw, index);
    const { attacker, defender, weapon, damage } = move;
    sentences.push(`${attacker} engages ${defender}.`);
    sentences.push(`${attacker} swings the ${weapon}.`);
    sentences.push(`${defender} takes ${damage} damage.`);
    const elemental = elementalSentence(move);
    if (elemental) {
      sentences.push(elemental);
    }
    if (damage > 50) {
      sentences.push(`Critical hit by ${attacker} with ${weapon}!`);
    }
  });
  sentences.push(`Clash recorded ${total} actions.`);
  return sentences;
}

function battleReport(actions) {
  const lines = combat(actions).map(
    (sentence, i) => `${String(i + 1).padStart(2, " ")}. ${sentence}`
  );
  const damageTotal = actions.reduce((sum, action) => sum + action[3], 0);
  lines.push(`Total damage dealt: ${damageTotal}.`);
  return lines.join("\n");
}

