function validateStop(stop, index) {
  if (!Array.isArray(stop) || stop.length !== 5) {
    throw new TypeError(`Stop at index ${index} must be a list of five fields.`);
  }
  const [number, address, size, contact, signature] = stop;
  if (!Number.isInteger(number) || number < 1) {
    throw new RangeError(`Stop number must be a positive integer, got ${number}.`);
  }
  if (typeof address !== 'string' || address.trim() === '') {
    throw new TypeError(`Stop ${number} is missing a street address.`);
  }
  if (!['small', 'medium', 'large'].includes(size)) {
    throw new RangeError(`Unknown package size "${size}" at stop ${number}.`);
  }
  if (typeof contact !== 'string' || contact.trim() === '') {
    throw new TypeError(`Stop ${number} is missing a contact name.`);
  }
  if (typeof signature !== 'boolean') {
    throw new TypeError(`Signature flag at stop ${number} must be a boolean.`);
  }
  return { number, address: address.trim(), size, contact: contact.trim(), signature };
}

function handlingInstruction({ size, address, contact }) {
  if (size === 'small') {
    return `Leave in mailbox for ${contact}.`;
  }
  if (size === 'medium') {
    return `Leave at front door at ${address}.`;
  }
  return `Ring the bell for ${contact}.`;
}

function route(stops) {
  if (!Array.isArray(stops)) {
    throw new TypeError('route expects a list of stop lists.');
  }
  const total = stops.length;
  const sentences = [`Manifest contains ${total} stops.`];
  stops.forEach((raw, index) => {
    const stop = validateStop(raw, index);
    sentences.push(`Proceed to stop ${stop.number} at ${stop.address}.`);
    sentences.push(`Deliver ${stop.size} package to ${stop.contact}.`);
    sentences.push(`Arrived at ${stop.address} stop ${stop.number}.`);
    sentences.push(handlingInstruction(stop));
    if (stop.signature) {
      sentences.push(`Signature required from ${stop.contact}.`);
    }
  });
  sentences.push(`Completed all ${total} stops.`);
  return sentences;
}

function printRoute(stops) {
  const sentences = route(stops);
  sentences.forEach((sentence, line) => {
    console.log(`${String(line + 1).padStart(2, ' ')}. ${sentence}`);
  });
  return sentences.length;
}

const manifest = [
  [1, 'Main St', 'small', 'Bob', true],
  [2, '14 Elm Ave', 'medium', 'Dana', false],
  [3, 'Harbor Rd', 'large', 'Ines', true],
];
const lineCount = printRoute(manifest);
console.log(`Route sheet printed with ${lineCount} lines.`);

