function describeBuoy(id, waterTemp) {
  return `Buoy ${id} reporting ${waterTemp} degrees.`;
}

function describeWind(id, windSpeed) {
  return `Wind ${windSpeed} knots at ${id}.`;
}

function describeWaves(waveHeight, waterTemp) {
  return `Waves ${waveHeight} feet at ${waterTemp} degrees.`;
}

function describeSeaState(id, waveHeight) {
  if (waveHeight < 2) {
    return `Calm seas at ${id}.`;
  }
  if (waveHeight <= 5) {
    return `Moderate chop of ${waveHeight} feet.`;
  }
  return `Rough seas warning: ${waveHeight} feet.`;
}

function validateReading(reading, index) {
  if (!Array.isArray(reading) || reading.length !== 5) {
    throw new TypeError(`Reading ${index} must have 5 fields.`);
  }
  const [id, windSpeed, waveHeight, waterTemp] = reading;
  if (typeof id !== 'string' || id.length === 0) {
    throw new TypeError(`Reading ${index} has an invalid buoy identifier.`);
  }
  for (const [name, value] of [['wind speed', windSpeed], ['wave height', waveHeight], ['water temperature', waterTemp]]) {
    if (typeof value !== 'number' || Number.isNaN(value)) {
      throw new TypeError(`Reading ${index} has a non-numeric ${name}.`);
    }
  }
  return reading;
}

function marine(readings) {
  if (!Array.isArray(readings)) {
    throw new TypeError('readings must be an array of reading lists.');
  }
  const total = readings.length;
  const script = [`Forecast based on ${total} readings.`];
  readings.forEach((raw, index) => {
    const [id, windSpeed, waveHeight, waterTemp, stormWarning] = validateReading(raw, index);
    script.push(describeBuoy(id, waterTemp));
    script.push(describeWind(id, windSpeed));
    script.push(describeWaves(waveHeight, waterTemp));
    script.push(describeSeaState(id, waveHeight));
    if (stormWarning) {
      script.push(`Extreme weather alert for ${id}.`);
    }
  });
  script.push(`Broadcast ended for ${total} readings.`);
  return script;
}

function broadcast(readings) {
  return marine(readings)
    .map((line, position) => `${position + 1}. ${line}`)
    .join('\n');
}

const stationReadings = [
  ['B1', 15, 6, 60, true],
  ['B2', 8, 1.2, 64, false],
  ['B3', 22, 3.5, 58, true],
];

console.log(broadcast(stationReadings));
console.log(`Lines generated: ${marine(stationReadings).length}`);

module.exports = { marine, broadcast };

