function stevedore(containers) {
  const total = containers.length;
  const instructions = [`Initiating load of ${total} containers.`];

  for (const container of containers) {
    const [code, port, deck, tons, hazard] = container;

    instructions.push(`Routing ${code} to ${port}.`);
    instructions.push(`Placing ${code} on deck ${deck}.`);
    instructions.push(`Weight ${tons} tons on deck ${deck}.`);

    if (hazard === "explosive") {
      instructions.push(`Extreme caution handling ${code}.`);
    } else if (hazard === "chemical") {
      instructions.push(`Splash gear required on deck ${deck}.`);
    } else if (hazard === "general") {
      instructions.push(`Standard lift authorized for ${tons} tons.`);
    }

    if (tons > 20) {
      instructions.push(`Specialized crane for ${code}.`);
    }
  }

  instructions.push(`Dock cleared after ${total} containers.`);
  return instructions;
}

function validateManifest(containers) {
  const problems = [];

  containers.forEach((container, index) => {
    if (container.length !== 5) {
      problems.push(`Row ${index} must have 5 fields, found ${container.length}.`);
      return;
    }

    const [code, port, deck, tons, hazard] = container;

    if (typeof tons !== "number" || Number.isNaN(tons)) {
      problems.push(`Row ${index} has a non-numeric weight for ${code}.`);
    }
    if (!["explosive", "chemical", "general"].includes(hazard)) {
      problems.push(`Row ${index} has unknown hazard class "${hazard}".`);
    }
    if (!port || !deck) {
      problems.push(`Row ${index} is missing a destination or deck for ${code}.`);
    }
  });

  return problems;
}

function manifestReport(containers) {
  const problems = validateManifest(containers);
  if (problems.length > 0) {
    return problems.map((problem) => `MANIFEST ERROR: ${problem}`);
  }

  const tonnage = containers.reduce((sum, [, , , tons]) => sum + tons, 0);
  const decks = [...new Set(containers.map(([, , deck]) => deck))].sort();
  const lines = stevedore(containers);

  lines.push(`Total tonnage loaded: ${tonnage} tons.`);
  lines.push(`Decks used: ${decks.join(", ")}.`);
  return lines;
}

function main() {
  const manifest = [
    ["C1", "Miami", "A", 25, "chemical"],
    ["C2", "Lisbon", "B", 12, "explosive"],
    ["C3", "Oslo", "A", 8, "general"],
  ];

  for (const line of manifestReport(manifest)) {
    console.log(line);
  }
}

main();

