    const [code, port, deck, tons, hazard] = container;

    if (typeof tons !== "number" || Number.isNaN(tons)) {
      problems.push("Row " + index + " has a non-numeric weight for " + code + ".");
    }
    if (!["explosive", "chemical", "general"].includes(hazard)) {
      problems.push("Row " + index + " has unknown hazard class \"" + hazard + "\".");
    }
    if (!port || !deck) {
      problems.push("Row " + index + " is missing a destination or deck for " + code + ".");
    }
  });

