function parseSensor(sensor, index) {
  if (!Array.isArray(sensor) || sensor.length !== 5) {
    throw new TypeError(`Sensor entry ${index} must hold exactly 5 fields.`);
  }
  const [name, zone, code, latency, calibrated] = sensor;
  if (!Number.isFinite(latency)) {
    throw new TypeError(`Latency for ${name} must be a finite number.`);
  }
  return {
    name: String(name),
    zone: String(zone),
    code: String(code).toLowerCase(),
    latency,
    calibrated: Boolean(calibrated),
  };
}

function verdictLine(code, name, zone) {
  if (code === 'active') {
    return `Nominal operation for ${name}.`;
  }
  if (code === 'degraded') {
    return `Reduced vision in ${zone}.`;
  }
  if (code === 'offline') {
    return `Immediate repair for ${name}.`;
  }
  throw new RangeError(`Unrecognised status code ${code} reported by ${name}.`);
}

function telemetry(sensors) {
  if (!Array.isArray(sensors)) {
    throw new TypeError(`Expected an array of sensors, received ${typeof sensors}.`);
  }
  const total = sensors.length;
  const report = [`System check on ${total} sensors.`];
  sensors.forEach((sensor, index) => {
    const { name, zone, code, latency, calibrated } = parseSensor(sensor, index);
    report.push(`${name} located in ${zone}.`);
    report.push(`Status ${code} for ${name}.`);
    report.push(`Latency ${latency} in ${zone}.`);
    report.push(verdictLine(code, name, zone));
    if (!calibrated) {
      report.push(`Manual zeroing for ${name}.`);
    }
  });
  report.push(`Check complete for ${total} sensors.`);
  return report;
}

function main() {
  const fleet = [
    ['Lidar', 'front', 'degraded', 50, false],
    ['Radar', 'rear', 'active', 12, true],
    ['Camera', 'left', 'offline', 95, false],
  ];
  telemetry(fleet).forEach((line, index) => {
    console.log(`${String(index + 1).padStart(2, ' ')} ${line}`);
  });
}

main();

module.exports = { telemetry, parseSensor };

