function formatHour(hour) {
  if (!Number.isInteger(hour) || hour < 0 || hour > 23) {
    throw new RangeError(`Invalid expiration hour: ${hour}`);
  }
  return hour;
}

function severityLines(county, hazardType, severity, hour) {
  if (severity === 'critical') {
    return [`Immediate shelter in ${county}.`];
  }
  if (severity === 'elevated') {
    return [`Advising caution until ${hour}.`];
  }
  if (severity === 'minor') {
    return [`Normal operations despite ${hazardType}.`];
  }
  return [];
}

function hazardLines(hazard) {
  const [county, hazardType, severity, expirationHour, evacuate] = hazard;
  if (!county || !hazardType) {
    throw new TypeError(`Hazard entry is missing a county or type: ${hazard.join(', ')}`);
  }
  const hour = formatHour(expirationHour);
  const lines = [`Advising ${county}`
    + ` of ${hazardType}.`];
  lines.push(`Level ${severity}`
    + ` in ${county}.`);
  lines.push(`Warning until ${hour}`
    + ` for ${hazardType}.`);
  lines.push(...severityLines(county, hazardType, severity, hour));
  if (evacuate === true) {
    lines.push(`Residents of ${county} leave immediately.`);
  }
  return lines;
}

function alert(hazards) {
  if (!Array.isArray(hazards)) {
    throw new TypeError(`Expected a list of hazards, received ${typeof hazards}`);
  }
  const total = hazards.length;
  const scroll = [`Update for ${total} hazards.`];
  for (const hazard of hazards) {
    scroll.push(...hazardLines(hazard));
  }
  scroll.push(`Broadcast concluded for ${total} hazards.`);
  return scroll;
}

function renderScroll(hazards) {
  return alert(hazards)
    .map((sentence, index) => {
      const label = `${index + 1}.`;
      return label + ' ' + sentence;
    })
    .join('\n');
}

function main() {
  const feed = [
    ['Clark', 'Flood', 'critical', 18, true],
    ['Marion', 'Wind', 'elevated', 21, false],
    ['Boone', 'Fog', 'minor', 7, false]
  ];
  console.log(renderScroll(feed));
  const evacuations = feed.filter((hazard) => hazard[4] === true);
  console.log(`Counties under evacuation order: ${evacuations.length}`);
}

main();

module.exports = { alert, renderScroll, hazardLines, formatHour };

