function validateSegment(segment, index) {
  if (!Array.isArray(segment) || segment.length !== 5) {
    throw new Error(`Segment ${index + 1} must list name, elevation, heading, snow and risk.`);
  }
  const [name, elevation, heading, snow, risk] = segment;
  if (typeof elevation !== "number" || Number.isNaN(elevation)) {
    throw new Error(`Segment "${name}" has a non-numeric elevation.`);
  }
  return { name, elevation, heading, snow, risk: String(risk).toLowerCase() };
}

function approachLines(seg) {
  return [
    `Head ${seg.heading} to ${seg.name}.`,
    `Elevation ${seg.elevation} at ${seg.name}.`,
    `Snow ${seg.snow} on ${seg.heading}.`,
  ];
}

function riskLine(seg) {
  if (seg.risk === "high") {
    return `No entry to ${seg.name}.`;
  }
  if (seg.risk === "moderate") {
    return `Beacon checks at ${seg.elevation}.`;
  }
  if (seg.risk === "low") {
    return `Safe passage over ${seg.snow}.`;
  }
  throw new Error(`Unknown avalanche risk "${seg.risk}" for ${seg.name}.`);
}

function alpine(segments) {
  if (!Array.isArray(segments)) {
    throw new Error("alpine expects a list of segment lists.");
  }
  const total = segments.length;
  const guide = [`Expedition of ${total} segments.`];
  segments.forEach((raw, index) => {
    const seg = validateSegment(raw, index);
    guide.push(...approachLines(seg));
    guide.push(riskLine(seg));
    if (seg.elevation > 3000) {
      guide.push(`Thin air at ${seg.name}.`);
    }
  });
  guide.push(`Safe descent after ${total} segments.`);
  return guide;
}

function printGuide(title, segments) {
  const lines = alpine(segments);
  console.log(`=== ${title} ===`);
  lines.forEach((line, i) => {
    console.log(`${String(i + 1).padStart(2, " ")}. ${line}`);
  });
  console.log(`Total sentences: ${lines.length}`);
}

function main() {
  printGuide("Single peak", [["Peak", 3200, "North", "powder", "moderate"]]);
  printGuide("Full traverse", [
    ["Corbet Ridge", 2850, "East", "crust", "high"],
    ["Glacier Bowl", 3410, "South", "windslab", "low"],
    ["Larch Meadow", 1920, "West", "slush", "low"],
  ]);
  try {
    alpine([["Broken Spur", 2400, "North", "powder", "extreme"]]);
  } catch (err) {
    console.log(`Guide rejected: ${err.message}`);
  }
}

main();

module.exports = { alpine, printGuide };

