function validateArtwork(entry, index) {
  if (!Array.isArray(entry) || entry.length !== 5) {
    throw new TypeError(`Artwork ${index + 1} must be a list of five fields.`);
  }
  const [title, artist, year, medium, restored] = entry;
  if (typeof title !== 'string' || title.trim() === '') {
    throw new TypeError(`Artwork ${index + 1} is missing a piece title.`);
  }
  if (typeof artist !== 'string' || artist.trim() === '') {
    throw new TypeError(`Piece "${title}" is missing an artist name.`);
  }
  if (!Number.isInteger(year)) {
    throw new TypeError(`Piece "${title}" needs an integer creation year.`);
  }
  if (typeof medium !== 'string' || medium.trim() === '') {
    throw new TypeError(`Piece "${title}" is missing a medium type.`);
  }
  if (typeof restored !== 'boolean') {
    throw new TypeError(`Piece "${title}" needs a boolean restoration flag.`);
  }
  return { title, artist, year, medium: medium.toLowerCase(), restored };
}

function mediumHighlight(piece) {
  if (piece.medium === 'oil') {
    return `Brushwork of ${piece.artist}.`;
  }
  if (piece.medium === 'marble') {
    return `Admirable sculpture from ${piece.year}.`;
  }
  if (piece.medium === 'bronze') {
    return `Casting of ${piece.title}.`;
  }
  return null;
}

function gallery(artworks) {
  const pieces = artworks.map(validateArtwork);
  const total = pieces.length;
  const script = [`Exhibition of ${total} artworks.`];
  for (const piece of pieces) {
    script.push(`Introducing ${piece.title} by ${piece.artist}.`);
    script.push(`Dating ${piece.title} to ${piece.year}.`);
    script.push(`Medium ${piece.medium} by ${piece.artist}.`);
    const highlight = mediumHighlight(piece);
    if (highlight !== null) {
      script.push(highlight);
    }
    if (piece.restored) {
      script.push(`Conservation work on ${piece.title}.`);
    }
  }
  script.push(`Thank you for viewing ${total} artworks.`);
  return script;
}

function formatScript(sentences) {
  return sentences
    .map((sentence, index) => `${String(index + 1).padStart(3, ' ')}. ${sentence}`)
    .join('\n');
}

function main() {
  const collection = [
    ['Star', 'Gogh', 1889, 'oil', true],
    ['David', 'Buonarroti', 1504, 'marble', false],
    ['The Thinker', 'Rodin', 1904, 'bronze', true],
    ['Blue Loom', 'Ferrer', 1978, 'tapestry', false],
  ];
  const sentences = gallery(collection);
  console.log(formatScript(sentences));
  console.log(`Audio guide runtime: ${sentences.length * 6} seconds.`);
}

main();

module.exports = { gallery, formatScript };

