const REQUIRED_FIELDS = ["account", "amount", "company", "country", "flagged"];

function validateTransaction(entry, index) {
  if (!Array.isArray(entry) || entry.length !== REQUIRED_FIELDS.length) {
    throw new TypeError(`Transaction ${index} must hold ${REQUIRED_FIELDS.length} fields.`);
  }
  const [account, amount, company, country, flagged] = entry;
  if (!Number.isFinite(amount)) {
    throw new TypeError(`Transaction ${index} carries a non-numeric amount.`);
  }
  if (typeof company !== "string" || company.length === 0) {
    throw new TypeError(`Transaction ${index} is missing a shell company name.`);
  }
  if (typeof country !== "string") {
    throw new TypeError(`Transaction ${index} is missing a destination country.`);
  }
  return { account, amount, company, country, flagged: Boolean(flagged) };
}

function exitSentence({ amount, account }) {
  return `Amount ${amount} exiting ${account}.`;
}

function receiptSentence({ company, amount }) {
  return `Company ${company} receiving ${amount}.`;
}

function routingSentence({ country, account }) {
  return `Routing to ${country} from ${account}.`;
}

function jurisdictionSentence({ country, company, amount, account }) {
  if (country === "offshore") {
    return `Tax evasion by ${company}.`;
  }
  if (country === "domestic") {
    return `Local routing for ${amount}.`;
  }
  if (country === "sanctioned") {
    return `Embargo violation by ${account}.`;
  }
  return null;
}

function ledger(transactions) {
  const total = transactions.length;
  const sentences = [`Investigation into ${total} transactions.`];
  transactions.forEach((entry, index) => {
    const record = validateTransaction(entry, index);
    sentences.push(exitSentence(record));
    sentences.push(receiptSentence(record));
    sentences.push(routingSentence(record));
    const verdict = jurisdictionSentence(record);
    if (verdict !== null) {
      sentences.push(verdict);
    }
    if (record.flagged) {
      sentences.push(`Asset freeze on ${record.company}.`);
    }
  });
  sentences.push(`File closed on ${total} transactions.`);
  return sentences;
}

function main() {
  const transactions = [
    [123, 5000, "Corp", "sanctioned", true],
    [456, 1200, "Havenex", "offshore", false],
    [789, 340, "Midtown Supply", "domestic", true],
  ];
  const report = ledger(transactions);
  for (const sentence of report) {
    console.log(sentence);
  }
  console.log(`Report length: ${report.length} sentences.`);
}

main();

module.exports = { ledger };

