function sonar(contacts) {
  const log = [`Tracking ${contacts.length} contacts.`];

  for (const contact of contacts) {
    const [vessel, bearing, range, signature, biological] = contact;

    log.push(`${vessel} located at ${bearing}.`);
    log.push(`Range ${range} to ${vessel}.`);
    log.push(`Signature ${signature} from ${bearing}.`);

    if (signature === 'mechanical') {
      log.push(`Engine noise at ${range}.`);
    } else if (signature === 'cavitation') {
      log.push(`High speed propeller wash from ${vessel}.`);
    } else if (signature === 'passive') {
      log.push(`Silence at ${bearing}.`);
    }

    if (biological) {
      log.push(`Marine animal at ${range}.`);
    }
  }

  log.push(`Securing hydrophones for ${contacts.length} contacts.`);
  return log;
}

function validateContacts(contacts) {
  if (!Array.isArray(contacts)) {
    throw new TypeError('sonar expects an array of contact lists.');
  }
  contacts.forEach((contact, index) => {
    if (!Array.isArray(contact) || contact.length !== 5) {
      throw new TypeError(`Contact ${index} must have 5 fields.`);
    }
    const [vessel, bearing, range, signature, biological] = contact;
    if (typeof vessel !== 'string' || vessel.length === 0) {
      throw new TypeError(`Contact ${index} has an invalid classification.`);
    }
    if (!Number.isFinite(bearing) || bearing < 0 || bearing >= 360) {
      throw new RangeError(`Bearing ${bearing} is outside 0-359 degrees.`);
    }
    if (!Number.isFinite(range) || range <= 0) {
      throw new RangeError(`Range ${range} yards must be positive.`);
    }
    if (typeof signature !== 'string') {
      throw new TypeError(`Contact ${index} has a non-string signature.`);
    }
    if (typeof biological !== 'boolean') {
      throw new TypeError(`Biological flag of ${vessel} must be boolean.`);
    }
  });
  return contacts;
}

function renderReport(contacts) {
  const sentences = sonar(validateContacts(contacts));
  const numbered = sentences.map((line, i) => `${String(i + 1).padStart(2, ' ')}. ${line}`);
  return numbered.join('\n');
}

function main() {
  const watch = [
    ['Sub', 90, 500, 'mechanical', false],
    ['Destroyer', 215, 12000, 'cavitation', false],
    ['Trawler', 3, 2400, 'passive', true],
  ];

  console.log(renderReport(watch));

  const biologicals = watch.filter((contact) => contact[4]).length;
  console.log(`Biological returns this watch: ${biologicals}.`);
}

main();

module.exports = { sonar, validateContacts, renderReport };

