function validateScore(entry, index) {
  if (!Array.isArray(entry) || entry.length !== 5) {
    throw new TypeError(`Score ${index} must have 5 fields, got ${entry && entry.length}.`);
  }
  const [initials, total, level, character, recordBreaker] = entry;
  if (typeof initials !== 'string' || initials.length === 0) {
    throw new TypeError(`Score ${index} has invalid initials.`);
  }
  if (!Number.isFinite(total) || !Number.isFinite(level)) {
    throw new TypeError(`Score ${index} for ${initials} needs numeric total and level.`);
  }
  if (typeof character !== 'string' || character.length === 0) {
    throw new TypeError(`Score ${index} for ${initials} has no favorite character.`);
  }
  return { initials, total, level, character, recordBreaker: Boolean(recordBreaker) };
}

function levelLine(score) {
  if (score.level < 10) {
    return `Try again ${score.initials}.`;
  }
  if (score.level <= 20) {
    return `Solid run to ${score.level}.`;
  }
  return `Grandmaster ${score.initials}.`;
}

function scoreLines(score) {
  const lines = [`${score.initials} scored ${score.total}.`];
  lines.push(`${score.initials} survived to ${score.level}.`);
  lines.push(`${score.character} played by ${score.initials}.`);
  lines.push(levelLine(score));
  if (score.recordBreaker) {
    lines.push(`World record for ${score.total}.`);
  }
  return lines;
}

function arcade(scores) {
  if (!Array.isArray(scores)) {
    throw new TypeError(`Expected an array of scores, got ${typeof scores}.`);
  }
  const entries = scores.map(validateScore);
  const lines = [`Beat the ${entries.length} scores.`];
  for (const score of entries) {
    lines.push(...scoreLines(score));
  }
  lines.push(`Game over for ${entries.length} scores.`);
  return lines;
}

function attractMode(scores) {
  return arcade(scores).join('\n');
}

function leaderboard(scores) {
  const ranked = scores.map((entry, index) => validateScore(entry, index));
  ranked.sort((a, b) => b.total - a.total);
  return ranked.map((score, rank) => `${rank + 1}. ${score.initials} - ${score.total}`);
}

function main() {
  const scores = [
    ['AAA', 999, 25, 'Knight', true],
    ['BOB', 420, 14, 'Ranger', false],
    ['CJC', 80, 3, 'Mage', false],
  ];
  console.log(attractMode(scores));
  console.log(`Top score belongs to ${leaderboard(scores)[0]}.`);
}

main();

module.exports = { arcade, attractMode, leaderboard };

