function dispensary(scripts) {
  const total = scripts.length;
  const labels = ["Booting printer for a batch of " + total + " scripts."];

  for (const script of scripts) {
    const [patient, drug, dose, frequency, generic] = script;
    labels.push("Dispensing " + drug + " for " + patient + ".");
    labels.push("Prescribing " + dose + " mg of " + drug + ".");
    labels.push("Instructing " + patient + " to take it " + frequency + " daily.");

    if (frequency === "once") {
      labels.push("Advised morning dose of " + dose + " mg.");
    } else if (frequency === "twice") {
      labels.push("Splitting " + drug + " into a morning and an evening dose.");
    } else if (frequency === "as needed") {
      labels.push("Warning " + patient + " not to exceed the maximum daily limit.");
    }

    if (generic) {
      labels.push("Noting a cost saving generic replacement for " + drug + ".");
    }
  }

  labels.push("Shutting down after printing " + total + " scripts.");
  return labels;
}

function validateScript(script, index) {
  if (!Array.isArray(script) || script.length !== 5) {
    throw new TypeError("Script " + index + " must have exactly 5 fields.");
  }
  const [patient, drug, dose, frequency, generic] = script;
  if (typeof patient !== "string" || patient.trim() === "") {
    throw new TypeError("Script " + index + " has an invalid patient name.");
  }
  if (typeof drug !== "string" || drug.trim() === "") {
    throw new TypeError("Script " + index + " has an invalid drug name.");
  }
  if (typeof dose !== "number" || !(dose > 0)) {
    throw new RangeError("Script " + index + " has a non-positive dose: " + dose);
  }
  if (!["once", "twice", "as needed"].includes(frequency)) {
    throw new RangeError("Script " + index + " has unknown frequency \"" + frequency + "\".");
  }
  if (typeof generic !== "boolean") {
    throw new TypeError("Script " + index + " needs a boolean substitution flag.");
  }
}

function printRun(scripts) {
  scripts.forEach(validateScript);
  const labels = dispensary(scripts);
  return labels.map((line, i) => String(i + 1).padStart(3, "0") + " | " + line);
}

