const NUMBER_WORDS = [
  "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
  "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
  "sixteen", "seventeen", "eighteen", "nineteen", "twenty"
];

function spell(seconds) {
  const word = NUMBER_WORDS[seconds];
  return word ? word : `${seconds}`;
}

function validateStep(step, index) {
  const label = `step ${index + 1}`;
  if (!step || typeof step !== "object") {
    throw new TypeError(`Cue sheet ${label} must be an object.`);
  }
  for (const field of ["phaseName", "actionDescription", "propInvolved"]) {
    if (typeof step[field] !== "string" || step[field].trim() === "") {
      throw new TypeError(`Missing ${field} in ` + label + ".");
    }
  }
  if (!Number.isFinite(step.duration) || step.duration <= 0) {
    throw new RangeError(`Duration of ${label} must be a positive number.`);
  }
}

function script(steps) {
  const cues = [];
  steps.forEach((step, index) => {
    validateStep(step, index);
    const { phaseName, actionDescription, propInvolved, duration } = step;
    const timing = `${spell(duration)} seconds`;
    const prop = `the ${propInvolved}`;
    cues.push(`The ${phaseName} phase lasts ` + timing + ".");
    if (phaseName === "setup") {
      cues.push(`Perform ${actionDescription} with ` + prop + ".");
      cues.push(`Be ready in ${timing}.`);
    } else if (phaseName === "misdirection") {
      cues.push(`Wave ${prop} while you ` + actionDescription + ".");
      cues.push(`Hold their focus for ${timing}.`);
    } else if (phaseName === "prestige") {
      cues.push(`Reveal ${prop} as the ` + phaseName + " lands.");
      cues.push(`Let the ${actionDescription} breathe before the bow.`);
    }
    if (duration > 10) {
      cues.push(`Pace the ${phaseName} slowly across ` + timing + ".");
    }
  });
  return cues;
}

function renderCueSheet(cues) {
  return cues
    .map((cue, index) => `${String(index + 1).padStart(2, " ")}. ` + cue)
    .join("\n");
}

