const HIGH_CUSHION_THRESHOLD = 3;

const BALL_NAMES = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven',
  'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen'];

function sentence(...parts) {
  const text = parts.join(' ');
  const opening = text.charAt(0).toUpperCase() + text.slice(1);
  return `${opening}.`;
}

function classifyCushions(cushions) {
  if (cushions >= HIGH_CUSHION_THRESHOLD) return 'high';
  if (cushions > 0) return 'medium';
  return 'zero';
}

function cushionPhrase(cushions) {
  const band = classifyCushions(cushions);
  if (band === 'high') return 'a high cushion count';
  if (band === 'zero') return 'no cushions';
  if (cushions === 1) return 'a single cushion';
  return `${cushions} cushions`;
}

function ballName(ball) {
  return BALL_NAMES[ball] || String(ball);
}

function validateShot(shot, index) {
  const { player, ball, spin, cushions } = shot;
  const label = `shot ${index + 1}`;
  if (typeof player !== 'string' || player.trim() === '') {
    throw new TypeError(`A player name is missing on ${label}.`);
  }
  if (!Number.isInteger(ball) || ball < 1) {
    throw new RangeError(`An invalid ball number was logged on ${label}.`);
  }
  if (typeof spin !== 'string' || spin.trim() === '') {
    throw new TypeError(`A spin type is missing on ${label}.`);
  }
  if (!Number.isInteger(cushions) || cushions < 0) {
    throw new RangeError(`An invalid cushion count was logged on ${label}.`);
  }
}

function narrate(shots) {
  const lines = [];
  shots.forEach((shot, index) => {
    validateShot(shot, index);
    const { player, ball, spin, cushions } = shot;
    const ballRef = `the ${ballName(ball)} ball`;
    const cushionText = cushionPhrase(cushions);
    lines.push(sentence(player, 'targets', ballRef));
