      lines.push(sentence(player, 'calculated that deflection to the degree'));
    } else {
      lines.push(sentence('straight in with', cushionText, 'and pure', spin));
      lines.push(sentence('precision work on', ballRef));
    }
    if (spin === 'topspin') {
      lines.push(sentence(player, 'keeps the momentum rolling with that', spin));
    }
  });
  return lines;
}

