const VOLUME_WORDS = { 10: 'ten', 20: 'twenty', 30: 'thirty' };

function describeFormula(formula) {
  const { client, shade, volume, minutes } = formula;
  return `${client} / ${shade} / ${volume}vol / ${minutes}min`;
}

function validateFormula(formula, index) {
  const label = `formula #${index + 1}`;
  if (!formula || typeof formula !== 'object') {
    throw new TypeError(`Cannot read ${label}: expected an object.`);
  }
  const { client, shade, volume, minutes } = formula;
  if (typeof client !== 'string' || client.trim() === '') {
    throw new TypeError(`Missing client name in ${label}.`);
  }
  if (typeof shade !== 'string' || shade.trim() === '') {
    throw new TypeError(`Missing base shade for ${client} in ${label}.`);
  }
  if (!VOLUME_WORDS[volume]) {
    const allowed = Object.keys(VOLUME_WORDS).join(', ');
    throw new RangeError(`Developer volume ${volume} for ${client} is not one of ${allowed}.`);
  }
  if (!Number.isFinite(minutes) || minutes <= 0) {
    throw new RangeError(`Processing time for ${client} must be a positive number of minutes.`);
  }
}

function mix(formulas) {
  if (!Array.isArray(formulas)) {
    throw new TypeError('mix() expects an array of dye formulas.');
  }
  const guide = [];
  formulas.forEach((formula, index) => {
    validateFormula(formula, index);
    const { client, shade, volume, minutes } = formula;
    const word = VOLUME_WORDS[volume];
    guide.push(`Mix the ${shade} dye for ${client}.`);
    if (volume === 10) {
      guide.push(`Deposit the ${shade} tone with ${word} volume developer.`);
      guide.push(`Check the tone on ${client} every five minutes.`);
    } else if (volume === 20) {
      guide.push(`Use ${word} volume developer with the ${shade} dye.`);
      guide.push(`Confirm full grey coverage for ${client}.`);
    } else if (volume === 30) {
      guide.push(`Lift with ${word} volume developer for ${minutes} minutes.`);
      guide.push(`Monitor the ${shade} base closely while it lifts.`);
    }
    if (minutes > 40) {
      guide.push(`Warn ${client} that ${minutes} minutes may damage the hair.`);
    }
  });
  return guide;
}

function printGuide(formulas) {
  const steps = mix(formulas);
  formulas.forEach((formula) => {
    console.log(`Formula: ${describeFormula(formula)}`);
  });
  console.log(`Generated ${steps.length} mixing sentences:`);
  steps.forEach((step, index) => {
    console.log(`${index + 1}. ${step}`);
  });
  return steps;
}

const salonBook = [
  { client: 'Mary', shade: 'blonde', volume: 20, minutes: 30 },
  { client: 'Jonas', shade: 'ash brown', volume: 10, minutes: 25 },
  { client: 'Priya', shade: 'copper', volume: 30, minutes: 45 },
];

printGuide(salonBook);

module.exports = { mix, describeFormula, printGuide };

