const formatDuration = (minutes) => {
  const rounded = Math.round(minutes * 100) / 100;
  return Number.isInteger(rounded) ? `${rounded}` : rounded.toFixed(2);
};

const formatDelta = (delta) => {
  const sign = delta < 0 ? '-' : '+';
  return `${sign}${formatDuration(Math.abs(delta))}`;
};

const validate = (splits) => {
  if (!splits || typeof splits !== 'object') {
    throw new TypeError(`Expected a game record, got ${typeof splits}`);
  }
  if (!Array.isArray(splits.segments)) {
    throw new TypeError(`Game record for "${splits.title}" must carry a segments array`);
  }
  splits.segments.forEach((segment, index) => {
    if (typeof segment.actual !== 'number' || typeof segment.target !== 'number') {
      throw new TypeError(`Segment ${index + 1} needs numeric target and actual times`);
    }
  });
};

function narrate(splits) {
  validate(splits);
  const lines = [`=== ${splits.runner} is playing ${splits.title} ===`];
  lines.push(`Category: ${splits.category}`);
  let total = 0;
  for (const segment of splits.segments) {
    lines.push(`Stage ${segment.stage} completed in ${formatDuration(segment.actual)} minutes`);
    const delta = segment.actual - segment.target;
    if (delta < 0) {
      lines.push(`  Great pace! ${formatDelta(delta)} against a target of ${formatDuration(segment.target)}`);
    } else if (delta > 0) {
      lines.push(`  Careful, that stage ran long: ${formatDelta(delta)} over target`);
    }
    total += segment.actual;
  }
  lines.push(`Final time: ${formatDuration(total)} minutes`);
  lines.push(`Thanks for running, ${splits.runner}!`);
  return lines;
}

const run = {
  title: 'Quest',
  category: 'Any%',
  runner: 'Alice',
  segments: [
    { stage: 'Woods', target: 6, actual: 5 },
    { stage: 'Caves', target: 8, actual: 8 },
    { stage: 'Castle', target: 10, actual: 12.5 }
  ]
};

console.log(narrate(run).join('\n'));

module.exports = { narrate, formatDuration, formatDelta };

