function normalizeName(raw, label) {
  if (typeof raw !== 'string' || raw.trim() === '') {
    throw new TypeError(`The ${label} must be a non-empty string`);
  }
  return raw.trim();
}

function describeTerrain(rating) {
  const stars = Number(rating);
  if (!Number.isFinite(stars) || stars < 1 || stars > 5) {
    throw new RangeError(`Terrain rating ${rating} is outside the 1-5 scale`);
  }
  const label = stars >= 4 ? 'demanding' : stars >= 2.5 ? 'moderate' : 'gentle';
  return `Warning: terrain is rated ${stars} and counts as ${label}`;
}

function swapLines(record, index) {
  if (record === null || typeof record !== 'object') {
    throw new TypeError(`Swap #${index + 1} is not a record object`);
  }
  const item = normalizeName(record.item, `item of swap #${index + 1}`);
  const action = record.taken ? 'retrieved' : 'deposited';
  const condition = normalizeName(record.condition, `condition of ${item}`);
  return [
    `Finder ${action} the ${item}`,
    `Its condition: ${condition}`
  ];
}

function logbook(discoveries) {
  if (discoveries === null || typeof discoveries !== 'object') {
    throw new TypeError('logbook expects a discoveries object');
  }
  const finder = normalizeName(discoveries.finder, 'finder name');
  const location = normalizeName(discoveries.location, 'location name');
  const swaps = Array.isArray(discoveries.swaps) ? discoveries.swaps : [];

  const sentences = [`${finder} found the cache at ${location}`];
  sentences.push(describeTerrain(discoveries.terrain));

  swaps.forEach((record, index) => {
    sentences.push(...swapLines(record, index));
  });

  sentences.push(`The expedition was a success for ${finder}`);
  return sentences;
}

function renderLogbook(discoveries) {
  return logbook(discoveries)
    .map((line, index) => `${index + 1}. ${line}`)
    .join('\n');
}

module.exports = { logbook, renderLogbook, describeTerrain };

