const NUMBER_WORDS = [
  'zero', 'one', 'two', 'three', 'four', 'five', 'six',
  'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve'
];

function spellTime(seconds) {
  const unit = seconds === 1 ? 'second' : 'seconds';
  if (Number.isInteger(seconds) && seconds >= 0 && seconds < NUMBER_WORDS.length) {
    return `${NUMBER_WORDS[seconds]} ${unit}`;
  }
  return `${seconds.toFixed(2)} ${unit}`;
}

function validateRun(run) {
  for (const field of ['dogName', 'breed', 'handlerName']) {
    if (typeof run[field] !== 'string' || run[field].trim() === '') {
      throw new TypeError(`Field ${field} must be a non-empty string`);
    }
  }
  if (!Array.isArray(run.obstacles)) {
    throw new TypeError('Field obstacles must be an array of records');
  }
  run.obstacles.forEach((obstacle, index) => {
    if (typeof obstacle.type !== 'string' || obstacle.type.trim() === '') {
      throw new TypeError(`Obstacle ${index} is missing a type`);
    }
    if (typeof obstacle.time !== 'number' || !Number.isFinite(obstacle.time)) {
      throw new TypeError(`Obstacle ${obstacle.type} needs a numeric completion time`);
    }
    if (!Number.isInteger(obstacle.faults) || obstacle.faults < 0) {
      throw new TypeError(`Obstacle ${obstacle.type} needs a fault count of zero or more`);
    }
  });
}

function faultNote(faults) {
  const penalty = faults === 1 ? 'fault' : 'faults';
  return `That costs the team ${faults} ${penalty}`;
}

function commentate(run) {
  validateRun(run);
  const { dogName, breed, handlerName, obstacles } = run;
  const lines = [`${dogName} the ${breed} is on the course`];
  lines.push(`${handlerName} takes position at the starting line`);

  let totalFaults = 0;
  for (const obstacle of obstacles) {
    lines.push(`Cleared the ${obstacle.type} in ${spellTime(obstacle.time)}`);
    if (obstacle.faults === 0) {
      lines.push(`Flawless execution on the ${obstacle.type}`);
    } else {
      lines.push(faultNote(obstacle.faults));
    }
    totalFaults += obstacle.faults;
  }

  lines.push(`Total penalties: ${totalFaults}`);
  lines.push(`${dogName} and ${handlerName} make a formidable partnership`);
  return lines;
}

module.exports = { commentate, spellTime, faultNote };

