function formatTime(seconds) {
  return `${seconds.toFixed(2)}s`;
}

function welcomeLines(eventName, city) {
  const stage = [eventName, city].join(' in ');
  const greeting = `Welcome to ${stage}`;
  const crowdCall = `Let's hear it for the finest axes in ${city}!`;
  return [greeting, crowdCall];
}

function athleteLines(athlete) {
  const lines = [];
  const stepUp = `steps up to chop the ${athlete.wood}`;
  lines.push([athlete.name, stepUp].join(' '));
  lines.push(`Wood of choice today: ${athlete.wood}`);
  const cut = `Cut through in ${formatTime(athlete.cutTime)}`;
  const pace = `using ${athlete.swings} swings`;
  lines.push([cut, pace].join(' '));
  if (athlete.swings < 20) {
    lines.push(`Spectacular! Only ${athlete.swings} swings to finish the block!`);
  }
  return lines;
}

function findWinner(athletes) {
  return athletes.reduce((best, athlete) =>
    athlete.cutTime < best.cutTime ? athlete : best
  );
}

function validateAthlete(athlete, index) {
  const label = `athlete #${index + 1}`;
  if (!athlete || typeof athlete.name !== 'string' || !athlete.name.trim()) {
    throw new Error(`Missing person name for ${label}`);
  }
  if (typeof athlete.wood !== 'string' || !athlete.wood.trim()) {
    throw new Error(`Missing wood type for ${athlete.name}`);
  }
  if (!Number.isFinite(athlete.cutTime) || athlete.cutTime <= 0) {
    throw new Error(`Invalid cut time for ${athlete.name}`);
  }
  if (!Number.isInteger(athlete.swings) || athlete.swings <= 0) {
    throw new Error(`Invalid swing count for ${athlete.name}`);
  }
}

function announce(competition) {
  const { eventName, city, athletes } = competition;
  if (!Array.isArray(athletes) || athletes.length === 0) {
    throw new Error(`No athletes registered for ${eventName}`);
  }
  athletes.forEach(validateAthlete);

  const announcements = welcomeLines(eventName, city);
  for (const athlete of athletes) {
    announcements.push(...athleteLines(athlete));
  }

  const winner = findWinner(athletes);
  const verdict = `The winner is ${winner.name}`;
  const clocked = `with a time of ${formatTime(winner.cutTime)}`;
  announcements.push([verdict, clocked].join(' '));
  announcements.push(`Thank you and goodnight from ${city}`);
  return announcements;
}

const clash = {
  eventName: 'Lumberjack Clash',
  city: 'Portland',
  athletes: [
    { name: 'John', wood: 'Pine', cutTime: 31.4, swings: 18 },
    { name: 'Marta', wood: 'Oak', cutTime: 29.75, swings: 24 },
    { name: 'Dev', wood: 'Birch', cutTime: 33.2, swings: 21 }
  ]
};

for (const line of announce(clash)) {
  console.log(line);
}

