const HIGH_HUMIDITY_THRESHOLD = 70;

function humidityIsHigh(level) {
  if (typeof level === 'number') {
    return level >= HIGH_HUMIDITY_THRESHOLD;
  }
  return String(level).trim().toLowerCase() === 'high';
}

function describeHumidity(level) {
  if (typeof level === 'number') {
    return `${level}% relative humidity`;
  }
  return `${level} humidity in the kitchen`;
}

function durationPhrase(hours) {
  if (hours === 1) {
    return `for ${hours} hour`;
  }
  return `for ${hours} hours`;
}

function stepLines(step) {
  const lines = [[step.action, durationPhrase(step.hours)].join(' ')];
  if (humidityIsHigh(step.humidity)) {
    const reading = describeHumidity(step.humidity);
    lines.push(`Dust the dough and the bench with extra flour: ${reading}`);
  }
  if (step.hours > 4) {
    lines.push(`Fermentation warning: check the dough twice while you ${step.action.toLowerCase()}`);
  }
  return lines;
}

function validateRecipe(recipe) {
  if (!recipe || typeof recipe.breadName !== 'string' || recipe.breadName.trim() === '') {
    throw new TypeError('A recipe needs a non-empty bread name');
  }
  if (!Number.isFinite(recipe.starterPercent)) {
    throw new TypeError(`Starter percentage must be a number, got ${recipe.starterPercent}`);
  }
  if (!Number.isFinite(recipe.ambientTemp)) {
    throw new TypeError(`Ambient temperature must be a number, got ${recipe.ambientTemp}`);
  }
  if (!Array.isArray(recipe.steps)) {
    throw new TypeError(`Steps must be given as a list for ${recipe.breadName}`);
  }
  recipe.steps.forEach((step, index) => {
    const position = index + 1;
    if (!step || typeof step.action !== 'string' || step.action.trim() === '') {
      throw new TypeError(`Step ${position} needs an action name`);
    }
    if (!Number.isFinite(step.hours) || step.hours <= 0) {
      throw new RangeError(`Step ${position} needs a positive duration in hours`);
    }
  });
}

function schedule(recipe) {
  validateRecipe(recipe);
  const lines = [`Recipe for ${recipe.breadName}`];
  lines.push(`Starter: ${recipe.starterPercent}% of the flour weight`);
  lines.push(`Ambient temperature: ${recipe.ambientTemp} degrees`);
  for (const step of recipe.steps) {
    lines.push(...stepLines(step));
  }
  lines.push(`Good bake with your ${recipe.breadName}!`);
  return lines;
}

const recipes = [
  {
    breadName: 'Rye Loaf',
    starterPercent: 20,
    ambientTemp: 22,
    steps: [
      { action: 'Knead', hours: 2, humidity: 'low' },
      { action: 'Bulk ferment', hours: 6, humidity: 'high' }
    ]
  },
  {
    breadName: 'Country Sourdough',
    starterPercent: 15,
    ambientTemp: 26,
    steps: [
      { action: 'Autolyse', hours: 1, humidity: 55 },
      { action: 'Shape', hours: 1, humidity: 82 },
      { action: 'Cold proof', hours: 12, humidity: 65 }
    ]
  }
];

for (const recipe of recipes) {
  schedule(recipe).forEach((line) => console.log(line));
  console.log('');
}

module.exports = { schedule, stepLines, durationPhrase, humidityIsHigh };

