function heading(site) {
  return `Case heading: ${site}`;
}

function investigatorLine(investigator) {
  return `Lead investigator in charge: ${investigator}`;
}

function energyComparison(room) {
  const delta = room.peakEnergy - room.baseEnergy;
  const comparison = `Base energy ${room.baseEnergy} rose to peak energy ${room.peakEnergy}`;
  return `${comparison} (a swing of ${delta})`;
}

function roomNotes(room) {
  const notes = [`Sweeping the ${room.name}`];
  notes.push(energyComparison(room));
  if (room.peakEnergy > 50) {
    notes.push(`DANGER: readings in the ${room.name} exceed the safe threshold of fifty`);
  }
  notes.push(`Entity suspected: ${room.entitySuspected}`);
  return notes;
}

function validateRoom(room, index) {
  if (!room || typeof room.name !== 'string' || room.name.trim() === '') {
    throw new Error(`Room record ${index} is missing a room name`);
  }
  if (!Number.isFinite(room.baseEnergy) || !Number.isFinite(room.peakEnergy)) {
    throw new Error(`Room ${room.name} must have numeric base and peak energy levels`);
  }
  if (typeof room.entitySuspected !== 'string' || room.entitySuspected.trim() === '') {
    throw new Error(`Room ${room.name} is missing the entity suspected`);
  }
}

function recommendation(site, investigator, rooms) {
