function formatTime(seconds) {
  const whole = Math.floor(seconds);
  const hundredths = Math.round((seconds - whole) * 100);
  return `${whole}.${String(hundredths).padStart(2, '0')}s`;
}

function describeCollisions(count) {
  const gates = count === 1 ? 'gate' : 'gates';
  return `  Structural damage: ${count} ${gates} clipped`;
}

function validateRace(race) {
  const problems = [];
  for (const field of ['pilot', 'drone', 'track']) {
    if (!race[field]) {
      problems.push(`missing ${field}`);
    }
  }
  if (!Array.isArray(race.laps) || race.laps.length === 0) {
    problems.push('no lap records');
  }
  if (problems.length > 0) {
    throw new Error(`Cannot broadcast: ${problems.join(', ')}`);
  }
}

function broadcast(race) {
  validateRace(race);
  const lines = [`Welcome to ${race.track}!`];
  lines.push(`${race.pilot} is flying the ${race.drone}`);

  let fastest = race.laps[0];
  for (const lap of race.laps) {
    lines.push(`Lap ${lap.lap} finished in ${formatTime(lap.time)}`);
    if (lap.collisions === 0) {
      lines.push('  Clean sector, not a single gate touched');
    } else {
      lines.push(describeCollisions(lap.collisions));
    }
    if (lap.time < fastest.time) {
      fastest = lap;
    }
  }

  lines.push(`Fastest lap: lap ${fastest.lap} at ${formatTime(fastest.time)}`);
  lines.push(`Signing off from ${race.track}, see you next season!`);
  return lines;
}

