    { lap: 3, time: 33.75, collisions: 1 },
  ],
};

for (const line of broadcast(demoRace)) {
  console.log(line);
}

const totalGates = demoRace.laps.reduce((sum, lap) => sum + lap.collisions, 0);
console.log(`Total gates clipped over ${demoRace.laps.length} laps: ${totalGates}`);

