const GEAR_BY_HAZARD = {
  asbestos: 'a P3 respirator and disposable coveralls',
  mold: 'an N95 mask and nitrile gloves',
  lead: 'a HEPA vacuum and washable overalls',
  electrical: 'insulated gloves and an arc-flash face shield',
  structural: 'a hard hat and steel-toed boots'
};

function gearFor(hazardType) {
  const key = hazardType.trim().toLowerCase();
  return GEAR_BY_HAZARD[key] || 'full personal protective equipment';
}

function severityLabel(severity) {
  const level = severity.trim().toLowerCase();
  if (level === 'critical') return 'CRITICAL';
  if (level === 'high') return 'HIGH';
  return level;
}

function report(site) {
  const name = site.name;
  const lines = [`Dossier for ${name}`];
  lines.push(`Constructed in ${site.year}`);

  const hazards = site.hazards || [];
  hazards.forEach(hazard => {
    const label = severityLabel(hazard.severity);
    lines.push(`${hazard.type} found in the ${hazard.area}`);
    lines.push(`Severity of this finding: ${label}`);
    if (label === 'CRITICAL') {
      lines.push(`Evacuate the ${hazard.area} immediately`);
    }
    lines.push(`Wear ${gearFor(hazard.type)} while working here`);
  });

  lines.push(`Overall survey complete for ${name}`);
  return lines;
}

function criticalCount(site) {
  return (site.hazards || []).filter(h => severityLabel(h.severity) === 'CRITICAL').length;
}

function summarize(site) {
  const total = (site.hazards || []).length;
  return `${site.name}: ${total} findings logged, ${criticalCount(site)} requiring evacuation`;
}

