const ONES = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight',
  'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen',
  'seventeen', 'eighteen', 'nineteen'];
const TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy',
  'eighty', 'ninety'];

function toWords(n) {
  if (!Number.isInteger(n) || n < 0 || n > 999) {
    throw new Error(`Cannot spell out the value ${n}`);
  }
  if (n < 20) {
    return ONES[n];
  }
  if (n < 100) {
    const tensWord = TENS[Math.floor(n / 10)];
    const unit = n % 10;
    return unit === 0 ? tensWord : `${tensWord}-` + ONES[unit];
  }
  const hundredWord = `${ONES[Math.floor(n / 100)]} hundred`;
  const remainder = n % 100;
  return remainder === 0 ? hundredWord : `${hundredWord} and ` + toWords(remainder);
}

function eaterLines(eater, index) {
  const name = String(eater.name || '').trim();
  if (!name) {
    throw new Error(`Eater number ${index + 1} has no name`);
  }
  const amount = eater.amount;
  if (!Number.isInteger(amount) || amount < 0) {
    throw new Error(`Invalid amount consumed for ${name}`);
  }
  const fouls = eater.fouls || 0;
  const amountWord = toWords(amount);
  const lines = [`${name} consumed ` + amountWord];
  if (amount > 50) {
    lines.push(`${name} has a massive appetite`);
  }
  if (fouls > 0) {
    const foulWord = fouls === 1 ? 'foul' : 'fouls';
    const foulPhrase = toWords(fouls) + ' ' + foulWord;
    lines.push(`Penalty deduction for ${name}: ` + foulPhrase);
  }
  return lines;
}

function ticker(contest) {
  const food = String(contest.food || '').trim();
  if (!food) {
    throw new Error('A food item is required to start the challenge');
  }
  const limitWord = toWords(contest.timeLimit);
  const lines = [`Challenge for ${food} with a limit of ` + limitWord];
  const eaters = contest.eaters || [];
  let total = 0;
  eaters.forEach((eater, index) => {
    total += eater.amount;
    eaterLines(eater, index).forEach((line) => lines.push(line));
  });
  const totalWord = toWords(total);
  lines.push(`Grand total consumed: ${totalWord}`);
  lines.push('The eating contest is over');
  return lines;
}

const nathansClassic = {
  food: 'Hot Dogs',
  timeLimit: 10,
  eaters: [
    { name: 'Joey', amount: 40, fouls: 0 },
    { name: 'Molly', amount: 62, fouls: 2 },
    { name: 'Sam', amount: 18, fouls: 1 }
  ]
};

ticker(nathansClassic).forEach((line, index) => {
  const stamp = toWords(index + 1);
  console.log(`[${stamp}] ` + line);
});

module.exports = { ticker, toWords, eaterLines };

