const PERFECT_SCORE = 10;
const NUMBER_WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten'];

function spellPoints(points) {
  if (points >= 0 && points < NUMBER_WORDS.length) {
    return NUMBER_WORDS[points];
  }
  return `${points}`;
}

function validateEntry(entry) {
  if (!entry || typeof entry !== 'object') {
    throw new TypeError('A judging entry must be an object');
  }
  for (const field of ['team', 'title', 'sand']) {
    const value = entry[field];
    if (typeof value !== 'string' || value.trim() === '') {
      throw new TypeError(`The judging card needs a non-empty ${field}`);
    }
  }
  if (!Array.isArray(entry.scores) || entry.scores.length === 0) {
    throw new TypeError(`Team ${entry.team} has no score records to judge`);
  }
  for (const record of entry.scores) {
    if (typeof record.category !== 'string' || typeof record.remark !== 'string') {
      throw new TypeError(`A score record for ${entry.team} is missing its category or remark`);
    }
    const points = record.points;
    if (!Number.isInteger(points) || points < 0 || points > PERFECT_SCORE) {
      throw new RangeError(`Points for ${record.category} must be whole numbers up to ${PERFECT_SCORE}`);
    }
  }
}

function judge(entry) {
  validateEntry(entry);
  const { team, title, sand, scores } = entry;
  const lines = [`Judging team ${team}`];
  lines.push(`Sculpture ${title} carved in ${sand} sand`);

  let total = 0;
  for (const { category, points, remark } of scores) {
    lines.push(`Category ${category} scored ${spellPoints(points)}`);
    lines.push(`Judge remarks: "${remark}"`);
    if (points === PERFECT_SCORE) {
      lines.push(`Flawless category: ${category}`);
    }
    total += points;
  }

  lines.push(`Final score tally: ${spellPoints(total)}`);
  lines.push(`Thank you ${team}`);
  return lines;
}

module.exports = { judge, spellPoints, validateEntry, PERFECT_SCORE };

