const MARK_WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten'];

function markWord(mark) {
  if (typeof mark !== 'number' || Number.isNaN(mark)) {
    throw new Error('A numerical mark is required, received ' + mark);
  }
  if (mark < 0 || mark > 10) {
    throw new Error('Marks run from zero to ten, received ' + mark);
  }
  if (Number.isInteger(mark)) {
    return MARK_WORDS[mark];
  }
  const [whole, frac] = mark.toFixed(1).split('.');
  const decimalPart = 'point ' + MARK_WORDS[Number(frac)];
  return MARK_WORDS[Number(whole)] + ' ' + decimalPart;
}

function markPhrase(mark) {
  const word = markWord(mark);
  const article = /^[aeiou]/.test(word) ? 'an' : 'a';
  return article + ' ' + word;
}

function scorecard(performance) {
  const { rider, horse, level, movements } = performance;
  if (!rider || !horse) {
    throw new Error('A rider and a horse are needed, got ' + rider + ' and horse ' + horse);
  }
  if (!Array.isArray(movements) || movements.length === 0) {
    throw new Error('No movements were recorded for ' + rider);
  }
  const lines = [rider + ' is riding ' + horse];
  lines.push('The test level is ' + level);
  let total = 0;
  for (const movement of movements) {
    const { figure, mark, directive } = movement;
    const phrase = markPhrase(mark);
    lines.push(figure + ' received ' + phrase);
    lines.push('The judge directs: ' + directive);
    if (mark < 5) {
      lines.push('A mark under five is a severe deduction on ' + figure);
    }
    total += mark;
  }
  const average = total / movements.length;
  const percentage = (average * 10).toFixed(2);
  lines.push('The final percentage is ' + percentage + '%');
  lines.push('Please applaud ' + horse);
  return lines;
}

const performance = {
  rider: 'Charlotte',
  horse: 'Valegro',
  level: 'Grand Prix',
  movements: [
