const ONES = [
  'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
  'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen',
  'seventeen', 'eighteen', 'nineteen'
];
const TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
const RANKS = ['', 'first', 'second', 'third', 'fourth', 'fifth', 'sixth', 'seventh', 'eighth', 'ninth', 'tenth'];
const DANGER_SPEED = 30;

function spellNumber(value) {
  if (value < 20) return ONES[value];
  const tens = TENS[Math.floor(value / 10)];
  const unit = value % 10;
  return unit === 0 ? tens : `${tens}-${ONES[unit]}`;
}

function spellSpeed(speed) {
  const rounded = Math.round(speed);
  if (rounded < 0 || rounded > 99) {
    throw new RangeError(`Speed clocked out of broadcast range: ${speed}`);
  }
  return spellNumber(rounded);
}

function spellRank(rank) {
  const word = RANKS[rank];
  return word || `number ${spellNumber(rank)}`;
}

function checkName(label, value) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new TypeError(`A ${label} is required for the broadcast`);
  }
  return value.trim();
}

function checkpointLines(checkpoint, index) {
  const street = checkName(`street location at checkpoint ${index + 1}`, checkpoint.street);
  const speed = Number(checkpoint.speed);
  if (!Number.isFinite(speed)) {
    throw new TypeError(`Checkpoint ${index + 1} on ${street} has no speed clocked`);
  }
  const lines = [`Clocked at ${street} with ${spellSpeed(speed)} speed`];
  lines.push(`Holding ${spellRank(Number(checkpoint.rank))} position`);
  if (speed > DANGER_SPEED) {
    lines.push(`Dangerous momentum building at ${street}`);
  }
  return lines;
}

function derby(race) {
  if (!race || typeof race !== 'object') {
    throw new TypeError('The race broadcast needs a race record');
  }
  const driver = checkName('driver name', race.driver);
  const vehicle = checkName('vehicle name', race.vehicle);
  const sponsor = checkName('sponsor name', race.sponsor);
  const checkpoints = Array.isArray(race.checkpoints) ? race.checkpoints : [];
  const lines = [`Welcome to the run by ${driver}`];
  lines.push(`Thanks to ${sponsor} for backing the ${vehicle}`);
  checkpoints.forEach((checkpoint, index) => {
    lines.push(...checkpointLines(checkpoint, index));
  });
  lines.push(`What a run by ${driver}!`);
  return lines;
}

const broadcast = derby({
  driver: 'Mario',
  vehicle: 'Bullet',
  sponsor: 'Peach Motors',
  checkpoints: [
    { street: 'Main Street', speed: 30, rank: 1 },
    { street: 'Harbor Road', speed: 42, rank: 2 },
    { street: 'Cliff Pass', speed: 55, rank: 12 }
  ]
});

broadcast.forEach((line) => console.log(line));
console.log(`Broadcast carried ${spellNumber(broadcast.length)} lines`);

module.exports = { derby, spellSpeed, spellRank };

