function formatDuration(minutes) {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  if (hours === 0) {
    return `${rest} minutes`;
  }
  if (rest === 0) {
    return `${hours} hour${hours === 1 ? 's' : ''}`;
  }
  return `${hours}h ${rest}m`;
}

function describeAngle(angle) {
  return `about ${angle} degrees`;
}

function validateSession(session) {
  const required = ['studio', 'teacher', 'style', 'duration', 'poses', 'restingPose', 'meditationMinutes', 'finalChant', 'goodbyeGesture'];
  for (const key of required) {
    if (session[key] === undefined) {
      throw new Error(`Session data is missing the "${key}" field.`);
    }
  }
  if (!Array.isArray(session.poses) || session.poses.length === 0) {
    throw new Error('Session data must include at least one pose.');
  }
}

function narratePose(pose, previousPosture) {
  const transition = `From ${previousPosture}, move into ${pose.name}.`;
  const breathing = `${pose.breathPhase} for ${pose.breathCount} breaths.`;
  const alignment = `Draw your ${pose.focalPart} open, keeping the joint at ${describeAngle(pose.jointAngle)}.`;
  const modification = `If you need support, take a ${pose.prop} or rest in ${pose.alternative}.`;
  return [transition, breathing, alignment, modification];
}

function narrate(session) {
  validateSession(session);
  const lines = [`Welcome to ${session.studio}, led by ${session.teacher}.`];
  lines.push(`Today's practice is ${session.style} for ${formatDuration(session.duration)}.`);
  let previousPosture = 'a comfortable seat';
  for (const pose of session.poses) {
    lines.push(...narratePose(pose, previousPosture));
    previousPosture = pose.name;
  }
  lines.push(`Settle into ${session.restingPose} and meditate for ${session.meditationMinutes} minutes.`);
  lines.push(`We close with ${session.finalChant}, and I offer you ${session.goodbyeGesture}.`);
  return lines;
}

function printScript(session) {
  const script = narrate(session);
  script.forEach((line, index) => {
    console.log(`${String(index + 1).padStart(2, ' ')}. ${line}`);
  });
  console.log(`(${script.length} spoken lines in total.)`);
}

