  return `${bout.eastWrestler} faces ${bout.westWrestler} at the shikiri line.`;
}

function formatClash(bout) {
  const impact = `The tachiai lands with ${bout.impactForce} force`;
  return `${impact}, hands finding ${bout.handPlacement}.`;
}

function formatFinish(bout) {
  const technique = `A clean ${bout.winningTechnique} ends the exchange`;
  return `${technique}, leaving the loser ${bout.losingPosture}.`;
}

function formatConclusion(bout) {
  return `${bout.winner} takes the bout after ${bout.durationSeconds} seconds.`;
}

function describeBout(bout) {
  return [
    formatStareDown(bout),
    formatClash(bout),
    formatFinish(bout),
    formatConclusion(bout),
  ];
}

function recap(tournament) {
  const lines = [
    `Welcome to ${tournament.arena} for day ${tournament.dayNumber}.`,
    `Yokozuna ${tournament.grandChampion} greets you this ${tournament.season}.`,
