  return `Trail breaker ${breaker} reports ${depthText} on the route.`;
}

function arrivalAnnouncement(musher, checkpoint) {
  return `Musher ${musher} has just pulled into the ${checkpoint} checkpoint.`;
}

function dogHealthStatus(droppedDogs, packEnergy) {
  const dogWord = droppedDogs === 1 ? 'dog' : 'dogs';
  const dropped = `${droppedDogs} ${dogWord} dropped`;
  return `Vets logged ${dropped}; the remaining pack is running at ${packEnergy} energy.`;
}

function weatherUpdate(temperature, windChill) {
  const reading = `${temperature} degrees`;
  return `Current temperature is ${reading} with a wind chill factor of ${windChill}.`;
}

function departurePlan(restDuration, upcomingTerrain) {
  const rest = `${restDuration} of mandatory rest`;
  return `The team takes ${rest} before heading into ${upcomingTerrain}.`;
}

function finishPrediction(destination, arrivalTime) {
  return `The burled arch in ${destination} is expected to see this team around ${arrivalTime}.`;
}

function closingSignature(marshal, frequency) {
  return `Race marshal ${marshal} signing off on radio frequency ${frequency}.`;
}

function log(race) {
  const lines = [
    openingDispatch(race.name, race.start),
    trailCondition(race.trailBreaker, race.snowDepth),
  ];

  for (const checkpoint of race.checkpoints) {
    lines.push(arrivalAnnouncement(checkpoint.musher, checkpoint.name));
    lines.push(dogHealthStatus(checkpoint.droppedDogs, checkpoint.packEnergy));
    lines.push(weatherUpdate(checkpoint.temperature, checkpoint.windChill));
    lines.push(departurePlan(checkpoint.restDuration, checkpoint.upcomingTerrain));
  }

  lines.push(finishPrediction(race.destination, race.arrivalTime));
  lines.push(closingSignature(race.marshal, race.frequency));

  return lines;
}

