const REQUIRED_DETAILS = [
  'crew', 'floor', 'dj', 'tempo', 'rounds',
  'votingPanel', 'raisedHand', 'grandPrize', 'trophy'
];

const ROUND_DETAILS = [
  'alias', 'entryDirection', 'topRock', 'floorwork',
  'powerMove', 'syncBeat', 'opponentReaction', 'hypeChant'
];

function validateCypher(cypher) {
  for (const key of REQUIRED_DETAILS) {
    if (cypher[key] === undefined) {
      throw new Error(`Missing cypher detail: ${key}`);
    }
  }
  if (!Array.isArray(cypher.rounds)) {
    throw new TypeError(`rounds must be an array, got ${typeof cypher.rounds}`);
  }
  cypher.rounds.forEach((round, index) => {
    for (const key of ROUND_DETAILS) {
      if (round[key] === undefined) {
        const position = `round ${index + 1}`;
        throw new Error(`Missing ${key} in ` + position);
      }
    }
  });
}

function hypeLine(crew, floor) {
  const surface = `this ${floor} floor!`;
  return `${crew} crew is ready to tear up ` + surface;
}

function musicIntro(dj, tempo) {
  const beat = `breakbeats at ${tempo}`;
  return `DJ ${dj} is on the tables spinning ` + beat + ', so grab your spot!';
}

function roundLines(round) {
  const approach = `in from the ${round.entryDirection} of the cypher.`;
  const entry = `${round.alias} slides ` + approach;
  const transition = `melts down into ${round.floorwork}.`;
  const footwork = `Top-rock ${round.topRock} ` + transition;
  const timing = `dead on the ${round.syncBeat}.`;
  const freeze = `That ${round.powerMove} freeze lands ` + timing;
  const chant = `answer back with "${round.hypeChant}"!`;
  const crowd = `${round.opponentReaction} — circle, ` + chant;
  return [entry, footwork, freeze, crowd];
}

function judgeDecision(votingPanel, raisedHand) {
  const verdict = `hands are up on the ${raisedHand} side!`;
  return `The ${votingPanel} has locked in the vote: ` + verdict;
}

function winnerAnnouncement(grandPrize, trophy) {
  const hardware = `and the ${trophy} to prove it!`;
  return `They take home ${grandPrize} ` + hardware;
}

function call(cypher) {
  validateCypher(cypher);
  const script = [
    hypeLine(cypher.crew, cypher.floor),
    musicIntro(cypher.dj, cypher.tempo)
  ];
  for (const round of cypher.rounds) {
    script.push(...roundLines(round));
  }
  script.push(judgeDecision(cypher.votingPanel, cypher.raisedHand));
  script.push(winnerAnnouncement(cypher.grandPrize, cypher.trophy));
  return script;
}

