      topRock: 'Indian step',
      floorwork: 'a six-step drop',
      powerMove: 'air chair',
      syncBeat: 'snare crack',
      opponentReaction: 'Her rival just backed off shaking his head',
      hypeChant: 'Go Pop, go Pop'
    },
    {
      alias: 'Lil Turbo',
      entryDirection: 'back of the room',
      topRock: 'Brooklyn rock',
      floorwork: 'a CC to knee spin',
      powerMove: 'windmill to headstand',
      syncBeat: 'kick drum',
      opponentReaction: 'The whole bench jumped up at once',
      hypeChant: 'Turbo, Turbo'
    }
  ],
  votingPanel: 'three-judge panel',
  raisedHand: 'Zulu',
  grandPrize: 'the 500 dollar pot',
  trophy: 'golden boombox'
};

for (const [index, line] of call(tonight).entries()) {
  console.log(`${index + 1}. ` + line);
}

module.exports = { call, hypeLine, musicIntro, roundLines, judgeDecision, winnerAnnouncement };

