function formatPercent(value) {
  return `${Math.round(value)}%`;
}

function formatSeconds(value) {
  const rounded = Math.round(value * 10) / 10;
  return `${rounded}s`;
}

function requireField(performance, field) {
  const value = performance[field];
  if (value === undefined || value === null || value === '') {
    throw new Error(`Performance data is missing the "${field}" field.`);
  }
  return value;
}

function crossfadeLine(mix) {
  return `Crossfade from ${mix.outgoingTrack} into ${mix.incomingTrack}.`;
}

function equalizationLine(mix) {
  const bass = formatPercent(mix.bassCut);
  return `Cut the bass by ${bass} while riding the treble up ${formatPercent(mix.trebleBoost)}.`;
}

function timingLine(mix) {
  const window = formatSeconds(mix.crossfadeSeconds);
  return `Hold the blend for ${mix.bars} bars, a ${window} crossfade.`;
}

function effectLine(mix) {
  const feedback = formatPercent(mix.echoFeedback);
  return `Trigger the "${mix.vocalSample}" sample with echo feedback at ${feedback}.`;
}

