function requireFields(source, fields, label) {
  const missing = fields.filter((field) => !source || !source[field]);
  if (missing.length > 0) {
    throw new Error(`${label} is missing: ${missing.join(', ')}`);
  }
  return source;
}

function formatMovementCount(count) {
  const noun = count === 1 ? 'movement' : 'movements';
  return `${count} ${noun}`;
}

function footwork(movement) {
  return `Step ${movement.stepDirection} into a ${movement.stanceType} stance.`;
}

function defense(movement) {
  return `Execute a ${movement.blockStyle} block at ${movement.targetHeight} height.`;
}

function offense(movement) {
  return `Strike with the ${movement.weaponPart} toward the ${movement.impactPoint}.`;
}

function spirit(movement) {
  return `Shout "${movement.kihapSound}" with eyes fixed ${movement.eyeFocus}.`;
}

function instruct(examination) {
  requireFields(examination, ['dojang', 'grandmaster', 'beltLevel', 'startingStance'], 'Examination header');
  requireFields(examination, ['finalPivot', 'breathRhythm', 'boardType', 'holdingAssistant'], 'Closing detail');

  const script = [
    `Bow to Grandmaster ${examination.grandmaster} of the ${examination.dojang} dojang.`,
    `As a ${examination.beltLevel} belt, begin in ${examination.startingStance} stance.`,
  ];

  const movements = examination.movements || [];
  movements.forEach((movement, index) => {
    requireFields(
      movement,
      ['stepDirection', 'stanceType', 'blockStyle', 'targetHeight', 'weaponPart', 'impactPoint', 'kihapSound', 'eyeFocus'],
      `Movement ${index + 1}`
    );
    script.push(footwork(movement));
    script.push(defense(movement));
    script.push(offense(movement));
    script.push(spirit(movement));
  });

  script.push(`Pivot ${examination.finalPivot} to ready position, breathing in a ${examination.breathRhythm} rhythm.`);
  script.push(`Break the ${examination.boardType} board held by ${examination.holdingAssistant}.`);
  return script;
}

