'use strict';

const REQUIRED = [
  'park', 'surface', 'stickModel', 'springTension', 'rider',
  'bounces', 'legBurn', 'sweatLevel', 'highScore', 'worldRecord',
];

function phrase(...parts) {
  return parts.join(' ');
}

function assertSession(session) {
  const missing = REQUIRED.filter((key) => session[key] === undefined);
  if (missing.length > 0) {
    throw new Error(`Telemetry incomplete, missing: ${missing.join(', ')}`);
  }
}

function launchCall(rider, bounce) {
  const altitude = `${bounce.height} inches`;
  return phrase(rider, 'airs out to', altitude);
}

function trickCall(bounce) {
  const grab = `${bounce.handlebarGrab} grab`;
  return phrase(bounce.bodySpin, 'into a', grab);
}

function impactCall(bounce) {
  const shock = `${bounce.concreteShock} concrete shock`;
  const rebound = `${bounce.reboundForce} rebound force`;
  return phrase('absorbs', shock, 'and rides out', rebound);
}

function scoreCall(bounce) {
  const combo = `${bounce.comboMultiplier}x combo multiplier`;
  const gasp = `${bounce.audienceGasp} from the crowd`;
  return phrase(combo, 'earns', gasp);
}

function readout(session) {
  assertSession(session);
  const lines = [];
  const surfaceNote = `${session.surface} surface`;
  lines.push(`Location tag: ${phrase(session.park, 'on', surfaceNote)}.`);
  const tensionNote = `${session.springTension} tension`;
  lines.push(`Rider is on a ${phrase(session.stickModel, 'with', tensionNote)}.`);

  session.bounces.forEach((bounce, index) => {
    const marker = `Bounce ${index + 1}`;
    lines.push(phrase(marker, 'launch:', `${launchCall(session.rider, bounce)}.`));
    lines.push(phrase(marker, 'trick:', `${trickCall(bounce)}.`));
    lines.push(phrase(marker, 'impact:', `${impactCall(bounce)}.`));
    lines.push(phrase(marker, 'score:', `${scoreCall(bounce)}.`));
  });

  const burnNote = `${session.legBurn} leg burn`;
  const sweatNote = `${session.sweatLevel} sweat`;
  lines.push(`Fatigue warning: ${phrase(burnNote, 'paired with', sweatNote)}.`);
  const pointsNote = `${session.highScore} points`;
  const recordNote = `new world record: ${session.worldRecord}`;
  lines.push(`Final tally: ${phrase(pointsNote, '—', recordNote)}.`);
  return lines;
}

function main() {
  const session = {
    park: 'Riverfront Plaza',
    surface: 'cracked asphalt',
    stickModel: 'Vurtego',
