      {
        height: 102, bodySpin: 'frontside 540', handlebarGrab: 'crossed-arm tail',
        concreteShock: 'knee-rattling', reboundForce: 'snappy',
        comboMultiplier: 5, audienceGasp: 'a full stadium gasp',
      },
    ],
    legBurn: 'searing',
    sweatLevel: 'shirt-soaking',
    highScore: 9480,
