function formatInitialization(powerSource, startingSwitch) {
  return 'Powered by ' + powerSource + ', the sequence begins when the ' + startingSwitch + ' is flipped.';
}

function formatTrigger(step, index) {
  const position = 'Step ' + (index + 1);
  return position + ': the ' + step.trigger + ' ' + step.action + '.';
}

function formatKineticTransfer(step) {
  return 'Momentum passes to the ' + step.reaction + ' through a ' + step.mechanism + '.';
}

function formatTiming(step) {
  const distance = step.distance + ' of travel';
  return 'After ' + step.delay + ', the motion covers ' + distance + '.';
}

function formatSensory(step) {
  return 'You hear ' + step.sound + ' and see ' + step.spark + '.';
}

function describeStep(step, index) {
  return [
    formatTrigger(step, index),
    formatKineticTransfer(step),
    formatTiming(step),
    formatSensory(step),
  ];
}

function formatSuccess(flawless, resetTime) {
  const verdict = flawless ? 'flawless' : 'imperfect';
  return 'The run was ' + verdict + ' and the machine resets in ' + resetTime + '.';
}

function formatFinale(payoff, confettiColor) {
  return 'Grand finale: ' + payoff + ', followed by a burst of ' + confettiColor + ' confetti.';
}

function trace(contraption) {
  const lines = [
    formatTitle(contraption.projectName, contraption.creator),
    formatInitialization(contraption.powerSource, contraption.startingSwitch),
  ];
  contraption.steps.forEach((step, index) => {
    lines.push(...describeStep(step, index));
  });
  lines.push(formatSuccess(contraption.flawless, contraption.resetTime));
  lines.push(formatFinale(contraption.payoff, contraption.confettiColor));
  return lines;
}

const breakfastMachine = {
  projectName: 'Breakfast',
  creator: 'Doc',
