      delay: '1.2 seconds',
      distance: '40 centimetres',
      sound: 'a crisp wooden clatter',
      spark: 'a flash off the polished rail',
    },
    {
      trigger: 'last domino',
      action: 'tips into the tin bucket',
      reaction: 'pulley basket',
      mechanism: 'counterweighted rope',
      delay: 'half a second',
      distance: '1.5 metres',
