    },
  ],
  flawless: true,
  resetTime: 'under three minutes',
  payoff: 'the toaster ejects a perfect slice',
  confettiColor: 'gold',
};

for (const line of trace(breakfastMachine)) {
  console.log(line);
}

module.exports = { trace, describeStep };

