  return `Set ${toss.performerGroup} with flags angled at ${toss.flagAngle} degrees.`;
}

function releaseMechanic(toss) {
  return `Release on a ${toss.bodySpin} body spin, launching to ${toss.releaseHeight}.`;
}

function visualTrajectory(toss) {
  return `Silk flutters ${toss.silkFlutter} through ${toss.apexRotations} rotations at apex.`;
}

function catchInstruction(toss) {
  return `Catch ${toss.catchPosition} on the ${toss.footStomp} foot stomp.`;
}

function visualHold(pose, smile) {
  return `Hold the ${pose} pose with a ${smile} smile.`;
}

function uniformShine(uniform, reflection) {
  return `The ${uniform} uniforms catch ${reflection} from the stadium lights.`;
}

function choreograph(performance) {
  const lines = [
    showIntroduction(performance.showTitle, performance.bandDirector),
    weatherCondition(performance.windSpeed, performance.sunGlareAngle)
  ];
