function formatSection(section, index) {
  const {
    color,
    shapeFormation,
    toppleSpeed,
    kineticSound,
    specialGimmick,
    verticalDrop,
    pieceCount,
    transition,
  } = section;
  const position = index + 1;
  const initiation = `Section ${position}: the ${color} dominoes fall into a ${shapeFormation} formation.`;
  const velocity = `They topple at ${toppleSpeed}, filling the hall with ${kineticSound}.`;
  const feature = `A ${specialGimmick} carries the cascade down a ${verticalDrop} drop.`;
  const summary = `${pieceCount} pieces later, the run ${transition}.`;
  return [initiation, velocity, feature, summary];
}

function describeVenue(floorSpace, cameraAngle) {
  return `The rally covers ${floorSpace} of floor space, filmed from ${cameraAngle}.`;
}

function validateExhibition(exhibition) {
  if (!exhibition || typeof exhibition !== 'object') {
    throw new TypeError('narrate() requires an exhibition object.');
  }
  const { sections } = exhibition;
  if (!Array.isArray(sections)) {
    throw new TypeError(`Expected sections to be an array, got ${typeof sections}.`);
  }
  sections.forEach((section, index) => {
    if (!section || typeof section !== 'object') {
      throw new TypeError(`Section ${index + 1} is not a valid track section.`);
    }
  });
  return sections;
}

function narrate(exhibition) {
  const sections = validateExhibition(exhibition);
  const {
    theme,
    team,
    floorSpace,
    cameraAngle,
    lastTowerHeight,
    cheerVolume,
    recordTitle,
    adjudicator,
  } = exhibition;

  const script = [];
  script.push(`Team ${team} presents their ${theme} rally.`);
  script.push(describeVenue(floorSpace, cameraAngle));

  sections.forEach((section, index) => {
    script.push(...formatSection(section, index));
  });

  script.push(`The final cascade tips a ${lastTowerHeight} tower as the crowd roars at ${cheerVolume}.`);
  script.push(`The run is certified as the ${recordTitle} by ${adjudicator}.`);
  return script;
}

const spaceRally = {
  theme: 'Space',
  team: 'Dynamo',
  floorSpace: '1,200 square metres',
  cameraAngle: 'a slow overhead crane shot',
  sections: [
    {
      color: 'silver',
      shapeFormation: 'spiral galaxy',
      toppleSpeed: 'three metres per second',
      kineticSound: 'a rising metallic hiss',
      specialGimmick: 'magnetic launch ramp',
      verticalDrop: 'two-metre',
      pieceCount: 18400,
      transition: 'hands off cleanly to the orbit ring',
    },
    {
      color: 'cobalt',
      shapeFormation: 'comet tail',
      toppleSpeed: 'four metres per second',
      kineticSound: 'a deep rolling thunder',
      specialGimmick: 'rotating airlock gate',
      verticalDrop: 'half-metre',
      pieceCount: 9250,
      transition: 'triggers the countdown wall without a stall',
    },
  ],
  lastTowerHeight: 'four-metre',
  cheerVolume: '103 decibels',
  recordTitle: 'largest space-themed domino field',
  adjudicator: 'adjudicator Mira Halden',
};

narrate(spaceRally).forEach((line, index) => {
  console.log(`${String(index + 1).padStart(2, ' ')}. ${line}`);
});

module.exports = { narrate, formatSection, describeVenue };

