    envelopeVolume,
    gasType,
    boilerPressure,
    burnerStatus,
    propellerCount,
    hullIntegrity,
    destination
  } = validate(airship);

  const lift = [envelopeVolume, 'cubic meters of', gasType].join(' ');
  const entries = [];
  entries.push(`Maintenance log for the ${vesselName}.`);
