const REQUIRED_FIELDS = [
  'dialType',
  'direction',
  'gnomonHeight',
  'shadowLength',
  'hourSpacing',
  'motto',
  'pedestal',
  'city',
  'hemisphere',
];

function validate(sundial) {
  if (sundial === null || typeof sundial !== 'object') {
    throw new TypeError(`Expected a sundial specification object, received ${typeof sundial}.`);
  }
  for (const field of REQUIRED_FIELDS) {
    const value = sundial[field];
    if (typeof value !== 'string' || value.trim() === '') {
      throw new TypeError(`The sundial specification is missing a usable "${field}" value.`);
    }
  }
}

function read(sundial, field) {
  return sundial[field].trim();
}

function plot(sundial) {
  validate(sundial);
  const city = read(sundial, 'city');
  return [
    `Designing a ${read(sundial, 'dialType')} sundial for ${city} in the ${read(sundial, 'hemisphere')} hemisphere.`,
    `The dial face must orient towards the ${read(sundial, 'direction')}.`,
    `Erect a gnomon with a height of ${read(sundial, 'gnomonHeight')} inches.`,
    `Calculate a maximum shadow length of ${read(sundial, 'shadowLength')} inches.`,
    `Draft the hour lines with ${read(sundial, 'hourSpacing')} degree intervals.`,
    `Engrave the motto reading ${read(sundial, 'motto')}.`,
    `Mount the dial onto a ${read(sundial, 'pedestal')} pedestal.`,
    'Align the gnomon with true north.',
    `The ${city} sundial is ready to track time.`,
  ];
}

function formatWorkOrder(sundial) {
  const steps = plot(sundial);
  const heading = `Work order: ${read(sundial, 'dialType')} dial, ${read(sundial, 'city')}`;
  const lines = [heading, '='.repeat(heading.length)];
  steps.forEach((step, index) => {
    lines.push(`  ${index + 1}. ${step}`);
  });
  return lines.join('\n');
}

function main() {
  const romanDial = {
    dialType: 'horizontal',
    direction: 'south',
    gnomonHeight: 'six',
    shadowLength: 'twelve',
    hourSpacing: 'fifteen',
    motto: 'seize the day',
    pedestal: 'marble',
    city: 'Rome',
    hemisphere: 'northern',
  };
  const sydneyDial = {
    ...romanDial,
    dialType: 'vertical',
    direction: 'north',
    motto: 'the hours pass',
    pedestal: 'sandstone',
    city: 'Sydney',
    hemisphere: 'southern',
  };
  for (const dial of [romanDial, sydneyDial]) {
    console.log(formatWorkOrder(dial));
    console.log('');
  }
}

main();

module.exports = { plot, formatWorkOrder };

