function calculateCircleArea(radius) {
  if (typeof radius !== 'number' || Number.isNaN(radius)) {
    throw new TypeError(`radius must be a number, got ${typeof radius}`);
  }
  if (!Number.isFinite(radius)) {
    throw new RangeError(`radius must be finite, got ${radius}`);
  }
  if (radius < 0) {
    throw new RangeError(`radius must not be negative, got ${radius}`);
  }
  return Math.PI * radius * radius;
}

function calculateCircumference(radius) {
  return 2 * Math.PI * radius;
}

function formatArea(radius, digits = 4) {
  const area = calculateCircleArea(radius);
  return `A circle of radius ${radius} has area ${area.toFixed(digits)}`;
}

function describeAsMultipleOfPi(radius) {
  const factor = radius * radius;
  const shown = Number.isInteger(factor) ? `${factor}` : factor.toFixed(3);
  return `${shown} * PI`;
}

function parseRadius(text) {
  const trimmed = String(text).trim();
  const value = Number(trimmed);
  if (trimmed === '' || Number.isNaN(value)) {
    throw new TypeError(`cannot parse "${text}" as a radius`);
  }
  return value;
}

function buildReportRow(input) {
  const radius = parseRadius(input);
  const area = calculateCircleArea(radius);
  const perimeter = calculateCircumference(radius);
  return {
    radius,
    line: `r=${radius} | area=${area.toFixed(4)} (${describeAsMultipleOfPi(radius)}) | circumference=${perimeter.toFixed(4)}`,
  };
}

function buildReport(inputs) {
  const rows = [];
  for (const input of inputs) {
    try {
      rows.push(buildReportRow(input).line);
    } catch (error) {
      rows.push(`r=${input} | error: ${error.message}`);
    }
  }
  const total = rows.length;
  return `${rows.join('\n')}\n(${total} row${total === 1 ? '' : 's'} processed)`;
}

function main() {
  const samples = ['1', '2', 2.5, '0', '-3', 'circle'];
  console.log(buildReport(samples));
  console.log(formatArea(1));
  const doubled = calculateCircleArea(2) / calculateCircleArea(1);
  console.log(`Doubling the radius multiplies the area by ${doubled}`);
}

main();

module.exports = {
  calculateCircleArea,
  calculateCircumference,
  formatArea,
  describeAsMultipleOfPi,
  parseRadius,
  buildReport,
};

