const rollDice = (sides) => {
  if (typeof sides !== 'number' || !Number.isInteger(sides) || sides < 1) {
    console.error(`Invalid input: ${sides} is not a valid number of sides for a dice.`);
    throw new Error('Sides must be a positive integer.');
  }

  const min = 1;
  const max = Math.floor(sides);

  const result = Math.floor(Math.random() * (max - min + 1)) + min;

  console.log(`Rolling a ${sides}-sided die...`);
  console.log(`The result is: ${result}`);

  const message = `You rolled a ${sides}-sided die and got ${result}.`;
  console.log(message);

  if (result === 1) {
    console.warn(`Oh no, a critical miss! You rolled a ${result}.`);
  } else if (result === sides) {
    console.info(`Critical success! You rolled a ${result}.`);
  }

  const finalMessage = `Dice roll complete for ${sides} sides.`;
  console.log(finalMessage);

  return result;
};

