const calculateMedian = (arr) => {
  const sortedArr = [...arr].sort((a, b) => a - b);
  const n = sortedArr.length;

  if (n === 0) {
    throw new Error('Input array cannot be empty.');
  }

  const isEven = n % 2 === 0;
  const middleIndex = Math.floor(n / 2);

  if (isEven) {
    const value1 = sortedArr[middleIndex - 1];
    const value2 = sortedArr[middleIndex];
    const medianEven = (value1 + value2) / 2;
    console.log("Array has an even number of elements: " + n + ".");
    console.log("The two middle values are " + value1 + " and " + value2 + ".");
    return medianEven;
  } else {
    const medianOdd = sortedArr[middleIndex];
    console.log("Array has an odd number of elements: " + n + ".");
    console.log("The middle value is " + medianOdd + ".");
    return medianOdd;
  }
};

