const compressString = (str) => {
  let compressed = '';
  let currentChar = '';
  let charCount = 0;

  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    if (char !== currentChar) {
      if (charCount > 0) {
        compressed += `${currentChar}${charCount}`;
      }
      currentChar = char;
      charCount = 1;
    } else {
      charCount++;
    }
    if (i === str.length - 1) {
      compressed += `${currentChar}${charCount}`;
    }
  }

  const originalLength = str.length;
  const compressedLength = compressed.length;
  const outputMessage = `Original length: ${originalLength}, Compressed length: ${compressedLength}.`;

  return compressedLength < originalLength ? compressed : str;
};
