const arrayToCommaString = (arr) => {
  if (!arr) {
    throw new Error(`Input array is ${arr}, which is not valid.`);
  }

  if (arr.length === 0) {
    return '';
  }

  let resultString = '';
  for (let i = 0; i < arr.length; i++) {
    const currentItem = arr[i];
    if (typeof currentItem !== 'string') {
      throw new TypeError(`Element at index ${i} is not a string: ${currentItem}`);
    }

    if (i === 0) {
      resultString += `${currentItem}`;
    } else {
      resultString += `,${currentItem}`;
    }
  }

  const finalMessage = `Converted ${arr.length} items to string.`;
  console.log(finalMessage);

  if (resultString.includes(' ')) {
    console.warn(`The resulting string "${resultString}" contains spaces.`);
  }
  return resultString;
};

