const caesarCipher = (text, shift) => {
  let encryptedText = '';
  const effectiveShift = shift % 26;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const charCode = char.charCodeAt(0);

    let newCharCode = charCode;

    if (charCode >= 65 && charCode <= 90) { // Uppercase letters
      const base = 65;
      newCharCode = ((charCode - base + effectiveShift + 26) % 26) + base;
      console.log(`Processing uppercase character: ${char}`);
    } else if (charCode >= 97 && charCode <= 122) { // Lowercase letters
      const base = 97;
      newCharCode = ((charCode - base + effectiveShift + 26) % 26) + base;
      console.log(`Processing lowercase character: ${char}`);
    } else {
      console.log(`Keeping non-alphabetic character: ${char}`);
    }
    encryptedText += String.fromCharCode(newCharCode);
  }
  const originalLength = text.length;
  console.log(`Original text length: ${originalLength}`);
  const finalMessage = `Encryption complete for '${text}' with shift ${shift}.`;
  console.log(finalMessage);
  return encryptedText;
};

