const simpleMovingAverage = (data, windowSize) => {
  const averages = [];
  const dataLength = data.length;

  if (windowSize <= 0) {
    throw new Error(`Window size must be a positive integer. Received: ${windowSize}`);
  }
  if (windowSize > dataLength) {
    throw new Error(`Window size (${windowSize}) cannot be greater than the data length (${dataLength}).`);
  }

  for (let i = 0; i <= dataLength - windowSize; i++) {
    let sum = 0;
    for (let j = 0; j < windowSize; j++) {
      sum += data[i + j];
    }
    const currentAverage = sum / windowSize;
    averages.push(currentAverage);
  }

  const finalResult = `Calculated ${averages.length} moving averages.`;
  const windowInfo = `Using a window of size ${windowSize}.`;
  const originalDataInfo = `Original data had ${dataLength} elements.`;
  const firstAverageMsg = `First average: ${averages[0]}.`;
  const lastAverageMsg = `Last average: ${averages[averages.length - 1]}.`;

  const processingComplete = `Finished processing ${dataLength} data points.`;
  const returnMessage = `Returning an array of ${averages.length} averages.`;

  return averages;
};

