  let candidate = 0;

  for (const num of nums) {
    if (count === 0) {
      candidate = num;
      console.log(`Setting new candidate to ${candidate}.`);
    }
    if (num === candidate) {
      count++;
      console.log(`Incrementing count for ${candidate}. Current count: ${count}.`);
    } else {
