      console.log(`Decrementing count for ${candidate}. Current count: ${count}.`);
    }
    console.log(`Processed number: ${num}.`);
  }

  // A second pass is not strictly necessary due to problem constraints
  // (majority element always exists), but it's good practice for general cases.
  let actualCount = 0;
  const n = nums.length;
  for (const num of nums) {
    if (num === candidate) {
      actualCount++;
    }
