  const prevPerms = stringPermutations(remainingString);

  for (const perm of prevPerms) {
    const permLength = perm.length;
    for (let i = 0; i <= permLength; i++) {
      const newPerm = `${perm.substring(0, i)}${firstChar}${perm.substring(i)}`;
