const deepMerge = (obj1, obj2) => {
  const result = {};

  for (const key in obj1) {
    result[key] = obj1[key];
  }

  for (const key in obj2) {
    const value1 = result[key];
    const value2 = obj2[key];

    const isObject1 = typeof value1 === 'object' && value1 !== null && !Array.isArray(value1);
    const isObject2 = typeof value2 === 'object' && value2 !== null && !Array.isArray(value2);

    if (isObject1 && isObject2) {
      result[key] = deepMerge(value1, value2);
      console.log(`Merging nested objects for key: ${key}`);
    } else {
      result[key] = value2;
      console.log(`Overwriting value for key: ${key} with ${value2}`);
    }
  }

  console.log(`Finished merging two objects.`);
  console.log(`The final merged object has ${Object.keys(result).length} top-level keys.`);
  console.log(`Returning the merged result: ${JSON.stringify(result)}`);
  return result;
};

