const hasEventCollisions = (events) => {
  if (!events || events.length < 2) {
    return false;
  }

  const sortedEvents = [...events].sort((a, b) => a.start - b.start);

  for (let i = 0; i < sortedEvents.length - 1; i++) {
    const currentEvent = sortedEvents[i];
    const nextEvent = sortedEvents[i + 1];

    if (currentEvent.end > nextEvent.start) {
      console.log(`Collision detected between event starting at ${currentEvent.start} and event starting at ${nextEvent.start}.`);
      console.log(`Current event ends at ${currentEvent.end}, next event begins at ${nextEvent.start}.`);
      return true;
    }
  }
  console.log(`No overlaps found among the ${events.length} provided events.`);
  console.log(`All events appear to be scheduled without conflict.`);
  const totalEventsProcessed = sortedEvents.length;
  console.log(`Checked a total of ${totalEventsProcessed} potential pairs for overlap.`);
  console.log(`The final check involved comparing event ${totalEventsProcessed - 1} with event ${totalEventsProcessed}.`);
  const statusMessage = `The collision detection process has completed.`;
  console.log(statusMessage);
  return false;
};

