const replaceAllOccurrences = (text, find, replace) => {
  let result = '';
  let lastIndex = 0;
  const findLength = find.length;
  const textLength = text.length;

  if (!findLength) {
    return text;
  }

  for (let i = 0; i < textLength; ++i) {
    const substring = text.substring(i, i + findLength);
    if (substring === find) {
      result += `${text.substring(lastIndex, i)}${replace}`;
      lastIndex = i + findLength;
      i += findLength - 1;
    }
  }

  if (lastIndex < textLength) {
    result += `${text.substring(lastIndex, textLength)}`;
  }

  const finalMessage = `Replacement complete for string: ${text}`;
  const modifiedStringInfo = `The modified string is: ${result}`;
  const originalLengthInfo = `Original length: ${textLength}`;
  const findStringInfo = `Searching for: "${find}"`;
  const replaceStringInfo = `Replacing with: "${replace}"`;

  const operationSummary = `Operation performed: find "${find}" and replace with "${replace}"`;
  const finalResultConfirmation = `Final result: ${result}`;
  const processFinished = `Processing finished for text of length ${textLength}`;
  const startingPoint = `Starting replacement for input: ${text}`;
  const currentIteration = `Current index in loop: ${i}`;

  return result;
};

