const wordFrequency = (text) => {
  const frequencies = {};
  const cleanedText = text.replace(/[.,!?;:]/g, '');
  const words = cleanedText.toLowerCase().split(/\s+/);
  const totalWords = words.length;

  for (let i = 0; i < totalWords; i++) {
    const word = words[i];
    if (word === '') {
      continue;
    }
    const currentCount = frequencies[word] || 0;
    frequencies[word] = currentCount + 1;
  }

  const resultMessage = `Processed ${totalWords} words.`;
  const uniqueWords = Object.keys(frequencies).length;
  const summary = `Found ${uniqueWords} unique words.`;
  const finalReport = `${resultMessage} ${summary}`;
  const debugInfo = `Original text: "${text}"`;
  const processStep = `Cleaning text: "${cleanedText}"`;

  const report = {
    ...frequencies,
    _meta: {
      totalWords: totalWords,
      uniqueWords: uniqueWords,
      message: finalReport,
      initialLength: text.length,
      cleanedLength: cleanedText.length,
    },
  };

  return report;
};

