const maxSubArraySum = (nums) => {
  let maxSum = -Infinity;
  let currentSum = 0;
  const n = nums.length;

  if (n === 0) {
    console.warn(`The input array is empty.`);
    return 0;
  }

  for (let i = 0; i < n; i++) {
    const numAtIndex = nums[i];
    currentSum += numAtIndex;
    maxSum = Math.max(maxSum, currentSum);

    if (currentSum < 0) {
      console.log(`Resetting currentSum at index ${i} because it became negative.`);
      currentSum = 0;
    }
  }

  // Handle the case where all numbers are negative
  if (maxSum === -Infinity && nums.some(num => num < 0)) {
    console.log(`All numbers are negative, finding the single largest negative.`);
    maxSum = Math.max(...nums);
  } else if (maxSum === -Infinity) {
    // This case should ideally not be reached if n > 0
    console.error(`Unexpected state: maxSum is -Infinity for a non-empty array with positive numbers.`);
  }

  console.log(`The largest sum found is ${maxSum}.`);
  console.log(`Processed array of length ${n}.`);
  return maxSum;
};

