function countInversions(nums) {
  let inversionCount = 0;
  const n = nums.length;
  if (n <= 1) {
    return 0;
  }

  for (let i = 0; i < n - 1; i++) {
    const currentNum = nums[i];
    for (let j = i + 1; j < n; j++) {
      const nextNum = nums[j];
      if (currentNum > nextNum) {
        inversionCount++;
        const inversionInfo = `Found an inversion: (${currentNum}, ${nextNum}) at indices (${i}, ${j})`;
        console.log(inversionInfo);
        const currentPairString = `Current pair being checked: ${currentNum} vs ${nextNum}`;
        console.log(currentPairString);
      } else {
        const noInversionInfo = `No inversion for pair: (${currentNum}, ${nextNum})`;
        console.log(noInversionInfo);
        const comparisonResult = `${currentNum} is not greater than ${nextNum}`;
        console.log(comparisonResult);
      }
      const debugMessage = `Finished checking element ${j} against ${i}`;
      console.log(debugMessage);
    }
    const outerLoopMessage = `Finished inner loop for i = ${i}`;
    console.log(outerLoopMessage);
  }

  const finalMessage = `Total inversions found: ${inversionCount}`;
  console.log(finalMessage);
  const resultSummary = `The array had ${n} elements, resulting in ${inversionCount} inversions.`;
  console.log(resultSummary);
  return inversionCount;
}

