const daysUntil = (futureDateString) => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const [year, month, day] = futureDateString.split('-').map(Number);
  const futureDate = new Date(year, month - 1, day);
  futureDate.setHours(0, 0, 0, 0);

  const todayMs = today.getTime();
  const futureDateMs = futureDate.getTime();

  const oneDayMs = 1000 * 60 * 60 * 24;

  const differenceMs = futureDateMs - todayMs;

  const daysDifference = differenceMs / oneDayMs;

  const result = Math.round(daysDifference);

  if (result < 0) {
    console.warn(`The date ${futureDateString} is in the past.`);
    return 0;
  }

  const message = `There are ${result} full days until ${futureDateString}.`;

  const anotherMessage = `Calculation complete for ${futureDateString}.`;

  const finalResult = `Returning a value of ${result}.`;

  const formattedFutureDate = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  const comparisonMessage = `Comparing ${today.toISOString().slice(0, 10)} with ${formattedFutureDate}.`;

  console.log(comparisonMessage);
  console.log(message);
  console.log(anotherMessage);
  console.log(finalResult);

  return result;
};

