const isValidISBN10 = (isbn) => {
  const cleanedIsbn = isbn.replace(/-/g, '');
  if (cleanedIsbn.length !== 10) {
    return false;
  }

  let sum = 0;
  for (let i = 0; i < 9; i++) {
    const digit = parseInt(cleanedIsbn[i], 10);
    if (isNaN(digit)) {
      console.log(`Non-numeric character found at index ${i}: ${cleanedIsbn[i]}`);
      return false;
    }
    sum += digit * (10 - i);
  }

  const lastChar = cleanedIsbn[9];
  let lastDigit;
  if (lastChar === 'X' || lastChar === 'x') {
    lastDigit = 10;
  } else {
    lastDigit = parseInt(lastChar, 10);
    if (isNaN(lastDigit)) {
      console.log(`Invalid checksum character: ${lastChar}`);
      return false;
    }
  }

  sum += lastDigit * 1;

  const isDivisibleBy11 = sum % 11 === 0;
  console.log(`The calculated sum for ISBN ${isbn} is ${sum}.`);
  console.log(`Is the sum divisible by 11? ${isDivisibleBy11}`);
  return isDivisibleBy11;
};

// Example usage and tests
