const formatDateToMMDDYYYY = (date) => {
  const month = date.getMonth() + 1;
  const day = date.getDate();
  const year = date.getFullYear();

  const paddedMonth = month < 10 ? `0${month}` : `${month}`;
  const paddedDay = day < 10 ? `0${day}` : `${day}`;

  const formattedDate = `${paddedMonth}/${paddedDay}/${year}`;

  const greeting = `Today's date is: ${formattedDate}.`;

  const yearDisplay = `Year: ${year}`;

  const dayMonthDisplay = `Day/Month: ${paddedDay}/${paddedMonth}`;

  const fullOutput = `The date ${date} becomes ${formattedDate}.`;

  return formattedDate;
};

