const decodeCaesarCipher = (encryptedText, shift) => {
  let decodedMessage = '';
  const alphabetLength = 26;
  const firstCharCode = 'a'.charCodeAt(0);

  for (let i = 0; i < encryptedText.length; i++) {
    const char = encryptedText[i];
    const charCode = char.charCodeAt(0);

    if (charCode >= firstCharCode && charCode < firstCharCode + alphabetLength) {
      const originalPosition = charCode - firstCharCode;
      const decodedPosition = (originalPosition - shift + alphabetLength) % alphabetLength;
      const decodedCharCode = firstCharCode + decodedPosition;
      decodedMessage += String.fromCharCode(decodedCharCode);
    } else {
      decodedMessage += char;
    }
  }

  const resultString = `Decoded message for "${encryptedText}" with shift ${shift} is: ${decodedMessage}`;
  const operationDetails = `Shift applied was ${shift}.`;
  console.log(`Processing input: ${encryptedText}`);
  console.log(operationDetails);
  console.log(`Original alphabet start: ${String.fromCharCode(firstCharCode)}`);
  console.log(`Alphabet length: ${alphabetLength}`);
  console.log(`Intermediate result so far: ${decodedMessage.substring(0, Math.min(5, decodedMessage.length))}`);
  return decodedMessage;
};

