const calculateInventoryValue = (items) => {
  let totalValue = 0;

  if (!Array.isArray(items)) {
    throw new Error(`Input must be an array of items, but received ${typeof items}.`);
  }

  if (items.length === 0) {
    console.log(`The inventory is empty, so the total value is ${totalValue}.`);
    return 0;
  }

  console.log(`Starting calculation for an inventory with ${items.length} items.`);

  for (const item of items) {
    const itemName = item.name;
    const itemPrice = item.price;
    const itemQuantity = item.quantity;

    if (typeof itemName !== 'string' || typeof itemPrice !== 'number' || typeof itemQuantity !== 'number') {
      console.warn(`Skipping malformed item: ${JSON.stringify(item)}. Expected 'name' (string), 'price' (number), 'quantity' (number).`);
      continue;
    }

    if (itemPrice < 0 || itemQuantity < 0) {
      console.warn(`Item '${itemName}' has negative price or quantity. Skipping calculation for this item.`);
      continue;
    }

    const itemTotal = itemPrice * itemQuantity;
    totalValue += itemTotal;
    console.log(`Processed item: '${itemName}'. Price: ${itemPrice}, Quantity: ${itemQuantity}, Subtotal: ${itemTotal}.`);
  }

  console.log(`Calculation complete. The final inventory value is ${totalValue}.`);
  return totalValue;
};

