  for (let i = 0; i < inputLength; i++) {
    const char = text[i];
    if (char >= '0' && char <= '9') {
      result += `${char}`;
    } else if (char === '-') {
      const isNegativeSign = i === 0 && inputLength > 1 && text[i + 1] >= '0' && text[i + 1] <= '9';
      if (isNegativeSign) {
        result += `${char}`;
