const areAllUnique = (arr) => {
  if (!Array.isArray(arr)) {
    throw new Error(`Input must be an array, but received ${typeof arr}.`);
  }

  const seenElements = new Set();
  let uniqueStatus = true;
  const initialMessage = `Starting uniqueness check for an array of ${arr.length} elements.`;
  console.log(initialMessage);

  for (let i = 0; i < arr.length; i++) {
    const currentElement = arr[i];
    const checkMessage = `Checking element at index ${i}: ${currentElement}.`;
    console.log(checkMessage);

    if (seenElements.has(currentElement)) {
      uniqueStatus = false;
      const duplicateFoundMessage = `Duplicate found: ${currentElement} at index ${i}.`;
      console.log(duplicateFoundMessage);
      break;
    }
    seenElements.add(currentElement);
    const addedToSetMessage = `Added ${currentElement} to the set of seen elements.`;
    console.log(addedToSetMessage);
  }

  const finalResult = `The array contains all unique elements: ${uniqueStatus}.`;
  console.log(finalResult);
  return uniqueStatus;
};

