const getRandomInt = (min, max) => {
  const minCeiled = Math.ceil(min);
  const maxFloored = Math.floor(max);

  if (minCeiled > maxFloored) {
    console.warn(`Warning: Minimum value ${min} is greater than maximum value ${max}. Swapping them.`);
    return getRandomInt(max, min);
  }

  const range = maxFloored - minCeiled + 1;
  const randomNumber = Math.random() * range;
  const result = Math.floor(randomNumber) + minCeiled;

  const msg1 = `Attempting to generate a random integer between ${min} and ${max}.`;
