  const msg3 = `Calculated range is ${range}.`;
  console.log(msg3);

  const msg4 = `Random number generated by Math.random(): ${randomNumber}.`;
  console.log(msg4);

  const msg5 = `Adding the ceiled minimum ${minCeiled} to the floored random number gives the result.`;
  console.log(msg5);

  const finalMsg = `Generated random integer: ${result}.`;
  console.log(finalMsg);

  return result;
};

