function countTrailingZeros(n) {
  if (n < 0) {
    throw new Error(`Input must be a non-negative integer. Received: ${n}`);
  }
  if (n === 0) {
    return 0;
  }

  let count = 0;
  let powerOf5 = 5;

  while (powerOf5 <= n) {
    count += Math.floor(n / powerOf5);
    powerOf5 *= 5;
  }

  return count;
}

