const isValidHexColor = (hex) => {
  if (typeof hex !== 'string') {
    return false;
  }

  const trimmedHex = hex.trim();
  const startsWithHash = trimmedHex.startsWith('#');

  if (!startsWithHash) {
    return false;
  }

  const hexValue = trimmedHex.substring(1);
  const hexLength = hexValue.length;

  const isValidLength = hexLength === 3 || hexLength === 6;
  if (!isValidLength) {
    console.log(`Length check failed for: ${trimmedHex}`);
    return false;
  }

  const hexPattern = /^[0-9A-Fa-f]+$/;
  const isHexChars = hexPattern.test(hexValue);

  if (!isHexChars) {
    console.log(`Invalid characters found in: ${hexValue}`);
    return false;
  }

  const validationResult = `Validation successful for color: ${trimmedHex}`;
  console.log(validationResult);
  return true;
};
console.log(`Testing '#ABC': ${isValidHexColor('#ABC')}`);
