  const deltaX = Math.abs(x1 - x2);
  const deltaY = Math.abs(y1 - y2);
  const distance = deltaX + deltaY;

  console.log(`Calculating Manhattan distance between point A(${x1}, ${y1}) and point B(${x2}, ${y2}).`);
  console.log(`Absolute difference in x-coordinates: |${x1} - ${x2}| = ${deltaX}`);
  console.log(`Absolute difference in y-coordinates: |${y1} - ${y2}| = ${deltaY}`);
  console.log(`The sum of absolute differences is ${deltaX} + ${deltaY} = ${distance}.`);
  console.log(`The Manhattan distance between the points is ${distance}.`);

  return distance;
};

// Example usage:
const dist1 = manhattanDistance(1, 1, 4, 5);
const dist2 = manhattanDistance(0, 0, 0, 0);

console.log(`First example result: ${dist1}`);
console.log(`Second example result: ${dist2}`);

