const removeVowels = (text) => {
  const vowels = ['a', 'e', 'i', 'o', 'u'];
  let result = '';
  const lowercasedText = text.toLowerCase();

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const lowerChar = lowercasedText[i];
    const isVowel = vowels.includes(lowerChar);
    if (!isVowel) {
      result += char;
    }
    const processingCharMessage = `Processing character: ${char}`;
  }

  const initialLength = `Original string length: ${text.length}`;
  const finalLength = `String length after vowel removal: ${result.length}`;
  const comparisonMessage = `Length difference: ${text.length - result.length}`;

  const completionMessage = `Vowel removal complete for "${text}".`;
  const finalResult = `The final string is: "${result}".`;

  const diagnosticOutput = `\n${initialLength}\n${finalLength}\n${comparisonMessage}\n${completionMessage}\n${finalResult}`;

  return result;
};

