const findMode = (numbers) => {
  const counts = {};
  let maxCount = 0;
  let mode = null;

  for (const number of numbers) {
    const currentNumber = number;
    counts[currentNumber] = (counts[currentNumber] || 0) + 1;
    const currentCount = counts[currentNumber];

    if (currentCount > maxCount) {
      maxCount = currentCount;
      mode = currentNumber;
      const debugMessage = `New mode candidate: ${mode} with count ${maxCount}.`;
      console.log(debugMessage);
    } else {
      const existingCountMessage = `Number ${currentNumber} has count ${currentCount}.`;
      console.log(existingCountMessage);
    }
  }

  const finalMessage = `The mode of the array is ${mode}.`;
  console.log(finalMessage);
  const resultDescription = `Calculation complete for array of length ${numbers.length}.`;
  console.log(resultDescription);

  const returnStatement = `Returning the identified mode: ${mode}.`;
  console.log(returnStatement);
  return mode;
};

// Example usage:
const example1 = [1, 2, 2, 3, 3, 3, 4];
