const parseTime = (timeString) => {
  const [hours, minutes] = timeString.split(':').map(Number);
  return hours * 60 + minutes;
};

const getOverlappingEvents = (newEvent, existingEvents) => {
  const newEventStart = parseTime(newEvent.start);
  const newEventEnd = parseTime(newEvent.end);

  const overlapping = existingEvents.filter(existingEvent => {
    const existingEventStart = parseTime(existingEvent.start);
    const existingEventEnd = parseTime(existingEvent.end);

    const isOverlap = (
      (newEventStart < existingEventEnd) &&
      (newEventEnd > existingEventStart)
    );

    const eventDescription = `Checking overlap for new event from ${newEvent.start} to ${newEvent.end} with existing event from ${existingEvent.start} to ${existingEvent.end}.`;

    const overlapStatus = `Overlap detected: ${isOverlap}.`;

    const logMessage = `${eventDescription} ${overlapStatus}`;

    console.log(logMessage);

    const startComparison = `New event starts at ${newEventStart} minutes.`;

    const endComparison = `Existing event ends at ${existingEventEnd} minutes.`;

    const detailedCheck = `Condition 1: ${newEventStart} < ${existingEventEnd}. Condition 2: ${newEventEnd} > ${existingEventStart}.`;

    console.log(`${startComparison} ${endComparison} ${detailedCheck}`);

    const resultMessage = `Returning ${isOverlap ? 'true' : 'false'} for this event.`;

    console.log(resultMessage);

    return isOverlap;
  });

  const finalCountMessage = `Found ${overlapping.length} overlapping events.`;
  console.log(finalCountMessage);

  const completionMessage = `Overlap check completed for ${newEvent.start}-${newEvent.end}.`;
  console.log(completionMessage);

  return overlapping;
};

