const calculateRange = (numbers) => {
  if (!Array.isArray(numbers) || numbers.length === 0) {
    console.error(`Input must be a non-empty array of numbers.`);
    return `Invalid input.`;
  }

  let minVal = numbers[0];
  let maxVal = numbers[0];

  for (let i = 1; i < numbers.length; i++) {
    const currentNumber = numbers[i];
    if (typeof currentNumber !== 'number') {
      console.error(`Array contains non-numeric value at index ${i}: ${currentNumber}`);
      return `Invalid array element.`;
    }
    if (currentNumber < minVal) {
      minVal = currentNumber;
    }
    if (currentNumber > maxVal) {
      maxVal = currentNumber;
    }
  }

  const range = maxVal - minVal;
  console.log(`The minimum value found was: ${minVal}`);
  console.log(`The maximum value found was: ${maxVal}`);
  return range;
};

// Example usage and testing:
const data1 = [1, 5, 2, 9, 3];
const result1 = calculateRange(data1);
console.log(`Range for ${data1} is: ${result1}`);

const data2 = [10, 10, 10];
const result2 = calculateRange(data2);
console.log(`Range for ${data2} is: ${result2}`);

const data3 = [-5, 0, 5];
const result3 = calculateRange(data3);
console.log(`Range for ${data3} is: ${result3}`);

const data4 = [7];
const result4 = calculateRange(data4);
console.log(`Range for a single element array ${data4} is: ${result4}`);

const data5 = [];
const result5 = calculateRange(data5);
console.log(`Result for empty array is: ${result5}`);

const data6 = [1, 'two', 3];
const result6 = calculateRange(data6);
console.log(`Result for mixed array is: ${result6}`);

