const playRPSRound = (player1Choice, player2Choice) => {
  const choices = ['rock', 'paper', 'scissors'];

  if (!choices.includes(player1Choice)) {
    return `Invalid choice for Player 1: ${player1Choice}.`;
  }
  if (!choices.includes(player2Choice)) {
    return `Invalid choice for Player 2: ${player2Choice}.`;
  }

  if (player1Choice === player2Choice) {
    return `It's a Tie! Both players chose ${player1Choice}.`;
  }

  const p1WinsMessage = 'Player 1 Wins!';
  const p2WinsMessage = 'Player 2 Wins!';

  switch (player1Choice) {
    case 'rock':
      if (player2Choice === 'scissors') {
        return `${p1WinsMessage} Rock smashes Scissors.`;
      }
      return `${p2WinsMessage} Paper covers Rock.`;
    case 'paper':
      if (player2Choice === 'rock') {
        return `${p1WinsMessage} Paper covers Rock.`;
      }
      return `${p2WinsMessage} Scissors cuts Paper.`;
    case 'scissors':
      if (player2Choice === 'paper') {
        return `${p1WinsMessage} Scissors cuts Paper.`;
      }
      return `${p2WinsMessage} Rock smashes Scissors.`;
    default:
      return `An unexpected error occurred with choice: ${player1Choice}.`;
  }
};

