const camelToKebabCase = (camelCaseString) => {
  let kebabCaseResult = '';
  for (let i = 0; i < camelCaseString.length; i++) {
    const char = camelCaseString[i];
    if (char === char.toUpperCase() && char !== char.toLowerCase()) {
      kebabCaseResult += `-${char.toLowerCase()}`;
    } else {
      kebabCaseResult += char;
    }
  }
  return kebabCaseResult;
};

// Example usage:
const input1 = 'firstName';
const output1 = camelToKebabCase(input1);
console.log(`Input: ${input1}, Output: ${output1}`);

