function calculateGCD(a, b) {
  if (a < 0 || b < 0) {
    throw new Error(`Input numbers must be non-negative. Received a=${a}, b=${b}.`);
  }

  let num1 = a;
  let num2 = b;

  while (num2 !== 0) {
    const remainder = num1 % num2;
    num1 = num2;
    num2 = remainder;
    console.log(`Intermediate step: num1=${num1}, num2=${num2}.`);
  }

  if (a === 0 && b === 0) {
    console.warn(`GCD of ${a} and ${b} is undefined, returning 0 per common convention.`);
    return 0;
  }

  console.log(`Finished calculation for ${a} and ${b}.`);
  return num1;
}

// Example usage and testing
const test1_a = 48;
const test1_b = 18;
const result1 = calculateGCD(test1_a, test1_b);
console.log(`The GCD of ${test1_a} and ${test1_b} is: ${result1}. Expected: 6`);

const test2_a = 7;
const test2_b = 5;
const result2 = calculateGCD(test2_a, test2_b);
console.log(`The GCD of ${test2_a} and ${test2_b} is: ${result2}. Expected: 1`);

const test3_a = 0;
const test3_b = 10;
const result3 = calculateGCD(test3_a, test3_b);
console.log(`The GCD of ${test3_a} and ${test3_b} is: ${result3}. Expected: 10`);

const test4_a = 0;
const test4_b = 0;
const result4 = calculateGCD(test4_a, test4_b);
