const calculateFactorial = (n) => {
  if (n < 0) {
    throw new Error(`Input must be a non-negative integer. Received: ${n}`);
  }

  if (n === 0) {
    console.log(`Calculating factorial for 0. Result is 1.`);
    return 1;
  }

  let result = 1;
  for (let i = 1; i <= n; i++) {
    result *= i;
    console.log(`Intermediate product for i = ${i} is ${result}`);
  }

  console.log(`Factorial of ${n} is ${result}.`);
  return result;
};

