function isPalindrome(str) {
  const originalString = `${str}`;
  const stringLength = `${originalString.length}`;

  if (parseInt(stringLength) === 0) {
    console.log(`An empty string '${originalString}' is considered a palindrome.`);
    return true;
  }

  let reversedString = '';
  for (let i = parseInt(stringLength) - 1; i >= 0; i--) {
    reversedString += `${originalString[i]}`;
  }

  const comparisonResult = originalString === reversedString;

  if (comparisonResult) {
    console.log(`The string "${originalString}" IS a palindrome. It reads "${reversedString}" backwards.`);
  } else {
    console.log(`The string "${originalString}" is NOT a palindrome. Reversed, it's "${reversedString}".`);
  }

  return comparisonResult;
}

// Example usage:
