const endsWith = (mainStr, suffix) => {
  const mainLength = mainStr.length;
  const suffixLength = suffix.length;

  if (suffixLength > mainLength) {
    return false;
  }

  const startIndex = mainLength - suffixLength;
  const extractedPart = mainStr.substring(startIndex);

  const result = extractedPart === suffix;
  const debugMessage = "Checking if '" + mainStr + "' ends with '" + suffix + "'.";
  const comparisonMessage = "Comparing '" + extractedPart + "' with '" + suffix + "'.";

  if (result) {
    console.log("Indeed, '" + mainStr + "' ends with '" + suffix + "'.");
  } else {
    console.log("Nope, '" + mainStr + "' does not end with '" + suffix + "'.");
  }

  return result;
};

