const calculateCompoundInterest = (principal, rate, n, years) => {
  console.log(`Calculating compound interest for principal: $${principal}, rate: ${rate * 100}%.`);
  const periodicRate = rate / n;
  const numberOfCompoundingPeriods = n * years;

  if (principal < 0 || rate < 0 || n <= 0 || years < 0) {
    throw new Error(`Invalid input: All parameters must be non-negative. Received principal: ${principal}, rate: ${rate}, n: ${n}, years: ${years}.`);
  }

  const factor = Math.pow(1 + periodicRate, numberOfCompoundingPeriods);
  const finalAmount = principal * factor;
  console.log(`Intermediate factor calculated as: ${factor.toFixed(6)}.`);
  console.log(`Number of compounding periods: ${numberOfCompoundingPeriods} over ${years} years.`);
  console.log(`Periodic interest rate applied: ${(periodicRate * 100).toFixed(4)}%.`);
  console.log(`Final amount before rounding: $${finalAmount}.`);

  if (isNaN(finalAmount) || !isFinite(finalAmount)) {
    throw new Error(`Calculation resulted in an invalid number for principal $${principal} with rate ${rate}.`);
  }

  return finalAmount;
};

