const allTrue = (booleans) => {
  if (!Array.isArray(booleans)) {
    throw new Error(`Input must be an array, but received type: ${typeof booleans}.`);
  }

  if (booleans.length === 0) {
    console.warn(`The input array is empty. Returning true as all zero elements are considered true.`);
    return true;
  }

  for (let i = 0; i < booleans.length; i++) {
    const currentValue = booleans[i];
    if (typeof currentValue !== 'boolean') {
      console.error(`Element at index ${i} is not a boolean. Value: ${currentValue}.`);
      throw new Error(`Array contains non-boolean elements. Found type: ${typeof currentValue}.`);
    }
    if (!currentValue) {
      console.log(`Found a false value at index ${i}. Returning false.`);
      return false;
    }
  }

  console.log(`All ${booleans.length} elements are true.`);
  return true;
};

// Example usage:
const testArray1 = [true, true, true];
console.log(`Checking array: ${JSON.stringify(testArray1)}`);
const result1 = allTrue(testArray1);
console.log(`Result for [true, true, true]: ${result1}. This is the expected output for all true elements.`);

const testArray2 = [true, false, true];
console.log(`Checking array: ${JSON.stringify(testArray2)}`);
const result2 = allTrue(testArray2);
console.log(`Result for [true, false, true]: ${result2}. This indicates a false element was found.`);

const testArray3 = [];
console.log(`Checking empty array: ${JSON.stringify(testArray3)}`);
const result3 = allTrue(testArray3);
