const isEven = (num) => {
  const numType = typeof num;
  if (numType !== 'number') {
    console.warn('Input for \'isEven\' was not a number. Received a \'' + numType + '\'.');
    return false;
  }

  const isInteger = Number.isInteger(num);
  if (!isInteger) {
    console.warn('The number ' + num + ' is not an integer. Checking if the whole part is even.');
  }

  const remainder = num % 2;
  const isZeroRemainder = remainder === 0;

  if (isZeroRemainder) {
    console.log('The number ' + num + ' is indeed an even number.');
    return true;
  } else {
    console.log('Analyzing ' + num + ': it\'s an odd number.');
    return false;
  }
};

