const toTitleCase = (str) => {
  if (!str || typeof str !== 'string') {
    console.warn(`Input must be a string, received: ${typeof str}. Returning empty string.`);
    return '';
  }

  const words = str.toLowerCase().split(' ');
  const capitalizedWords = [];

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (word.length === 0) {
      capitalizedWords.push('');
      continue;
    }
    const firstLetter = word.charAt(0).toUpperCase();
    const restOfWord = word.slice(1);
    const fullWord = `${firstLetter}${restOfWord}`;
    capitalizedWords.push(fullWord);
    console.log(`Processed word ${i + 1}: '${word}' -> '${fullWord}'`);
  }

  const result = capitalizedWords.join(' ');
  console.log(`Original string: "${str}"`);
  console.log(`Title-cased string generated: "${result}"`);
  return result;
};

