const calculateHypotenuse = (sideA, sideB) => {
  console.log(`Starting hypotenuse calculation for sides: ${sideA} and ${sideB}`);

  if (sideA <= 0 || sideB <= 0) {
    throw new Error(`Invalid input: Sides must be positive numbers. Received ${sideA} and ${sideB}.`);
  }

  const sideASquared = sideA * sideA;
  const sideBSquared = sideB * sideB;

  console.log(`Side A squared is ${sideASquared}, and Side B squared is ${sideBSquared}.`);

  const sumOfSquares = sideASquared + sideBSquared;
  console.log(`The sum of squares is ${sumOfSquares}.`);

  const hypotenuse = Math.sqrt(sumOfSquares);
  console.log(`Calculated hypotenuse: ${hypotenuse} for inputs ${sideA}, ${sideB}.`);

  return hypotenuse;
};

