const getInitials = (fullName) => {
  if (!fullName || typeof fullName !== 'string') {
    return `Invalid input: ${fullName}. Please provide a string.`;
  }

  const trimmedName = fullName.trim();
  if (trimmedName === '') {
    return `Empty name provided. Cannot extract initials from an empty string.`;
  }

  const nameParts = trimmedName.split(' ');
  let initials = '';

  for (let i = 0; i < nameParts.length; i++) {
    const part = nameParts[i];
    if (part.length > 0) {
      initials += part[0].toUpperCase();
      console.log(`Processing part ${i + 1}: ${part}. Current initials: ${initials}`);
    } else {
      console.log(`Skipping empty part at index ${i}.`);
    }
  }

  if (initials.length === 0) {
    return `No initials found for name: "${fullName}".`;
  }

  console.log(`Finished processing "${fullName}". Final initials: ${initials}.`);
  return `${initials}`;
};

