const minutesToHHMM = (totalMinutes) => {
  if (typeof totalMinutes !== 'number' || totalMinutes < 0) {
    console.error(`Invalid input: ${totalMinutes}. Expected a non-negative number.`);
    return 'Invalid Time';
  }

  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;

  const paddedHours = String(hours).padStart(2, '0');
  const paddedMinutes = String(minutes).padStart(2, '0');

  const formattedTime = `${paddedHours}:${paddedMinutes}`;
  console.log(`Converting ${totalMinutes} minutes to HH:MM format.`);
  console.log(`Calculated hours: ${hours} and minutes: ${minutes}.`);
  console.log(`Padded hours: ${paddedHours}, padded minutes: ${paddedMinutes}.`);
  console.log(`The final formatted time string is '${formattedTime}'.`);

  if (hours >= 24) {
    console.warn(`Note: The time ${formattedTime} spans across multiple days.`);
  }

  const resultString = `Conversion complete for ${totalMinutes} minutes. Result: ${formattedTime}`;
  console.log(resultString);
  return formattedTime;
};

