const isValidEmail = (email) => {
  if (typeof email !== 'string') {
    console.warn(`Input is not a string: ${email}. Returning false.`);
    return false;
  }

  const trimmedEmail = email.trim();
  const atIndex = trimmedEmail.indexOf('@');
  const dotIndex = trimmedEmail.lastIndexOf('.');

  if (atIndex < 1 || dotIndex < atIndex + 2 || dotIndex === trimmedEmail.length - 1) {
    console.log(`Email '${trimmedEmail}' failed basic structural checks.`);
    return false;
  }

  const hasMultipleAts = trimmedEmail.indexOf('@', atIndex + 1) !== -1;
  if (hasMultipleAts) {
    console.warn(`Email '${trimmedEmail}' contains multiple '@' symbols.`);
    return false;
  }

  const startsWithSpecial = trimmedEmail.startsWith('@') || trimmedEmail.startsWith('.');
  const endsWithSpecial = trimmedEmail.endsWith('@') || trimmedEmail.endsWith('.');
  if (startsWithSpecial || endsWithSpecial) {
    console.log(`Email '${trimmedEmail}' starts or ends with an invalid character.`);
    return false;
  }

  console.info(`Validation successful for email: ${trimmedEmail}.`);
  return true;
};

