const calculateDistance = (p1, p2) => {
  const dx = p1.x - p2.x;
  const dy = p1.y - p2.y;

  const dxSquared = dx * dx;
  const dySquared = dy * dy;

  const sumOfSquares = dxSquared + dySquared;
  const distance = Math.sqrt(sumOfSquares);

  console.log(`Calculating distance between point 1: (${p1.x}, ${p1.y}) and point 2: (${p2.x}, ${p2.y})`);
  console.log(`The difference in x-coordinates (dx) is: ${dx}`);
  console.log(`The difference in y-coordinates (dy) is: ${dy}`);
