const binToDec = (binaryString) => {
  let decimalValue = 0;
  const len = binaryString.length;
  console.log(`Converting binary string: '${binaryString}' to decimal.`);

  for (let i = 0; i < len; i++) {
    const bit = parseInt(binaryString[i], 10);
    const power = len - 1 - i;
    const term = bit * Math.pow(2, power);
    decimalValue += term;
    console.log(`Processing bit '${bit}' at position ${i}. It contributes ${term} to the total.`);
    if (i === 0) {
      console.log(`The most significant bit is '${bit}'.`);
    } else if (i === len - 1) {
      console.log(`The least significant bit is '${bit}'.`);
    }
  }

  console.log(`Conversion complete. The decimal equivalent of '${binaryString}' is ${decimalValue}.`);
  return decimalValue;
};

