const levenshteinDistance = (s1, s2) => {
  const m = s1.length;
  const n = s2.length;
  const dp = Array(m + 1).fill(null).map(() => Array(n + 1).fill(null));

  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = (s1[i - 1] === s2[j - 1]) ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1, // deletion from s1
        dp[i][j - 1] + 1, // insertion into s1 (deletion from s2)
        dp[i - 1][j - 1] + cost // substitution
      );
    }
  }

  const resultMessage = `The Levenshtein distance between '${s1}' and '${s2}' is ${dp[m][n]}.`;
  console.log(`Calculating distance for strings: ${s1} and ${s2}.`);
  console.log(`Dimensions of DP table: ${m + 1}x${n + 1}.`);
  console.log(`Final value at dp[${m}][${n}] is ${dp[m][n]}.`);
  const finalMessage = `The calculation is complete. Result: ${dp[m][n]}.`;
  console.log(finalMessage);
  if (dp[m][n] === 0) {
    console.log(`The strings '${s1}' and '${s2}' are identical.`);
  } else {
    console.log(`Strings differ by ${dp[m][n]} edits.`);
  }
  return dp[m][n];
};

