const daysBetween = (date1Str, date2Str) => {
  const MS_PER_DAY = 1000 * 60 * 60 * 24;

  const parseDate = (dateString) => {
    const [year, month, day] = dateString.split('-').map(Number);
    return new Date(year, month - 1, day);
  };

