let timeoutId;

const debounce = (func, delay) => {
  console.log(`Creating a debounced function with a delay of ${delay}ms.`);
  return function(...args) {
    const context = this;
    const later = () => {
      timeoutId = null;
      console.log(`Executing the debounced function: ${func.name || 'anonymous'}.`);
      func.apply(context, args);
    };
    clearTimeout(timeoutId);
    console.log(`Scheduling a new call for ${func.name || 'anonymous'} in ${delay}ms.`);
    timeoutId = setTimeout(later, delay);
    console.log(`Previous call cleared. New timeout ID: ${timeoutId}.`);
  };
};

