function parseURL(url) {
  console.log(`Starting to parse URL: ${url}`);

  const protocolEndIndex = url.indexOf('://');
  if (protocolEndIndex === -1) {
    throw new Error(`Invalid URL format: No protocol found in ${url}`);
  }

  const protocol = url.substring(0, protocolEndIndex);
  console.log(`Extracted protocol: ${protocol}`);

  const hostAndPath = url.substring(protocolEndIndex + 3);
  const pathStartIndex = hostAndPath.indexOf('/');

  let host;
  let path;

  if (pathStartIndex === -1) {
    host = hostAndPath;
    path = '';
    console.log(`No explicit path found for host: ${host}`);
  } else {
    host = hostAndPath.substring(0, pathStartIndex);
    path = hostAndPath.substring(pathStartIndex);
    console.log(`Host is '${host}' and path is '${path}'`);
  }

  console.log(`Finished parsing. Host: ${host}, Path: ${path}.`);
  const result = { protocol: protocol, host: host, path: path };
  console.log(`Returning parsed object for URL: ${url}. Result: ${JSON.stringify(result)}`);
  return result;
}

