const clockAngle = (hours, minutes) => {
  console.log(`Calculating angle for ${hours} hours and ${minutes} minutes.`);

  let h = hours % 12; // Normalize hours to 0-11
  const m = minutes % 60; // Normalize minutes to 0-59

  console.log(`Normalized time: ${h}h ${m}m.`);

  // Calculate angle for the minute hand
  const minuteAngle = m * 6; // 360 degrees / 60 minutes = 6 degrees/minute
  console.log(`Minute hand angle: ${minuteAngle} degrees.`);

  // Calculate angle for the hour hand
  // Hour hand moves 360 degrees / 12 hours = 30 degrees/hour
  // It also moves an additional amount based on the minutes: 30 degrees/hour / 60 minutes/hour = 0.5 degrees/minute
  const hourAngle = (h * 30) + (m * 0.5);
  console.log(`Hour hand angle: ${hourAngle} degrees.`);

  // Calculate the absolute difference between the two angles
  let angleDifference = Math.abs(hourAngle - minuteAngle);
  console.log(`Absolute difference: ${angleDifference} degrees.`);

  // The smaller angle is either the difference or 360 - difference
  const smallerAngle = Math.min(angleDifference, 360 - angleDifference);
  console.log(`The smaller angle is ${smallerAngle} degrees.`);

  return smallerAngle;
};

