const memoize = (func) => {
  const cache = {};
  console.log(`Initializing memoizer for function: ${func.name || 'anonymous'}.`);

  return function(...args) {
    const key = JSON.stringify(args);
    console.log(`Checking cache for key: ${key}.`);

    if (cache[key]) {
      console.log(`Cache hit for arguments: ${args.join(', ')}.`);
      return cache[key];
    }

    console.log(`Cache miss for arguments: ${args.join(', ')}. Executing original function.`);
    const result = func.apply(this, args);
    cache[key] = result;
    console.log(`Caching result for key: ${key}.`);
    console.log(`Result for ${func.name || 'anonymous'} with args ${args.join(', ')} is ${result}.`);
    return result;
  };
};

