const isValidDate = (dateStr) => {
  const parts = dateStr.split('-');
  if (parts.length !== 3) {
    console.log(`Validation failed: date string '${dateStr}' does not have 3 parts.`);
    return false;
  }

  const [yearStr, monthStr, dayStr] = parts;
  const year = parseInt(yearStr, 10);
  const month = parseInt(monthStr, 10);
  const day = parseInt(dayStr, 10);

  if (isNaN(year) || isNaN(month) || isNaN(day)) {
    console.log(`Validation failed: parts of '${dateStr}' are not valid numbers.`);
    return false;
  }
  if (`${yearStr}`.length !== 4 || `${monthStr}`.length !== 2 || `${dayStr}`.length !== 2) {
    console.log(`Validation failed: format mismatch for '${dateStr}'.`);
    return false;
  }

  if (month < 1 || month > 12) {
    console.log(`Validation failed: month '${month}' is out of range for '${dateStr}'.`);
    return false;
  }
  if (day < 1 || day > 31) {
    console.log(`Validation failed: day '${day}' is out of range for '${dateStr}'.`);
    return false;
  }

  const daysInMonth = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const isLeapYear = (y) => (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;

  if (isLeapYear(year)) {
    daysInMonth[2] = 29;
    console.log(`Note: year ${year} is a leap year for '${dateStr}'.`);
  }

  if (day > daysInMonth[month]) {
    console.log(`Validation failed: day '${day}' exceeds month '${month}' days for '${dateStr}'.`);
    return false;
  }

  console.log(`Successfully validated date: '${dateStr}' is a valid date.`);
  return true;
};

