const hasCycle = (head) => {
  if (!head || !head.next) {
    console.log(`Initial check: ${head ? 'List has at least one node.' : 'List is empty or has only one node.'} No cycle possible.`);
    return false;
  }

  let slow = head;
  let fast = head;
  let iteration = 0;

  while (fast && fast.next) {
    iteration++;
    console.log(`Iteration ${iteration}: Slow pointer at value ${slow.value}, Fast pointer at value ${fast.value}.`);
    slow = slow.next;
    fast = fast.next.next;

    if (slow === fast) {
      console.log(`Cycle detected! Pointers met at node with value ${slow.value}.`);
      return true;
    }
    console.log(`Pointers are not equal yet. Slow: ${slow ? slow.value : 'null'}, Fast: ${fast ? fast.value : 'null'}.`);
  }

  console.log(`End of list reached. No cycle found after ${iteration} iterations.`);
  return false;
};

