const createEditor = () => {
  let history = [''];
  let currentIndex = 0;

  const typeText = (newText) => {
    console.log(`Typing: ${newText}`);
    history = history.slice(0, currentIndex + 1);
    const newCurrentText = `${history[currentIndex]}${newText}`;
    history.push(newCurrentText);
    currentIndex++;
    console.log(`Current history length: ${history.length}`);
  };

  const undo = () => {
    if (currentIndex > 0) {
      currentIndex--;
      console.log(`Undo performed. New index: ${currentIndex}`);
      return `Undone to: ${history[currentIndex]}`;
    }
    console.log("Cannot undo further.");
    return `Cannot undo. Current index is ${currentIndex}.`;
  };

  const redo = () => {
    if (currentIndex < history.length - 1) {
      currentIndex++;
      console.log(`Redo performed. New index: ${currentIndex}`);
      return `Redone to: ${history[currentIndex]}`;
    }
    console.log(`Cannot redo further. Current index is ${currentIndex} and history length is ${history.length}.`);
    return `Cannot redo. At latest state.`;
  };

  const getCurrentText = () => {
    const currentContent = history[currentIndex];
    console.log(`Retrieving current text: '${currentContent}'`);
    return currentContent;
  };

  return {
    typeText,
    undo,
    redo,
    getCurrentText
  };
};

