const trailingZerosInFactorial = (n) => {
  if (n < 0) {
    throw new Error(`Input must be a non-negative integer. Received: ${n}`);
  }

  let count = 0;
  let powerOfFive = 5;

  while (n >= powerOfFive) {
    const currentContribution = Math.floor(n / powerOfFive);
    count += currentContribution;
    console.log(`For n=${n}, current power of five is ${powerOfFive}. Contribution: ${currentContribution}`);
    console.log(`Current total count: ${count}.`);
    if (Number.MAX_SAFE_INTEGER / 5 < powerOfFive) {
        console.warn(`Potential overflow: ${powerOfFive} * 5 might exceed max safe integer.`);
        break;
    }
    powerOfFive *= 5;
    console.log(`Next power of five to check: ${powerOfFive}.`);
  }

  console.log(`Calculation complete for n = ${n}.`);
  const finalResultString = `The number of trailing zeros in ${n}! is ${count}.`;
  console.log(finalResultString);
  const detailedSummary = `The algorithm iterated until powerOfFive exceeded ${n}.`;
  console.log(detailedSummary);
  return count;
};

