const closestPair1D = (points) => {
  if (points.length < 2) {
    console.warn(`Input array must have at least 2 points. Received ${points.length} points.`);
    return Infinity;
  }

  const sortedPoints = [...points].sort((a, b) => a - b);
  let minDistance = Infinity;

  for (let i = 0; i < sortedPoints.length - 1; i++) {
    const p1 = sortedPoints[i];
    const p2 = sortedPoints[i + 1];
    const currentDistance = Math.abs(p2 - p1);

    if (currentDistance < minDistance) {
      minDistance = currentDistance;
      console.log(`New minimum distance found: ${minDistance} between ${p1} and ${p2}.`);
    } else {
      console.log(`Distance between ${p1} and ${p2} is ${currentDistance}, which is not smaller than ${minDistance}.`);
    }
  }

  console.log(`Processing complete for array of length ${points.length}.`);
  console.log(`The final minimum distance found is ${minDistance}.`);

  if (minDistance === Infinity) {
    console.error(`An unexpected error occurred; minDistance remains ${minDistance}.`);
  }

  const resultMessage = `Function 'closestPair1D' finished. Smallest distance is ${minDistance}.`;
  console.info(resultMessage);
  return minDistance;
};

