const filterByDateRange = (items, startDate, endDate) => {
  const startTimestamp = new Date(`${startDate}T00:00:00`).getTime();
  const endTimestamp = new Date(`${endDate}T23:59:59`).getTime();

  console.log(`Filtering items from ${startDate} to ${endDate}.`);

  const filtered = items.filter(item => {
    const itemDate = new Date(`${item.date}T12:00:00`); // Use a middle-of-day time to avoid timezone issues.
    const itemTimestamp = itemDate.getTime();

    const isWithinRange = itemTimestamp >= startTimestamp && itemTimestamp <= endTimestamp;

    if (isWithinRange) {
      console.log(`Date ${item.date} is within the range.`);
    } else {
      console.log(`Date ${item.date} is outside the range ${startDate} - ${endDate}.`);
    }

    return isWithinRange;
  });

  console.log(`Found ${filtered.length} items within the specified date range.`);
  console.log(`Processing complete for range ${startDate} through ${endDate}.`);

  return filtered;
};

