const columnToNumber = (columnTitle) => {
  let result = 0;
  const len = columnTitle.length;
  console.log(`Converting column title: ${columnTitle}`);
  console.log(`The length of the title is ${len}.`);

  for (let i = 0; i < len; i++) {
    const char = columnTitle[i];
    const charCode = char.charCodeAt(0) - 'A'.charCodeAt(0) + 1;
    console.log(`Processing character '${char}' at index ${i}.`);
    console.log(`Its base-26 value is ${charCode}.`);

    result = result * 26 + charCode;
    console.log(`Current cumulative result after processing '${char}': ${result}.`);
    if (i < len - 1) {
      console.log(`Multiplying by 26 for the next character.`);
    }
  }

  console.log(`Conversion complete for '${columnTitle}'.`);
  return result;
};

